const getOrCreateAdminDrawer = ({ selector, template } = {}) => {
  if (!selector || !template) return null;
  let drawer = document.querySelector(selector);
  if (drawer instanceof HTMLElement) {
    if (drawer.parentElement !== document.body) document.body.appendChild(drawer);
    return drawer;
  }
  const wrapper = document.createElement("div");
  wrapper.innerHTML = String(template).trim();
  drawer = wrapper.firstElementChild;
  if (!(drawer instanceof HTMLElement)) return null;
  document.body.appendChild(drawer);
  return drawer;
};

const getAdminStudentHistoryDrawer = () =>
  getOrCreateAdminDrawer({
    selector: "[data-admin-student-history-drawer]",
    template: ADMIN_STUDENT_HISTORY_DRAWER_TEMPLATE,
  });

const getAdminStudentHistoryTitle = () => {
  const drawer = getAdminStudentHistoryDrawer();
  return drawer instanceof HTMLElement ? drawer.querySelector("[data-admin-student-history-title]") : null;
};

const getAdminStudentHistorySub = () => {
  const drawer = getAdminStudentHistoryDrawer();
  return drawer instanceof HTMLElement ? drawer.querySelector("[data-admin-student-history-sub]") : null;
};

let adminStudentDrawerScrollLockY = 0;

const lockAdminStudentDrawerBackgroundScroll = () => {
  if (document.body.classList.contains("admin-student-drawer-open")) return;
  adminStudentDrawerScrollLockY = Math.max(window.scrollY || 0, window.pageYOffset || 0, 0);
  document.body.style.position = "fixed";
  document.body.style.top = `-${adminStudentDrawerScrollLockY}px`;
  document.body.style.left = "0";
  document.body.style.right = "0";
  document.body.style.width = "100%";
  document.body.classList.add("admin-student-drawer-open");
  document.documentElement.classList.add("admin-student-drawer-open");
};

const unlockAdminStudentDrawerBackgroundScroll = () => {
  const hadLock = document.body.classList.contains("admin-student-drawer-open");
  const restoreY = adminStudentDrawerScrollLockY;
  document.body.classList.remove("admin-student-drawer-open");
  document.documentElement.classList.remove("admin-student-drawer-open");
  document.body.style.position = "";
  document.body.style.top = "";
  document.body.style.left = "";
  document.body.style.right = "";
  document.body.style.width = "";
  adminStudentDrawerScrollLockY = 0;
  if (hadLock) window.scrollTo(0, restoreY);
};

const getAdminStudentSheet = () => {
  const drawer = getAdminStudentHistoryDrawer();
  return drawer instanceof HTMLElement ? drawer.querySelector("[data-admin-student-sheet]") : null;
};

const warnMissingAdminStudentHistoryDrawer = (context) => {
  console.warn("[admin] student history drawer unavailable", context);
};

const renderAdminStudentSheetLoadError = (error, fallbackMessage = "Não foi possível carregar a ficha do aluno.") => {
  const sheetEl = getAdminStudentSheet();
  const subEl = getAdminStudentHistorySub();
  const message =
    typeof error === "string"
      ? error
      : typeof error?.message === "string" && error.message
        ? error.message
        : fallbackMessage;
  console.error("[admin] student sheet render failed:", error);
  if (subEl instanceof HTMLElement) subEl.textContent = "Erro ao carregar";
  if (sheetEl instanceof HTMLElement) {
    sheetEl.innerHTML = `<div class="admin-student-simple-empty is-error">${escapeHtml(message)}</div>`;
  }
};

