const formatPedagogicoDate = (dateKey) => {
  const d = parseDateKey(dateKey);
  if (!d) return "—";
  return new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" }).format(d);
};

const formatPedagogicoGroupHeading = (dateKey) => {
  const date = parseDateKey(dateKey);
  if (!date) return "—";
  const weekday = new Intl.DateTimeFormat("pt-BR", { weekday: "long" }).format(date);
  const formatted = new Intl.DateTimeFormat("pt-BR", { day: "numeric", month: "long" }).format(date);
  const weekdayLabel = weekday.charAt(0).toUpperCase() + weekday.slice(1);
  return `${weekdayLabel}, ${formatted}`;
};

const formatPedagogicoCompactGroupHeading = (dateKey) => {
  const date = parseDateKey(dateKey);
  if (!date) return "—";
  const weekday = new Intl.DateTimeFormat("pt-BR", { weekday: "short" }).format(date).replace(/\./g, "");
  const formatted = new Intl.DateTimeFormat("pt-BR", { day: "numeric", month: "short" }).format(date).replace(/\./g, "");
  const weekdayLabel = weekday ? weekday.charAt(0).toUpperCase() + weekday.slice(1) : "";
  return `${weekdayLabel}, ${formatted}`;
};

const shiftDateKey = (dateKey, deltaDays) => {
  const date = parseDateKey(dateKey);
  if (!date) return "";
  date.setDate(date.getDate() + (Number(deltaDays) || 0));
  return dateKeyFromIso(date.toISOString());
};

const setPedagogicoPendingBadge = (count) => {
  const n = Math.max(0, Number(count) || 0);
  pedagogicoState.pendingCount = n;
  if (!(pedagogicoPendingBadge instanceof HTMLElement)) return;
  if (n <= 0) {
    pedagogicoPendingBadge.hidden = true;
    pedagogicoPendingBadge.textContent = "0";
    return;
  }
  pedagogicoPendingBadge.hidden = false;
  pedagogicoPendingBadge.textContent = String(n);
};

const setPedagogicoStatus = (text, tone = "") => {
  const targets = Array.from(document.querySelectorAll("[data-pedagogico-status]")).filter((el) => el instanceof HTMLElement);
  if (!targets.length && pedagogicoStatus instanceof HTMLElement) targets.push(pedagogicoStatus);
  const footerTarget = targets.find((el) => el instanceof HTMLElement && el.closest("[data-ped-footer]"));
  targets.forEach((el) => {
    if (!(el instanceof HTMLElement)) return;
    if (footerTarget && el !== footerTarget) {
      el.textContent = "";
      el.dataset.tone = "";
      return;
    }
    el.textContent = String(text || "");
    el.dataset.tone = String(tone || "");
  });
};

