const normalizeFinanceConversationId = (value) => {
  const raw = String(value || "").trim();
  if (!raw) return "";
  const match = raw.match(/\/conversations\/(\d+)(?:\D|$)/i);
  if (match) return match[1];
  return raw.replace(/\D+/g, "");
};

const financeStudentInitials = (value) => {
  const parts = String(value || "Aluno")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  return (parts[0]?.[0] || "A") + (parts.length > 1 ? parts[parts.length - 1][0] || "" : "");
};

const financeLocationFromPhone = (value) => {
  const digits = String(value || "").replace(/\D+/g, "");
  const br = digits.startsWith("55") ? digits.slice(2) : digits.length >= 10 ? digits : "";
  const ddd = br.slice(0, 2);
  const dddMap = {
    11: "São Paulo, SP",
    12: "Vale do Paraíba, SP",
    13: "Baixada Santista, SP",
    14: "Bauru/Marília, SP",
    15: "Sorocaba, SP",
    16: "Ribeirão Preto, SP",
    17: "São José do Rio Preto, SP",
    18: "Presidente Prudente, SP",
    19: "Campinas, SP",
    21: "Rio de Janeiro, RJ",
    22: "Norte Fluminense, RJ",
    24: "Sul Fluminense, RJ",
    27: "Vitória, ES",
    31: "Belo Horizonte, MG",
    41: "Curitiba, PR",
    47: "Joinville, SC",
    48: "Florianópolis, SC",
    51: "Porto Alegre, RS",
    61: "Brasília, DF",
    71: "Salvador, BA",
    81: "Recife, PE",
    85: "Fortaleza, CE",
    91: "Belém, PA",
  };
  if (digits.startsWith("55")) return dddMap[ddd] || "Brasil";
  if (digits.startsWith("1")) return "EUA/Canadá";
  if (digits.startsWith("351")) return "Portugal";
  if (digits.startsWith("44")) return "Reino Unido";
  if (digits.startsWith("34")) return "Espanha";
  return "Não informado";
};

const financeLocationForRow = (row) => {
  const direct =
    row?.localizacao ||
    row?.localização ||
    row?.cidade ||
    row?.city ||
    row?.estado ||
    row?.state ||
    row?.pais ||
    row?.país ||
    row?.country ||
    "";
  if (String(direct || "").trim()) return String(direct).trim();
  return financeLocationFromPhone(row?.telefone);
};

const formatFinanceMoney = (value) => {
  const n = Number(value);
  if (!Number.isFinite(n)) return "—";
  return n.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
};

const formatFinanceDate = (value) => {
  if (!value) return "—";
  try {
    const d = new Date(String(value));
    if (Number.isNaN(d.getTime())) return "—";
    return d.toLocaleDateString("pt-BR");
  } catch {
    return "—";
  }
};

const financeStatusLabel = (status) => {
  const raw = String(status || "").trim().toLowerCase();
  if (raw === "pago") return "Pago";
  if (raw === "vencido") return "Vencido";
  if (raw === "cancelado") return "Cancelado";
  return "Pendente";
};

const financeStatusTone = (status) => {
  const raw = String(status || "").trim().toLowerCase();
  if (raw === "pago") return "green";
  if (raw === "ativo") return "green";
  if (raw === "vencido") return "red";
  if (raw === "cancelado") return "gray";
  if (raw === "inativo") return "gray";
  return "yellow";
};

const financeAutomationReady = (row) => {
  const status = String(row?.status || "").trim().toLowerCase();
  const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
  return status === "ativo" && Boolean(conv);
};

const financeChatwootUrl = (conversationId) => {
  const id = normalizeFinanceConversationId(conversationId);
  return id ? `https://chatwoot.spaceschoolbr.com/app/accounts/1/conversations/${encodeURIComponent(id)}` : "";
};

const financeDateKey = (value) => {
  if (!value) return "";
  const date = value instanceof Date ? value : new Date(String(value));
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
  return createDateKey(date);
};

const financeDaysUntil = (value) => {
  if (!value) return null;
  const date = new Date(String(value));
  if (Number.isNaN(date.getTime())) return null;
  const today = new Date();
  const start = new Date(today.getFullYear(), today.getMonth(), today.getDate()).getTime();
  const due = new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
  return Math.round((due - start) / 86400000);
};

const financeMatchesSearch = (row, search = "") => {
  const q = String(search || "").trim().toLowerCase();
  if (!q) return true;
  return [
    row?.aluno_nome,
    row?.telefone,
    row?.email,
    row?.status,
    row?.forma_pagamento,
    row?.asaas_customer_id,
    row?.asaas_subscription_id,
    row?.id_conversa_chatwoot,
    row?.id_cobranca_externa,
  ]
    .filter(Boolean)
    .some((value) => String(value).toLowerCase().includes(q));
};

const financeOpenCharge = (charges = [], row = {}) => {
  const email = String(row?.email || "").trim().toLowerCase();
  const phone = String(row?.telefone || "").replace(/\D+/g, "");
  const name = String(row?.aluno_nome || "").trim().toLowerCase();
  return charges
    .filter((charge) => {
      const status = String(charge?.status || "").toLowerCase();
      if (status === "pago" || charge?.pago_em) return false;
      const cEmail = String(charge?.email || "").trim().toLowerCase();
      const cPhone = String(charge?.telefone || "").replace(/\D+/g, "");
      const cName = String(charge?.aluno_nome || "").trim().toLowerCase();
      return (email && cEmail === email) || (phone && cPhone === phone) || (name && cName === name);
    })
    .sort((a, b) => String(a?.vencimento || "").localeCompare(String(b?.vencimento || "")))[0];
};

const financeStudentOperationalStatus = (row, charges = []) => {
  const status = String(row?.status || "").trim().toLowerCase();
  const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
  const hasAsaas = Boolean(String(row?.asaas_customer_id || row?.asaas_subscription_id || "").trim());
  const phone = Boolean(String(row?.telefone || "").replace(/\D+/g, ""));
  const open = financeOpenCharge(charges, row);
  const hasInvoice = Boolean(String(open?.link_fatura || open?.link_boleto || "").trim());
  const issues = [];
  if (status !== "ativo") issues.push("inativo");
  if (!conv) issues.push("sem Chatwoot");
  if (!hasAsaas) issues.push("sem Asaas");
  if (!phone) issues.push("sem telefone");
  if (open && !hasInvoice) issues.push("sem link");
  return {
    ready: issues.length === 0,
    issues,
    openCharge: open,
    hasAsaas,
    hasChatwoot: Boolean(conv),
    hasPhone: phone,
    hasInvoice,
  };
};

const financePriorityItems = ({ alunos = [], cobrancas = [] } = {}) => {
  const items = [];
  cobrancas.forEach((row) => {
    const status = String(row?.status || "").toLowerCase();
    const paid = status === "pago" || row?.pago_em;
    const dueIn = financeDaysUntil(row?.vencimento);
    const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
    const invoice = String(row?.link_fatura || row?.link_boleto || "").trim();
    if (paid) return;
    if (status === "vencido" || (Number.isFinite(dueIn) && dueIn < 0)) {
      items.push({ tone: "red", title: row?.aluno_nome || "Cobrança vencida", detail: `${formatFinanceMoney(row?.valor)} vencida em ${formatFinanceDate(row?.vencimento)}`, row, kind: "cobranca" });
    } else if (Number.isFinite(dueIn) && dueIn <= 7) {
      items.push({ tone: "yellow", title: row?.aluno_nome || "Vence em breve", detail: `${formatFinanceMoney(row?.valor)} vence em ${dueIn} dia(s)`, row, kind: "cobranca" });
    }
    if (!conv) items.push({ tone: "blue", title: row?.aluno_nome || "Cobrança sem conversa", detail: "Vincular Chatwoot antes da automação", row, kind: "cobranca" });
    if (String(row?.forma_pagamento || "").toUpperCase() === "ASAAS" && !invoice) {
      items.push({ tone: "blue", title: row?.aluno_nome || "Cobrança sem link", detail: "Adicionar link Asaas/fatura", row, kind: "cobranca" });
    }
  });
  alunos.forEach((row) => {
    const ops = financeStudentOperationalStatus(row, cobrancas);
    if (String(row?.status || "").toLowerCase() === "ativo" && ops.issues.length) {
      items.push({ tone: ops.issues.includes("sem Chatwoot") ? "blue" : "yellow", title: row?.aluno_nome || "Aluno ativo incompleto", detail: ops.issues.join(", "), row, kind: "aluno" });
    }
  });
  return items.slice(0, 8);
};

const setFinanceStatus = (message, tone = "") => {
  const el = document.querySelector("[data-finance-status]");
  if (!(el instanceof HTMLElement)) return;
  el.textContent = String(message || "");
  el.dataset.tone = tone || "";
};

const ensureFinanceLoaded = async ({ force = false } = {}) => {
  if (!isFinanceAccessRole(currentRole)) return;
  if (!force && financeState.loadedAt && Date.now() - financeState.loadedAt < 30_000) return;

  financeState.loading = true;
  financeState.error = "";
  renderFinancePanel();

  try {
    const res = await fetchWithAuth("/api/financeiro-dashboard", { method: "GET" });
    const data = await res.json().catch(() => null);
    if (!res.ok) throw new Error(data?.error || "finance_load_failed");
    financeState.alunos = Array.isArray(data?.alunos) ? data.alunos : [];
    financeState.cobrancas = Array.isArray(data?.cobrancas) ? data.cobrancas : [];
    financeState.logs = Array.isArray(data?.logs) ? data.logs : [];
    financeState.eventos = Array.isArray(data?.eventos) ? data.eventos : [];
    financeState.pagamentos = Array.isArray(data?.pagamentos) ? data.pagamentos : [];
    financeState.errors = data?.errors && typeof data.errors === "object" ? data.errors : {};
    financeState.loadedAt = Date.now();
  } catch (error) {
    console.error("[finance] load panel failed:", error);
    financeState.error = "Não foi possível carregar o painel financeiro.";
  } finally {
    financeState.loading = false;
    renderFinancePanel();
  }
};

const financeErrorLabel = (key) => {
  if (key === "alunos") return "n8n_alunos_financeiro_space";
  if (key === "cobrancas") return "n8n_cobrancas_financeiras_space";
  if (key === "logs") return "n8n_logs_cobranca_space";
  if (key === "eventos") return "n8n_eventos_cobranca_space";
  if (key === "pagamentos") return "n8n_pagamentos_asaas_space";
  return key;
};

const financeErrorReason = (value) => {
  const err = value && typeof value === "object" ? value : { code: String(value || ""), message: String(value || "") };
  const code = String(err.code || "").trim();
  const message = String(err.message || "").trim();
  const status = Number(err.status || 0) || 0;
  const raw = `${code} ${message} ${err.details || ""} ${err.hint || ""}`.toLowerCase();
  if (code === "supabase_not_configured") return "Supabase não configurado no ambiente da Vercel.";
  if (status === 401 || status === 403 || raw.includes("permission denied") || raw.includes("rls")) {
    return "sem permissão no Supabase; use SUPABASE_SERVICE_ROLE_KEY no backend ou ajuste as políticas.";
  }
  if (status === 404 || raw.includes("could not find") || raw.includes("does not exist") || raw.includes("schema cache")) {
    return "tabela/coluna não encontrada no Supabase ou schema cache desatualizado.";
  }
  if (message) return message;
  if (code) return code;
  return "falha desconhecida.";
};

const renderFinanceTabs = () => {
  document.querySelectorAll("[data-finance-tab]").forEach((btn) => {
    if (!(btn instanceof HTMLButtonElement)) return;
    const tab = String(btn.getAttribute("data-finance-tab") || "");
    const active = tab === financeState.activeTab;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-selected", active ? "true" : "false");
  });
  document.querySelectorAll("[data-finance-table]").forEach((table) => {
    if (!(table instanceof HTMLElement)) return;
    table.hidden = String(table.getAttribute("data-finance-table") || "") !== financeState.activeTab;
  });
};

const financeBadgeHtml = (label, tone = "yellow") =>
  `<span class="admin-student-fin-status is-${escapeHtml(tone)}">${escapeHtml(label)}</span>`;

const financeReadyBadgeForAluno = (row) => {
  const status = String(row?.status || "").trim().toLowerCase();
  const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
  if (status !== "ativo") return financeBadgeHtml("Inativo", "gray");
  if (!conv) return `<span class="finance-missing">Sem Chatwoot</span>`;
  return `<span class="finance-ready">Pronto para cobrança</span>`;
};

const financeMonthKey = (value) => {
  const date = value ? new Date(String(value)) : null;
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return "";
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, "0")}`;
};

const financeMonthLabel = (key) => {
  const [year, month] = String(key || "").split("-").map((part) => Number(part));
  if (!year || !month) return "—";
  return new Date(year, month - 1, 1).toLocaleDateString("pt-BR", { month: "short" }).replace(".", "");
};

const renderFinanceDashboardHtml = ({ alunos, cobrancas, pagamentos, eventos, activeAlunos, pendingRows, paidRows, readyRows, withoutChatwoot, overdueTotal }) => {
  const paidValue = pagamentos.reduce((sum, row) => sum + (Number(row?.valor || 0) || 0), 0);
  const pendingValue = pendingRows.reduce((sum, row) => sum + (Number(row?.valor || 0) || 0), 0);
  const nextSevenRows = cobrancas.filter((row) => {
    const status = String(row?.status || "").toLowerCase();
    const dueIn = financeDaysUntil(row?.vencimento);
    return status !== "pago" && !row?.pago_em && Number.isFinite(dueIn) && dueIn >= 0 && dueIn <= 7;
  });
  const nextSevenValue = nextSevenRows.reduce((sum, row) => sum + (Number(row?.valor || 0) || 0), 0);
  const overdueRows = cobrancas.filter((row) => String(row?.status || "").toLowerCase() === "vencido" && !row?.pago_em);
  const delinquencyRate = cobrancas.length ? Math.round((overdueRows.length / cobrancas.length) * 100) : 0;
  const priorityItems = financePriorityItems({ alunos, cobrancas });
  const opsRows = activeAlunos.map((row) => ({ row, ops: financeStudentOperationalStatus(row, cobrancas) }));
  const readyOps = opsRows.filter((item) => item.ops.ready).length;
  const missingAsaas = opsRows.filter((item) => !item.ops.hasAsaas).length;
  const missingPhone = opsRows.filter((item) => !item.ops.hasPhone).length;
  const missingInvoice = opsRows.filter((item) => item.ops.openCharge && !item.ops.hasInvoice).length;
  const todayKey = createDateKey(new Date());
  const todayEvents = eventos.filter((row) => financeDateKey(row?.created_at) === todayKey);
  const monthKeys = [];
  const now = new Date();
  for (let i = 5; i >= 0; i -= 1) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    monthKeys.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
  }
  const revenueByMonth = Object.fromEntries(monthKeys.map((key) => [key, 0]));
  pagamentos.forEach((row) => {
    const key = financeMonthKey(row?.data_pagamento || row?.created_at || row?.vencimento);
    if (key in revenueByMonth) revenueByMonth[key] += Number(row?.valor || 0) || 0;
  });
  const maxRevenue = Math.max(1, ...Object.values(revenueByMonth));
  const statusCounts = cobrancas.reduce((acc, row) => {
    const status = String(row?.status || "sem status").toLowerCase();
    acc[status] = (acc[status] || 0) + 1;
    return acc;
  }, {});
  const locations = alunos.reduce((acc, row) => {
    const location = financeLocationForRow(row);
    acc[location] = (acc[location] || 0) + 1;
    return acc;
  }, {});
  const topLocations = Object.entries(locations).sort((a, b) => b[1] - a[1]).slice(0, 5);

  return `
    <section class="finance-dashboard-grid">
      <article class="finance-dashboard-panel finance-dashboard-panel-wide">
        <div class="finance-dashboard-panel-head">
          <div>
            <span>Performance</span>
            <strong>Evolução do faturamento</strong>
          </div>
          <b>${escapeHtml(formatFinanceMoney(paidValue))}</b>
        </div>
        <div class="finance-bar-chart" aria-label="Evolução do faturamento">
          ${monthKeys
            .map((key) => {
              const value = revenueByMonth[key] || 0;
              const height = Math.max(8, Math.round((value / maxRevenue) * 100));
              return `
                <div class="finance-bar-item">
                  <span>${escapeHtml(formatFinanceMoney(value))}</span>
                  <i style="height:${escapeHtml(String(height))}%"></i>
                  <small>${escapeHtml(financeMonthLabel(key))}</small>
                </div>
              `;
            })
            .join("")}
        </div>
      </article>

      <article class="finance-dashboard-panel">
        <div class="finance-dashboard-panel-head">
          <div><span>Carteira</span><strong>Operação atual</strong></div>
        </div>
        <div class="finance-dashboard-stack">
          <div><span>Alunos ativos</span><strong>${escapeHtml(String(activeAlunos.length))}</strong></div>
          <div><span>Aptos para cobrança</span><strong>${escapeHtml(String(readyRows.length))}</strong></div>
          <div><span>Sem conversa</span><strong>${escapeHtml(String(withoutChatwoot.length))}</strong></div>
        </div>
      </article>

      <article class="finance-dashboard-panel">
        <div class="finance-dashboard-panel-head">
          <div><span>Risco</span><strong>Cobranças abertas</strong></div>
        </div>
        <div class="finance-dashboard-stack">
          <div><span>Pendentes/vencidas</span><strong>${escapeHtml(String(pendingRows.length))}</strong></div>
          <div><span>Valor em aberto</span><strong>${escapeHtml(formatFinanceMoney(pendingValue))}</strong></div>
          <div><span>Total vencido</span><strong>${escapeHtml(formatFinanceMoney(overdueTotal))}</strong></div>
          <div><span>Inadimplência</span><strong>${escapeHtml(String(delinquencyRate))}%</strong></div>
        </div>
      </article>

      <article class="finance-dashboard-panel">
        <div class="finance-dashboard-panel-head">
          <div><span>Previsão</span><strong>Próximos 7 dias</strong></div>
        </div>
        <div class="finance-dashboard-big-number">
          <strong>${escapeHtml(formatFinanceMoney(nextSevenValue))}</strong>
          <span>${escapeHtml(String(nextSevenRows.length))} cobrança(s) próximas do vencimento</span>
        </div>
      </article>

      <article class="finance-dashboard-panel finance-dashboard-panel-map">
        <div class="finance-dashboard-panel-head">
          <div><span>Localização</span><strong>Alunos por região</strong></div>
        </div>
        <div class="finance-location-map">
          ${topLocations.length ? topLocations.map(([label, count]) => `<span>${escapeHtml(label)} <b>${escapeHtml(String(count))}</b></span>`).join("") : `<em>Sem localização disponível</em>`}
        </div>
      </article>

      <article class="finance-dashboard-panel finance-dashboard-panel-wide">
        <div class="finance-dashboard-panel-head">
          <div><span>Status</span><strong>Distribuição das cobranças</strong></div>
          <b>${escapeHtml(String(cobrancas.length))} total</b>
        </div>
        <div class="finance-status-bars">
          ${Object.entries(statusCounts)
            .map(([status, count]) => {
              const width = Math.max(8, Math.round((count / Math.max(1, cobrancas.length)) * 100));
              return `<div><span>${escapeHtml(status)}</span><i><b style="width:${escapeHtml(String(width))}%"></b></i><strong>${escapeHtml(String(count))}</strong></div>`;
            })
            .join("") || `<div><span>Sem cobranças</span><i><b style="width:0%"></b></i><strong>0</strong></div>`}
        </div>
      </article>

      <article class="finance-dashboard-panel">
        <div class="finance-dashboard-panel-head">
          <div><span>Automações</span><strong>Eventos hoje</strong></div>
        </div>
        <div class="finance-dashboard-big-number">
          <strong>${escapeHtml(String(todayEvents.length))}</strong>
          <span>${escapeHtml(String(eventos.length))} evento(s) no histórico carregado</span>
        </div>
      </article>

      <article class="finance-dashboard-panel finance-dashboard-panel-wide">
        <div class="finance-dashboard-panel-head">
          <div><span>Fila de cobrança</span><strong>Prioridade de hoje</strong></div>
          <b>${escapeHtml(String(priorityItems.length))} item(s)</b>
        </div>
        <div class="finance-priority-list">
          ${
            priorityItems.length
              ? priorityItems
                  .map(
                    (item) => `
                      <div class="finance-priority-item is-${escapeHtml(item.tone)}">
                        <span>${escapeHtml(item.kind === "aluno" ? "Aluno" : "Cobrança")}</span>
                        <strong>${escapeHtml(item.title)}</strong>
                        <small>${escapeHtml(item.detail)}</small>
                      </div>
                    `
                  )
                  .join("")
              : `<div class="finance-priority-empty">Nenhuma urgência encontrada agora.</div>`
          }
        </div>
      </article>

      <article class="finance-dashboard-panel">
        <div class="finance-dashboard-panel-head">
          <div><span>Checklist</span><strong>Status operacional</strong></div>
        </div>
        <div class="finance-ops-list">
          <div><span>Prontos</span><strong>${escapeHtml(String(readyOps))}</strong></div>
          <div><span>Sem Asaas</span><strong>${escapeHtml(String(missingAsaas))}</strong></div>
          <div><span>Sem telefone</span><strong>${escapeHtml(String(missingPhone))}</strong></div>
          <div><span>Cobrança sem link</span><strong>${escapeHtml(String(missingInvoice))}</strong></div>
        </div>
      </article>
    </section>
  `;
};

const renderFinancePanel = () => {
  const tables = {
    overview: document.querySelector('[data-finance-table="overview"]'),
    alunos: document.querySelector('[data-finance-table="alunos"]'),
    cobrancas: document.querySelector('[data-finance-table="cobrancas"]'),
    pagamentos: document.querySelector('[data-finance-table="pagamentos"]'),
    eventos: document.querySelector('[data-finance-table="eventos"]'),
    chatwoot: document.querySelector('[data-finance-table="chatwoot"]'),
  };
  const empty = document.querySelector("[data-finance-empty]");
  const summary = document.querySelector("[data-finance-summary]");
  if (!(tables.alunos instanceof HTMLElement)) return;
  const setTableHtml = (key, html) => {
    const table = tables[key];
    if (table instanceof HTMLElement) {
      table.innerHTML = html;
    }
  };

  const alunos = Array.isArray(financeState.alunos) ? financeState.alunos : [];
  const cobrancas = Array.isArray(financeState.cobrancas) ? financeState.cobrancas : [];
  const pagamentos = Array.isArray(financeState.pagamentos) ? financeState.pagamentos : [];
  const eventos = Array.isArray(financeState.eventos) ? financeState.eventos : [];
  const activeAlunos = alunos.filter((row) => String(row?.status || "").toLowerCase() === "ativo");
  const pendingRows = cobrancas.filter((row) => ["pendente", "vencido"].includes(String(row?.status || "").toLowerCase()) && !row?.pago_em);
  const paidRows = cobrancas.filter((row) => String(row?.status || "").toLowerCase() === "pago" || row?.pago_em);
  const readyRows = activeAlunos.filter(financeAutomationReady);
  const withoutChatwoot = activeAlunos.filter((row) => !normalizeFinanceConversationId(row?.id_conversa_chatwoot));
  const todayKey = createDateKey(new Date());
  const paidToday = pagamentos.filter((row) => financeDateKey(row?.created_at || row?.data_pagamento) === todayKey);
  const overdueTotal = cobrancas
    .filter((row) => String(row?.status || "").toLowerCase() === "vencido" && !row?.pago_em)
    .reduce((sum, row) => sum + (Number(row?.valor || 0) || 0), 0);

  if (summary instanceof HTMLElement) {
    summary.innerHTML = `
      <div class="finance-summary-card"><span>Alunos ativos</span><strong>${escapeHtml(String(activeAlunos.length))}</strong></div>
      <div class="finance-summary-card"><span>Pendentes/vencidas</span><strong>${escapeHtml(String(pendingRows.length))}</strong></div>
      <div class="finance-summary-card"><span>Pagas</span><strong>${escapeHtml(String(paidRows.length))}</strong></div>
      <div class="finance-summary-card"><span>Total vencido</span><strong>${escapeHtml(formatFinanceMoney(overdueTotal))}</strong></div>
      <div class="finance-summary-card"><span>Aptos para cobrança automática</span><strong>${escapeHtml(String(readyRows.length))}</strong></div>
      <div class="finance-summary-card"><span>Sem conversa vinculada</span><strong>${escapeHtml(String(withoutChatwoot.length))}</strong></div>
      <div class="finance-summary-card"><span>Pagamentos hoje</span><strong>${escapeHtml(String(paidToday.length))}</strong></div>
    `;
  }

  if (financeState.loading) {
    setFinanceStatus("Carregando dados financeiros...");
    Object.values(tables).forEach((table) => {
      if (table instanceof HTMLElement) table.innerHTML = "";
    });
    if (empty instanceof HTMLElement) empty.hidden = true;
    renderFinanceTabs();
    return;
  }

  if (financeState.error) {
    setFinanceStatus(financeState.error, "error");
    Object.values(tables).forEach((table) => {
      if (table instanceof HTMLElement) table.innerHTML = "";
    });
    if (empty instanceof HTMLElement) empty.hidden = true;
    renderFinanceTabs();
    return;
  }

  const errorEntries = Object.entries(financeState.errors || {});
  if (errorEntries.length) {
    const failed = errorEntries.map(([key, value]) => `${financeErrorLabel(key)} (${financeErrorReason(value)})`).join("; ");
    setFinanceStatus(`Algumas tabelas falharam ao carregar: ${failed}`, "error");
    console.error("[finance] tabelas com falha", financeState.errors);
  } else {
    setFinanceStatus(`${alunos.length} aluno(s), ${cobrancas.length} cobrança(s), ${pagamentos.length} pagamento(s), ${eventos.length} evento(s).`);
  }

  const search = String(financeState.filters.search || "");
  const alunoFilter = String(financeState.filters.alunos || "todos");
  const cobrancaFilter = String(financeState.filters.cobrancas || "todos");
  const filteredAlunos = alunos
    .filter((row) => financeMatchesSearch(row, search))
    .filter((row) => {
      const status = String(row?.status || "").toLowerCase();
      const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
      const ops = financeStudentOperationalStatus(row, cobrancas);
      if (alunoFilter === "ativos") return status === "ativo";
      if (alunoFilter === "sem_chatwoot") return status === "ativo" && !conv;
      if (alunoFilter === "sem_asaas") return status === "ativo" && !ops.hasAsaas;
      if (alunoFilter === "prontos") return status === "ativo" && ops.ready;
      if (alunoFilter === "inativos") return status !== "ativo";
      return true;
    });
  const filteredCobrancas = cobrancas
    .filter((row) => financeMatchesSearch(row, search))
    .filter((row) => {
      const status = String(row?.status || "").toLowerCase();
      const dueIn = financeDaysUntil(row?.vencimento);
      const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
      const invoice = String(row?.link_fatura || row?.link_boleto || "").trim();
      const paid = status === "pago" || row?.pago_em;
      if (cobrancaFilter === "abertas") return !paid;
      if (cobrancaFilter === "vencidas") return !paid && (status === "vencido" || (Number.isFinite(dueIn) && dueIn < 0));
      if (cobrancaFilter === "proximas") return !paid && Number.isFinite(dueIn) && dueIn >= 0 && dueIn <= 7;
      if (cobrancaFilter === "sem_chatwoot") return !conv;
      if (cobrancaFilter === "sem_link") return String(row?.forma_pagamento || "").toUpperCase() === "ASAAS" && !invoice;
      if (cobrancaFilter === "pagas") return paid;
      return true;
    });
  const renderFinanceFilters = (type) => `
    <div class="finance-filter-bar">
      <label>
        <span>Buscar</span>
        <input class="modal-input" value="${escapeHtml(search)}" placeholder="Nome, telefone, e-mail..." data-finance-filter-search />
      </label>
      ${
        type === "alunos"
          ? `<label><span>Filtro</span><select class="modal-input" data-finance-filter-alunos>
              <option value="todos" ${alunoFilter === "todos" ? "selected" : ""}>Todos</option>
              <option value="ativos" ${alunoFilter === "ativos" ? "selected" : ""}>Ativos</option>
              <option value="prontos" ${alunoFilter === "prontos" ? "selected" : ""}>Prontos para cobrança</option>
              <option value="sem_chatwoot" ${alunoFilter === "sem_chatwoot" ? "selected" : ""}>Sem Chatwoot</option>
              <option value="sem_asaas" ${alunoFilter === "sem_asaas" ? "selected" : ""}>Sem Asaas</option>
              <option value="inativos" ${alunoFilter === "inativos" ? "selected" : ""}>Inativos</option>
            </select></label>`
          : `<label><span>Filtro</span><select class="modal-input" data-finance-filter-cobrancas>
              <option value="todos" ${cobrancaFilter === "todos" ? "selected" : ""}>Todas</option>
              <option value="abertas" ${cobrancaFilter === "abertas" ? "selected" : ""}>Abertas</option>
              <option value="vencidas" ${cobrancaFilter === "vencidas" ? "selected" : ""}>Vencidas</option>
              <option value="proximas" ${cobrancaFilter === "proximas" ? "selected" : ""}>Próximos 7 dias</option>
              <option value="sem_chatwoot" ${cobrancaFilter === "sem_chatwoot" ? "selected" : ""}>Sem Chatwoot</option>
              <option value="sem_link" ${cobrancaFilter === "sem_link" ? "selected" : ""}>Asaas sem link</option>
              <option value="pagas" ${cobrancaFilter === "pagas" ? "selected" : ""}>Pagas</option>
            </select></label>`
      }
      <button type="button" class="admin-student-file-btn" data-finance-filter-clear>Limpar</button>
    </div>
  `;

  const currentRows =
    financeState.activeTab === "overview"
      ? alunos
      : financeState.activeTab === "alunos"
      ? filteredAlunos
      : financeState.activeTab === "cobrancas"
        ? filteredCobrancas
        : financeState.activeTab === "pagamentos"
          ? pagamentos
          : financeState.activeTab === "chatwoot"
            ? [...alunos, ...cobrancas].filter((row) => normalizeFinanceConversationId(row?.id_conversa_chatwoot))
            : eventos;
  if (empty instanceof HTMLElement) empty.hidden = currentRows.length > 0;

  const alunosTableHtml = filteredAlunos.length
    ? `
      ${renderFinanceFilters("alunos")}
      <div class="finance-row finance-head-row finance-row-alunos">
        <span>Aluno</span><span>Telefone</span><span>E-mail</span><span>Status</span><span>Asaas cliente</span><span>Assinatura</span><span>Operação</span><span>Chatwoot</span><span>Atualizado</span>
      </div>
      ${filteredAlunos
        .map((row) => {
          const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
          const chatUrl = row?.chatwoot_url || financeChatwootUrl(conv);
          const ops = financeStudentOperationalStatus(row, cobrancas);
          return `
            <div class="finance-row finance-row-alunos" data-finance-student-row="${escapeHtml(String(row?.id || ""))}">
              <span class="finance-student">${escapeHtml(row?.aluno_nome || "—")} ${financeReadyBadgeForAluno(row)}</span>
              <span>${escapeHtml(row?.telefone || "—")}</span>
              <span>${escapeHtml(row?.email || "—")}</span>
              <span>${financeBadgeHtml(row?.status || "—", financeStatusTone(row?.status))}</span>
              <span>${escapeHtml(row?.asaas_customer_id || "—")}</span>
              <span>${escapeHtml(row?.asaas_subscription_id || "—")}</span>
              <span>${ops.ready ? `<span class="finance-ready">OK</span>` : `<span class="finance-missing">${escapeHtml(ops.issues.join(", "))}</span>`}</span>
              <span class="admin-student-fin-actions">
                ${conv ? '<span class="finance-ready">Chatwoot vinculado</span>' : '<span class="finance-missing">Sem Chatwoot</span>'}
                ${
                  conv
                    ? `<button type="button" class="admin-student-file-btn" data-finance-chat-view="${escapeHtml(conv)}" data-finance-chat-source="aluno" data-finance-chat-row="${escapeHtml(
                        String(row?.id || "")
                      )}">Ver conversa</button><a class="admin-student-file-btn" href="${escapeHtml(chatUrl)}" target="_blank" rel="noopener">Abrir</a>`
                    : `<button type="button" class="admin-student-file-btn" data-finance-link-chat="aluno" data-finance-link-row="${escapeHtml(String(row?.id || ""))}">Vincular conversa</button>`
                }
              </span>
              <span>${escapeHtml(formatIsoToAdminStamp(row?.updated_at || row?.created_at))}</span>
            </div>
          `;
        })
        .join("")}
    `
    : alunos.length
      ? `${renderFinanceFilters("alunos")}<div class="finance-empty">Nenhum aluno encontrado com os filtros atuais.</div>`
    : "";
  setTableHtml(
    "overview",
    renderFinanceDashboardHtml({ alunos, cobrancas, pagamentos, eventos, activeAlunos, pendingRows, paidRows, readyRows, withoutChatwoot, overdueTotal })
  );
  setTableHtml("alunos", alunosTableHtml);

  setTableHtml(
    "cobrancas",
    filteredCobrancas.length
      ? `
      ${renderFinanceFilters("cobrancas")}
      <div class="finance-row finance-head-row finance-row-cobrancas">
        <span>Aluno</span><span>Valor</span><span>Vencimento</span><span>Prazo</span><span>Status</span><span>Forma</span><span>Fatura</span><span>Chatwoot</span><span>Pago em</span><span>Ações</span>
      </div>
      ${filteredCobrancas
        .map((row) => {
          const id = String(row?.id || "");
          const status = financeStatusLabel(row?.status);
          const value = formatFinanceMoney(row?.valor);
          const due = formatFinanceDate(row?.vencimento);
          const dueIn = financeDaysUntil(row?.vencimento);
          const dueLabel = Number.isFinite(dueIn) ? (dueIn < 0 ? `${Math.abs(dueIn)}d atrasada` : dueIn === 0 ? "vence hoje" : `${dueIn}d`) : "—";
          const method = String(row?.forma_pagamento || "—").trim() || "—";
          const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
          const chatUrl = row?.chatwoot_url || financeChatwootUrl(conv);
          const invoice = String(row?.link_fatura || "").trim();
          const isPaid = String(row?.status || "").toLowerCase() === "pago" || row?.pago_em;
          return `
            <div class="finance-row finance-row-cobrancas" data-finance-row="${escapeHtml(id)}">
              <span class="finance-student">${escapeHtml(row?.aluno_nome || row?.email || "—")}</span>
              <span>${escapeHtml(value)}</span>
              <span>${escapeHtml(due)}</span>
              <span>${escapeHtml(dueLabel)}</span>
              <span>${financeBadgeHtml(status, financeStatusTone(row?.status))}</span>
              <span>${escapeHtml(method)}</span>
              <span>${invoice ? `<a class="admin-student-file-btn" href="${escapeHtml(invoice)}" target="_blank" rel="noopener">Abrir fatura</a>` : "—"}</span>
              <span class="admin-student-fin-actions">
                ${conv ? '<span class="finance-ready">Chatwoot vinculado</span>' : '<span class="finance-missing">Sem Chatwoot</span>'}
                ${
                  conv
                    ? `<button type="button" class="admin-student-file-btn" data-finance-chat-view="${escapeHtml(conv)}" data-finance-chat-source="cobranca" data-finance-chat-row="${escapeHtml(
                        id
                      )}">Ver conversa</button><a class="admin-student-file-btn" href="${escapeHtml(chatUrl)}" target="_blank" rel="noopener">Abrir</a>`
                    : `<button type="button" class="admin-student-file-btn" data-finance-link-chat="cobranca" data-finance-link-row="${escapeHtml(id)}">Vincular conversa</button>`
                }
              </span>
              <span>${escapeHtml(formatIsoToAdminStamp(row?.pago_em))}</span>
              <span class="admin-student-fin-actions">
                <button type="button" class="admin-student-file-btn" data-finance-global-edit="${escapeHtml(id)}">Editar</button>
                <button type="button" class="admin-student-file-btn" data-finance-copy-link="${escapeHtml(invoice)}" ${invoice ? "" : "disabled"}>Copiar link</button>
                <button type="button" class="admin-student-file-btn" data-finance-global-confirm="${escapeHtml(id)}" ${isPaid ? "disabled" : ""}>Marcar pago</button>
              </span>
            </div>
          `;
        })
        .join("")}
    `
      : cobrancas.length
        ? `${renderFinanceFilters("cobrancas")}<div class="finance-empty">Nenhuma cobrança encontrada com os filtros atuais.</div>`
      : ""
  );

  setTableHtml(
    "pagamentos",
    pagamentos.length
      ? `
      <div class="finance-row finance-head-row finance-row-pagamentos">
        <span>Aluno</span><span>Valor</span><span>Vencimento</span><span>Pagamento</span><span>Status Asaas</span><span>Evento</span><span>ID pagamento</span><span>Cliente</span><span>Assinatura</span>
      </div>
      ${pagamentos
        .map(
          (row) => `
            <div class="finance-row finance-row-pagamentos">
              <span class="finance-student">${escapeHtml(row?.aluno_nome || "—")}</span>
              <span>${escapeHtml(formatFinanceMoney(row?.valor))}</span>
              <span>${escapeHtml(formatFinanceDate(row?.vencimento))}</span>
              <span>${escapeHtml(formatIsoToAdminStamp(row?.data_pagamento))}</span>
              <span>${financeBadgeHtml(row?.status_asaas || "—", financeStatusTone(row?.status_asaas))}</span>
              <span>${escapeHtml(row?.evento_asaas || "—")}</span>
              <span>${escapeHtml(row?.id_pagamento_asaas || "—")}</span>
              <span>${escapeHtml(row?.id_cliente_asaas || "—")}</span>
              <span>${escapeHtml(row?.id_assinatura_asaas || "—")}</span>
            </div>
          `
        )
        .join("")}
    `
      : ""
  );

  setTableHtml(
    "eventos",
    eventos.length
      ? `
      <div class="finance-row finance-head-row finance-row-eventos">
        <span>Aluno</span><span>Status evento</span><span>Tipo aviso</span><span>Valor</span><span>Vencimento</span><span>Motivo</span><span>Criado em</span>
      </div>
      ${eventos
        .map(
          (row) => `
            <div class="finance-row finance-row-eventos">
              <span class="finance-student">${escapeHtml(row?.aluno_nome || "—")}</span>
              <span>${financeBadgeHtml(row?.status_evento || "—", financeStatusTone(row?.status_evento))}</span>
              <span>${escapeHtml(row?.tipo_aviso || "—")}</span>
              <span>${escapeHtml(formatFinanceMoney(row?.valor))}</span>
              <span>${escapeHtml(formatFinanceDate(row?.vencimento))}</span>
              <span>${escapeHtml(row?.motivo || "—")}</span>
              <span>${escapeHtml(formatIsoToAdminStamp(row?.created_at))}</span>
            </div>
          `
        )
        .join("")}
    `
      : ""
  );

  const chatRows = [...alunos, ...cobrancas].filter((row) => normalizeFinanceConversationId(row?.id_conversa_chatwoot));
  const uniqueChatRows = Array.from(
    chatRows
      .reduce((map, row) => {
        const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
        if (!conv || map.has(conv)) return map;
        const source = financeState.alunos.some((item) => String(item?.id || "") === String(row?.id || "")) ? "aluno" : "cobranca";
        map.set(conv, { row, conv, source });
        return map;
      }, new Map())
      .values()
  );
  if (financeState.activeTab === "chatwoot" && uniqueChatRows.length) {
    const currentConv = normalizeFinanceConversationId(financeInlineChatState.conversationId);
    const currentExists = currentConv && uniqueChatRows.some((item) => item.conv === currentConv);
    if (!currentExists) {
      const first = uniqueChatRows[0];
      financeInlineChatState.conversationId = first.conv;
      financeInlineChatState.source = first.source;
      financeInlineChatState.row = first.row;
      financeInlineChatState.messages = [];
      financeInlineChatState.error = "";
      financeInlineChatState.isLoading = true;
      queueMicrotask(() => loadFinanceInlineChatMessages({ silent: false }).catch(() => {}));
    }
  }
  setTableHtml(
    "chatwoot",
    uniqueChatRows.length
      ? renderFinanceChatWorkspace(uniqueChatRows)
      : ""
  );

  renderFinanceTabs();
};

const ensureAdminStudentFinanceLoaded = async ({ force = false } = {}) => {
  const hist = adminStudentsState.history;
  const alunoId = String(hist?.alunoId || "").trim();
  if (!alunoId) return;
  if (!force && Array.isArray(hist?.financeRows) && hist.financeLoadedAt && Date.now() - hist.financeLoadedAt < 30_000) return;

  adminStudentsState.history.financeLoading = true;
  adminStudentsState.history.financeError = "";
  renderAdminStudentFinanceTab();

  try {
    const res = await fetchWithAuth(`/api/financeiro-cobrancas?aluno_id=${encodeURIComponent(alunoId)}`, { method: "GET" });
    const data = await res.json().catch(() => null);
    if (!res.ok) throw new Error(data?.error || "finance_load_failed");
    adminStudentsState.history.financeRows = Array.isArray(data?.rows) ? data.rows : [];
    adminStudentsState.history.financeLoadedAt = Date.now();
  } catch (error) {
    console.error("[finance] load charges failed:", error);
    adminStudentsState.history.financeError = "Não foi possível carregar dados financeiros agora.";
  } finally {
    adminStudentsState.history.financeLoading = false;
    renderAdminStudentFinanceTab();
  }
};

const renderAdminStudentFinanceTab = () => {
  const sheetEl = getAdminStudentSheet();
  if (!(sheetEl instanceof HTMLElement)) {
    console.warn("[admin] student sheet unavailable", "renderAdminStudentFinanceTab");
    return;
  }
  const panel = sheetEl.querySelector("[data-admin-student-finance]");
  if (!(panel instanceof HTMLElement)) return;

  const hist = adminStudentsState.history || {};
  const rows = Array.isArray(hist.financeRows) ? hist.financeRows : [];
  const loading = Boolean(hist.financeLoading);
  const errorMsg = String(hist.financeError || "");
  const alunoMeta = hist.alunoMeta || {};
  const monthly = alunoMeta?.valorMensalidade;
  const nextCharge = rows
    .filter((row) => String(row?.status || "").toLowerCase() !== "pago" && !row?.pago_em)
    .slice()
    .sort((a, b) => String(a?.vencimento || a?.data_vencimento || "").localeCompare(String(b?.vencimento || b?.data_vencimento || "")))[0];
  const overdueTotal = rows
    .filter((row) => String(row?.status || "").toLowerCase() === "vencido" && !row?.pago_em)
    .reduce((sum, row) => sum + (Number(row?.valor || row?.valor_cobranca || 0) || 0), 0);

  const rowsHtml = loading
    ? `<div class="admin-student-fin-table-empty">Carregando cobranças…</div>`
    : errorMsg
      ? `<div class="admin-student-fin-table-empty is-error">${escapeHtml(errorMsg)}</div>`
      : rows.length
        ? `<div class="admin-student-fin-table">
            <div class="admin-student-fin-row admin-student-fin-head">
              <span>Status</span><span>Valor</span><span>Vencimento</span><span>Forma</span><span>Chatwoot</span><span>Ações</span>
            </div>
            ${rows
              .map((row) => {
                const id = String(row?.id || "");
                const status = financeStatusLabel(row?.status);
                const tone = financeStatusTone(row?.status);
                const value = formatFinanceMoney(row?.valor ?? row?.valor_cobranca);
                const due = formatFinanceDate(row?.vencimento || row?.data_vencimento || row?.due_date);
                const method = String(row?.forma_pagamento || "—").trim() || "—";
                const conv = normalizeFinanceConversationId(row?.id_conversa_chatwoot);
                const chatUrl = row?.chatwoot_url || financeChatwootUrl(conv);
                return `
                  <div class="admin-student-fin-row" data-finance-row="${escapeHtml(id)}">
                    <span><span class="admin-student-fin-status is-${escapeHtml(tone)}">${escapeHtml(status)}</span></span>
                    <span>${escapeHtml(value)}</span>
                    <span>${escapeHtml(due)}</span>
                    <span>${escapeHtml(method)}</span>
                    <span>${conv ? escapeHtml(conv) : "—"}</span>
                    <span class="admin-student-fin-actions">
                      <button type="button" class="admin-student-file-btn" data-finance-edit="${escapeHtml(id)}">Editar</button>
                      <button type="button" class="admin-student-file-btn" data-finance-chat-view="${escapeHtml(conv)}" ${conv ? "" : "disabled"}>Ver conversa</button>
                      <a class="admin-student-file-btn" href="${escapeHtml(chatUrl || "#")}" target="_blank" rel="noopener" ${chatUrl ? "" : 'aria-disabled="true" tabindex="-1"'}>Abrir</a>
                      <button type="button" class="admin-student-file-btn" data-finance-confirm="${escapeHtml(id)}" ${
                        FINANCE_MANUAL_METHODS.includes(String(row?.forma_pagamento || "").toUpperCase()) && String(row?.status || "").toLowerCase() !== "pago"
                          ? ""
                          : "disabled"
                      }>Confirmar</button>
                    </span>
                  </div>
                `;
              })
              .join("")}
          </div>`
        : `<div class="admin-student-fin-table-empty">Nenhuma cobrança disponível.</div>`;

  panel.innerHTML = `
    <div class="admin-student-panel-card">
      <div class="admin-student-fin-headline">
        <div>
          <div class="admin-student-panel-title">Financeiro</div>
          <div class="admin-student-panel-note">Cobranças integradas ao n8n pela tabela Supabase.</div>
        </div>
        <button type="button" class="button button-solid button-small" data-finance-new>Nova cobrança</button>
      </div>
      <div class="admin-student-fin-grid">
        <div class="admin-student-fin-card"><span>Plano atual</span><strong>${escapeHtml(String(alunoMeta?.plano || "—"))}</strong></div>
        <div class="admin-student-fin-card"><span>Mensalidade</span><strong>${escapeHtml(formatFinanceMoney(monthly))}</strong></div>
        <div class="admin-student-fin-card"><span>Próxima cobrança</span><strong>${escapeHtml(nextCharge ? formatFinanceDate(nextCharge.vencimento || nextCharge.data_vencimento) : "—")}</strong></div>
        <div class="admin-student-fin-card"><span>Total inadimplente</span><strong>${escapeHtml(formatFinanceMoney(overdueTotal))}</strong></div>
      </div>
      ${rowsHtml}
    </div>
  `;
};

const readFinanceField = (key) => {
  const el = modalBody?.querySelector(`[data-finance-field="${CSS.escape(String(key))}"]`);
  if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement || el instanceof HTMLTextAreaElement) return String(el.value || "").trim();
  return "";
};

const openFinanceStudentModal = ({ row } = {}) => {
  const current = row && typeof row === "object" ? row : {};
  const isEdit = Boolean(current.id);
  openModal({
    title: isEdit ? "Editar aluno financeiro" : "Adicionar usuário",
    primaryLabel: "Salvar",
    secondaryLabel: "Cancelar",
    bodyHtml: `
      <div class="admin-student-fin-form">
        <label class="modal-field"><span>Nome do aluno</span><input class="modal-input" data-finance-field="aluno_nome" value="${escapeHtml(current.aluno_nome || "")}" /></label>
        <label class="modal-field"><span>Telefone</span><input class="modal-input" data-finance-field="telefone" value="${escapeHtml(current.telefone || "")}" /></label>
        <label class="modal-field"><span>E-mail</span><input class="modal-input" type="email" data-finance-field="email" value="${escapeHtml(current.email || "")}" /></label>
        <label class="modal-field"><span>Status</span><select class="modal-input" data-finance-field="status">
          <option value="ativo" ${String(current.status || "ativo").toLowerCase() === "ativo" ? "selected" : ""}>Ativo</option>
          <option value="inativo" ${String(current.status || "").toLowerCase() === "inativo" ? "selected" : ""}>Inativo</option>
        </select></label>
        <label class="modal-field"><span>Asaas customer ID</span><input class="modal-input" data-finance-field="asaas_customer_id" value="${escapeHtml(current.asaas_customer_id || "")}" /></label>
        <label class="modal-field"><span>Asaas subscription ID</span><input class="modal-input" data-finance-field="asaas_subscription_id" value="${escapeHtml(current.asaas_subscription_id || "")}" /></label>
        <label class="modal-field admin-student-field-wide"><span>ID conversa Chatwoot</span><input class="modal-input" data-finance-field="id_conversa_chatwoot" value="${escapeHtml(
          current.id_conversa_chatwoot || ""
        )}" placeholder="219" /></label>
        <div class="admin-student-files-inline-error" data-finance-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const errEl = modalBody?.querySelector("[data-finance-error]");
      const setErr = (msg) => {
        if (!(errEl instanceof HTMLElement)) return;
        errEl.textContent = String(msg || "");
        errEl.hidden = !msg;
      };
      const payload = {
        action: "save_aluno",
        id: current.id || "",
        aluno_nome: readFinanceField("aluno_nome"),
        telefone: readFinanceField("telefone"),
        email: readFinanceField("email"),
        asaas_customer_id: readFinanceField("asaas_customer_id"),
        asaas_subscription_id: readFinanceField("asaas_subscription_id"),
        id_conversa_chatwoot: readFinanceField("id_conversa_chatwoot"),
        status: readFinanceField("status"),
      };
      if (!payload.aluno_nome) {
        setErr("Informe o nome do aluno.");
        return false;
      }
      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Salvando...";
      (async () => {
        try {
          const res = await fetchWithAuth("/api/financeiro-dashboard", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
          });
          const data = await res.json().catch(() => null);
          if (!res.ok) throw new Error(data?.error || "save_failed");
          closeModal();
          await ensureFinanceLoaded({ force: true });
        } catch (error) {
          console.error("[finance] save student failed:", error);
          setErr("Não foi possível salvar o aluno financeiro.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || "Salvar";
        }
      })();
      return false;
    },
  });
};

