const createSalesCopilotExtensionToken = async () => {
  try {
    const res = await fetchWithAuth("/api/growth/copilot-vendas/realtime-token", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({}),
    });
    const data = await res.json().catch(() => null);
    if (!res.ok) throw new Error(data?.error || "token_failed");
    const token = String(data?.token || "");
    if (token) await navigator.clipboard?.writeText(token);
    setSalesCopilotStatus(token ? "Token da extensão copiado" : "Token gerado");
  } catch (error) {
    console.error("[growth copilot] extension token failed", error);
    setSalesCopilotStatus("Erro ao conectar extensão");
  }
};

const getAdminUsersUiRefs = (type) => {
  const safeType = type === "teacher" ? "teacher" : type === "growth" ? "growth" : "student";
  if (safeType === "teacher") {
    return { table: adminUsersTableTeacher, empty: adminUsersEmptyTeacher, error: adminUsersErrorTeacher };
  }
  if (safeType === "growth") {
    return { table: adminUsersTableGrowth, empty: adminUsersEmptyGrowth, error: adminUsersErrorGrowth };
  }
  return { table: adminUsersTableStudent, empty: adminUsersEmptyStudent, error: adminUsersErrorStudent };
};

const normalizeFirestoreRole = (value) => {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "teacher" || raw === "professor") return "teacher";
  if (raw === "student" || raw === "aluno") return "student";
  if (raw === "admin" || raw === "administrador") return "admin";
  if (raw === "growth") return "growth";
  if (raw === "finance" || raw === "financeiro") return "FINANCE";
  return "";
};

const normalizeFirestoreActive = (value) => {
  if (typeof value === "boolean") return value;
  return true;
};

const clonePlainData = (value) => {
  if (value == null) return value;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    return value;
  }
};

const normalizeUserRow = ({ id, nome, email, tipo, ativo, criadoEm }) => {
  const uid = String(id || "").trim();
  const name = String(nome || "").trim();
  const safeEmail = String(email || "").trim().toLowerCase();
  const role = normalizeFirestoreRole(tipo);
  if (!uid || !name || !safeEmail || !role) return null;
  return {
    id: uid,
    nome: name,
    email: safeEmail,
    tipo: role,
    ativo: normalizeFirestoreActive(ativo),
    criadoEm: criadoEm || null,
    initials: getInitials(name),
  };
};

const isPlainFirestorePatchObject = (value) => {
  if (!value || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
};

const sanitizeFirestorePatch = (value) => {
  if (Array.isArray(value)) {
    return value.map((item) => sanitizeFirestorePatch(item)).filter((item) => item !== undefined);
  }
  if (!isPlainFirestorePatchObject(value)) {
    return value === undefined ? undefined : value;
  }
  return Object.fromEntries(
    Object.entries(value)
      .map(([key, entryValue]) => [key, sanitizeFirestorePatch(entryValue)])
      .filter(([, entryValue]) => entryValue !== undefined)
  );
};

const USER_PATCH_PROTECTED_FIELDS = new Set(["cancelamento", "cancelamentosAnteriores", "historicoPedagogico", "comentarios"]);

const warnIfSuspiciousUserPatch = (patch, { context = "users_patch", allowProtectedFields = [] } = {}) => {
  const host = typeof window !== "undefined" ? String(window.location.hostname || "").trim().toLowerCase() : "";
  const isDevHost = host === "localhost" || host === "127.0.0.1" || host.endsWith(".local");
  if (!isDevHost || !patch || typeof patch !== "object") return;
  const allowed = new Set((Array.isArray(allowProtectedFields) ? allowProtectedFields : []).map((item) => String(item || "").trim()));
  const suspicious = Object.keys(patch).filter((key) => USER_PATCH_PROTECTED_FIELDS.has(key) && !allowed.has(key));
  if (!suspicious.length) return;
  console.warn(`[users patch] ${context} enviou campos protegidos: ${suspicious.join(", ")}`, patch);
};

const patchFirestoreUserDocument = async ({ userId, patch = {}, context = "users_patch", allowProtectedFields = [] } = {}) => {
  const id = String(userId || "").trim();
  if (!id) throw new Error("missing_user_id");
  const cleanPatch = sanitizeFirestorePatch(patch || {});
  if (!cleanPatch || typeof cleanPatch !== "object" || !Object.keys(cleanPatch).length) {
    throw new Error("empty_user_patch");
  }
  warnIfSuspiciousUserPatch(cleanPatch, { context, allowProtectedFields });
  const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, `firebase_init_${context}`);
  const user = await waitForFirebaseAuthReady(firebase, 5000);
  if (!user) throw new Error("not_authenticated");
  await withTimeout(
    firebase.setDoc(firebase.doc(firebase.primaryDb, "users", id), cleanPatch, { merge: true }),
    12_000,
    `firestore_${context}`
  );
  fetchWithAuth("/api/admin-users", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ uid: id, role: String(cleanPatch?.tipo || "").trim(), name: String(cleanPatch?.nome || "").trim(), action: "sync_mirror" }),
  }).catch((error) => {
    console.warn("[ownership] mirror sync request failed", {
      userId: id,
      context,
      message: error?.message || error,
    });
  });
  return { firebase, cleanPatch };
};

const getStudentIdentityAliases = (student = {}) => {
  const aliases = new Set();
  [student?.firestoreDocId, student?.firestoreDocIdRef, student?.docId, student?.documentId, student?.id, student?.uid, student?.userId, student?.studentId, student?.alunoId, student?.aluno_chave].forEach(
    (value) => {
      const safe = String(value || "").trim();
      if (safe) aliases.add(safe);
    }
  );
  return Array.from(aliases);
};

const buildStudentAliasMap = (students = []) => {
  const aliasToDocId = new Map();
  (Array.isArray(students) ? students : []).forEach((student) => {
    if (!student || typeof student !== "object") return;
    const canonicalId = String(student.firestoreDocId || student.docId || student.documentId || "").trim();
    if (!canonicalId) return;
    getStudentIdentityAliases(student).forEach((alias) => aliasToDocId.set(alias, canonicalId));
  });
  return aliasToDocId;
};

const resolveStudentCanonicalDocId = (studentOrId, { aliasMap = null } = {}) => {
  if (studentOrId && typeof studentOrId === "object") {
    const direct = String(studentOrId.firestoreDocId || studentOrId.docId || studentOrId.documentId || "").trim();
    if (direct) return direct;
    const maybeAlias = String(studentOrId.id || studentOrId.uid || studentOrId.userId || studentOrId.studentId || studentOrId.alunoId || "").trim();
    if (maybeAlias && aliasMap instanceof Map) {
      const resolved = String(aliasMap.get(maybeAlias) || "").trim();
      if (resolved) return resolved;
    }
    throw new Error("student_firestore_document_id_missing");
  }
  const raw = String(studentOrId || "").trim();
  if (!raw) throw new Error("student_firestore_document_id_missing");
  if (aliasMap instanceof Map) {
    const resolved = String(aliasMap.get(raw) || "").trim();
    if (resolved) return resolved;
  }
  return raw;
};

const normalizeAdminFirestoreUserRow = (sourceRow = {}) => {
  if (!sourceRow || typeof sourceRow !== "object") return null;
  const raw = clonePlainData(sourceRow);
  const firestoreDocId = String(sourceRow.firestoreDocId || sourceRow.docId || sourceRow.documentId || "").trim();
  const uid = firestoreDocId;
  const nome = String(sourceRow.nome || sourceRow.nomeCompleto || sourceRow.fullName || sourceRow.displayName || sourceRow.name || sourceRow.email || "Aluno sem nome").trim();
  const email = String(sourceRow.email || "").trim().toLowerCase();
  const tipo = normalizeFirestoreRole(sourceRow.tipo || sourceRow.role || sourceRow.type) || "student";
  if (!uid || !nome) return null;
  const sourceBusinessId = String(raw?.id || raw?.uid || raw?.userId || raw?.studentId || raw?.alunoId || "").trim();
  const createdAt = raw?.criadoEm || raw?.createdAt || raw?.created_at || raw?.cadastroEm || null;
  const canceladoEm = raw?.canceladoEm || raw?.cancelamentoEm || raw?.dataCancelamento || null;
  const desativadoEm = raw?.desativadoEm || canceladoEm || null;
  const professorId = String(raw?.professorId || raw?.teacherId || raw?.teacher_id || "").trim();
  const professorNome = String(raw?.professorNome || raw?.teacherNome || raw?.teacherName || "").trim();
  const especialidade = String(raw?.especialidade || raw?.specialty || raw?.nivelLeciona || "").trim();
  const englishLevelStart = String(raw?.english_level_start || raw?.englishLevelStart || "").trim();
  const observacoesPedagogicas = String(raw?.observacoesPedagogicas || raw?.notes || "").trim();
  const telefone = String(raw?.telefone || raw?.phone || raw?.telefoneWhatsapp || "").trim();
  return {
    ...raw,
    id: uid,
    firestoreDocId: uid,
    docId: uid,
    documentId: uid,
    sourceBusinessId,
    uid: String(raw?.uid || "").trim(),
    userId: String(raw?.userId || sourceBusinessId || "").trim(),
    studentId: String(raw?.studentId || sourceBusinessId || "").trim(),
    alunoId: String(raw?.alunoId || sourceBusinessId || "").trim(),
    nome,
    email,
    firestoreNome: nome,
    firestoreEmail: email,
    tipo,
    firestoreTipo: tipo,
    ativo: normalizeFirestoreActive(sourceRow.ativo),
    firestoreAtivo: normalizeFirestoreActive(sourceRow.ativo),
    criadoEm: createdAt,
    initials: getInitials(nome),
    professorId,
    teacherId: String(raw?.teacherId || professorId).trim(),
    professorNome,
    firestoreProfessorNome: professorNome,
    teacherNome: String(raw?.teacherNome || professorNome).trim(),
    firestoreProfessorId: professorId,
    turma: String(raw?.turma || raw?.turmaNome || raw?.groupName || raw?.className || "").trim(),
    groupId: String(raw?.groupId || raw?.classId || "").trim(),
    plano: String(raw?.plano || raw?.plan || "").trim(),
    firestorePlano: String(raw?.plano || raw?.plan || "").trim(),
    telefone,
    firestoreTelefone: telefone,
    pais: String(raw?.pais || raw?.country || "").trim(),
    endereco: String(raw?.endereco || raw?.address || "").trim(),
    estadoEua: String(raw?.estadoEua || raw?.estadoEUA || raw?.usState || "").trim(),
    valorMensalidade: Number.isFinite(Number(raw?.valorMensalidade)) ? Number(raw.valorMensalidade) : raw?.valorMensalidade ?? null,
    tempoContrato:
      typeof raw?.tempoContrato === "string" ? raw.tempoContrato : Number.isFinite(Number(raw?.tempoContrato)) ? String(Number(raw.tempoContrato)) : "",
    faixaIdade: String(raw?.faixaIdade || "").trim(),
    genero: String(raw?.genero || "").trim(),
    trabalho: String(raw?.trabalho || "").trim(),
    possuiFilhos:
      typeof raw?.possuiFilhos === "string" ? raw.possuiFilhos : typeof raw?.possuiFilhos === "boolean" ? (raw.possuiFilhos ? "sim" : "nao") : "",
    casado: typeof raw?.casado === "string" ? raw.casado : typeof raw?.casado === "boolean" ? (raw.casado ? "sim" : "nao") : "",
    pretendeVoltarBrasil: String(raw?.pretendeVoltarBrasil || "").trim(),
    objetivoPrincipal: String(raw?.objetivoPrincipal || "").trim(),
    nivelInglesAtual: String(raw?.nivelInglesAtual || "").trim(),
    english_level_start: englishLevelStart,
    englishLevelStart,
    photoURL: String(raw?.photoURL || raw?.photoUrl || "").trim(),
    especialidade,
    specialty: especialidade,
    observacoesPedagogicas,
    cancelamento: raw?.cancelamento ?? null,
    firestoreCancelamento: raw?.cancelamento ?? null,
    cancelamentosAnteriores: Array.isArray(raw?.cancelamentosAnteriores) ? raw.cancelamentosAnteriores : [],
    firestoreCancelamentosAnteriores: Array.isArray(raw?.cancelamentosAnteriores) ? raw.cancelamentosAnteriores : [],
    canceladoEm,
    desativadoEm,
    criadoKey: toDateKeyFromAny(createdAt),
    cancelKey: toDateKeyFromAny(canceladoEm),
    desativadoKey: toDateKeyFromAny(desativadoEm),
    source: raw?.source || "firestore",
  };
};

const loadUsersFromFirestore = async (type) => {
  const safeType = type === "teacher" ? "teacher" : type === "growth" ? "growth" : "student";
  const state = adminUsersState[safeType];
  if (state.isLoading) return;

  state.isLoading = true;
  state.error = "";
  setAdminManageStatus(safeType, "Carregando…");

  const { table, empty, error } = getAdminUsersUiRefs(safeType);
  if (error instanceof HTMLElement) error.hidden = true;

  try {
    const rows = await withTimeout(fetchUserRowsFromFirestore(safeType), 15_000, `admin_users_${safeType}`);
    state.rows = Array.isArray(rows) ? rows.filter(Boolean).sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR")) : [];
    state.loadedAt = Date.now();
    setAdminManageStatus(safeType, "");
    renderAdminUsersTable(safeType);
    if (currentRole === "admin" && activeModalKind === "event-form") {
      syncAdminEventUserSelects();
      validateCreateEventDraft();
    }
  } catch (err) {
    // Surface the root cause for debugging (rules, connectivity, etc.).
    console.error("[admin] loadUsersFromFirestore failed:", safeType, err);
    state.error = typeof err?.message === "string" && err.message ? err.message : "Não foi possível carregar a lista, tente novamente.";
    if (table instanceof HTMLElement) table.innerHTML = "";
    if (empty instanceof HTMLElement) empty.hidden = true;
    if (error instanceof HTMLElement) error.hidden = false;
    const code = typeof err?.code === "string" ? err.code : "";
    let message = "Não foi possível carregar.";
    if (code === "timeout") message = "Tempo esgotado ao carregar. Tente novamente.";
    if (code === "auth/no-current-user") message = "Sessão expirada. Faça login novamente.";
    setAdminManageStatus(safeType, message, "error");
  } finally {
    state.isLoading = false;
    if (currentRole === "admin" && activeModalKind === "event-form") {
      syncAdminEventUserSelects();
      validateCreateEventDraft();
    }
  }
};

const syncTeacherStatusFilterTabs = () => {
  const filter = adminUsersState?.teacher?.statusFilter === "inactive" ? "inactive" : "active";
  document.querySelectorAll("[data-admin-teacher-filter]").forEach((el) => {
    if (!(el instanceof HTMLButtonElement)) return;
    const value = String(el.getAttribute("data-admin-teacher-filter") || "").trim().toLowerCase();
    const isActive = value === filter;
    el.classList.toggle("is-active", isActive);
    el.setAttribute("aria-selected", isActive ? "true" : "false");
  });
};

const setTeacherStatusFilter = (nextFilter) => {
  const filter = String(nextFilter || "").trim().toLowerCase() === "inactive" ? "inactive" : "active";
  adminUsersState.teacher.statusFilter = filter;
  renderAdminUsersTable("teacher");
};

const renderAdminUsersTable = (type) => {
  const safeType = type === "teacher" ? "teacher" : type === "growth" ? "growth" : "student";
  const state = adminUsersState[safeType];
  const { table, empty, error } = getAdminUsersUiRefs(safeType);
  if (!(table instanceof HTMLElement)) return;
  if (error instanceof HTMLElement) error.hidden = true;

  const q = String(state.query || "").trim().toLowerCase();
  let filtered = q
    ? state.rows.filter((row) => row.nome.toLowerCase().includes(q) || row.email.toLowerCase().includes(q))
    : state.rows;

  if (safeType === "teacher") {
    const filter = state.statusFilter === "inactive" ? "inactive" : "active";
    filtered = filtered.filter((row) => (filter === "active" ? row.ativo : !row.ativo));
    syncTeacherStatusFilterTabs();
  }

  if (empty instanceof HTMLElement) empty.hidden = filtered.length > 0;
  table.innerHTML = `
    <div class="admin-users-row admin-users-head">
      <span> </span>
      <span>Nome</span>
      <span>E-mail</span>
      <span>Status</span>
      <span>Cadastro</span>
      <span> </span>
    </div>
    ${filtered
      .map((row) => {
        const badgeClass = row.ativo ? "admin-badge is-active" : "admin-badge is-inactive";
        const badgeLabel = row.ativo ? "Ativo" : "Inativo";
        return `
          <div class="admin-users-row" data-admin-user-row="${escapeHtml(row.id)}" data-admin-user-email="${escapeHtml(
          row.email
        )}" data-admin-user-name="${escapeHtml(row.nome)}" data-admin-user-active="${row.ativo ? "1" : "0"}">
            <div class="admin-user-avatar" aria-hidden="true">${escapeHtml(row.initials)}</div>
            <div class="admin-user-name">${escapeHtml(row.nome)}</div>
            <div class="admin-user-email">${escapeHtml(row.email)}</div>
            <div><span class="${badgeClass}">${badgeLabel}</span></div>
            <div class="admin-user-date">${escapeHtml(formatAdminDate(row.criadoEm))}</div>
            <div class="admin-row-actions" data-admin-actions>
              <button class="admin-actions-trigger" type="button" aria-label="Ações" data-admin-actions-trigger>
                <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M6.5 12h.01"></path>
                  <path d="M12 12h.01"></path>
                  <path d="M17.5 12h.01"></path>
                </svg>
              </button>
              <div class="admin-actions-menu" role="menu" aria-label="Ações do usuário">
                <button class="admin-action-item${row.ativo ? " is-danger" : ""}" type="button" data-admin-action-toggle>
                  ${row.ativo ? "Desativar" : "Ativar"}
                </button>
                <button class="admin-action-item" type="button" data-admin-action-reset>
                  Redefinir senha
                </button>
              </div>
            </div>
          </div>
        `;
      })
      .join("")}
  `;
};

const fetchUserRowsFromFirestore = async (tipo) => {
  const safeTipo = tipo === "teacher" ? "teacher" : tipo === "growth" ? "growth" : "student";
  const roleAliases =
    safeTipo === "student"
      ? ["student", "aluno"]
      : safeTipo === "teacher"
        ? ["teacher", "professor"]
        : safeTipo === "FINANCE"
          ? ["finance", "financeiro"]
          : [safeTipo];
  let sourceRows = null;
  if (currentRole === "admin") {
    const response = await fetchWithAuth(`/api/admin-data?collection=users&type=${encodeURIComponent(safeTipo)}${safeTipo === "student" ? "&debug=1" : ""}`);
    if (response.ok) {
      const payload = await response.json().catch(() => null);
      sourceRows = Array.isArray(payload?.rows) ? payload.rows : [];
      if (safeTipo === "student") {
        const focusIds = ["kkeegmFko4Xi0wigwpXLDG0Bo5E3", "qsZScLZ3NpXnqKB3lIISldK97cL2"];
        console.warn("[ownership] admin-data student payload", {
          totalRows: sourceRows.length,
          focused: focusIds.map((id) => ({
            id,
            present: sourceRows.some((row) => String(row?.firestoreDocId || row?.id || "").trim() === id),
            row:
              sourceRows.find((row) => String(row?.firestoreDocId || row?.id || "").trim() === id) || null,
          })),
          debug: payload?.debug || null,
        });
      }
    }
  }

  if (!sourceRows) {
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_students");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) {
      const e = new Error("firebase_not_authenticated");
      e.code = "auth/no-current-user";
      throw e;
    }
    const usersCollection = firebase.collection(firebase.primaryDb, "users");
    const snapshots = await Promise.all(
      roleAliases.map((alias) => {
        const q = firebase.query(usersCollection, firebase.where("tipo", "==", alias));
        return withTimeout(firebase.getDocs(q), 12_000, `firestore_getDocs_users_${safeTipo}_${alias}`);
      })
    );
    const byId = new Map();
    snapshots.forEach((snap) => {
      snap.forEach((docSnap) => {
        const data = docSnap.data ? docSnap.data() : {};
        byId.set(docSnap.id, {
          ...data,
          id: typeof data?.id === "string" && data.id.trim() ? data.id : docSnap.id,
          firestoreDocId: docSnap.id,
        });
      });
    });
    sourceRows = Array.from(byId.values());
  }

  const rows = [];
  sourceRows.forEach((sourceRow) => {
    const normalized = normalizeAdminFirestoreUserRow(sourceRow);
    if (normalized) rows.push(normalized);
  });
  return rows.filter(Boolean).sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));
};

