const fetchLessonLogsFromFirestore = async () => {
  try {
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_lessonlogs");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) {
      const e = new Error("firebase_not_authenticated");
      e.code = "auth/no-current-user";
      throw e;
    }

    const q = firebase.query(firebase.collection(firebase.primaryDb, "lessonLogs"));
    const snap = await withTimeout(firebase.getDocs(q), 12_000, "firestore_getDocs_lessonLogs_all");
    const logs = [];
    snap.forEach((docSnap) => {
      const data = docSnap.data ? docSnap.data() : null;
      if (!data || typeof data !== "object") return;
      const eventId = typeof data.eventId === "string" ? data.eventId.trim() : "";
      const professorId = typeof data.professorId === "string" ? data.professorId.trim() : "";
      const alunoId = typeof data.alunoId === "string" ? data.alunoId.trim() : "";
      const statusAula = typeof data.statusAula === "string" ? data.statusAula.trim().toLowerCase() : "";
      if (!eventId) return;
      logs.push({
        id: docSnap.id,
        eventId,
        professorId,
        alunoId,
        dateKey: typeof data.dateKey === "string" ? data.dateKey.trim() : "",
        statusAula,
        criadoEm: data.criadoEm ? (typeof data.criadoEm?.toDate === "function" ? data.criadoEm.toDate().toISOString() : String(data.criadoEm)) : "",
        atualizadoEm: data.atualizadoEm ? (typeof data.atualizadoEm?.toDate === "function" ? data.atualizadoEm.toDate().toISOString() : String(data.atualizadoEm)) : "",
        payload: data,
      });
    });

    // newest first to make "last" lookups cheap.
    logs.sort((a, b) => {
      const ak = String(a.dateKey || "");
      const bk = String(b.dateKey || "");
      if (ak !== bk) return bk.localeCompare(ak);
      const ams = a.atualizadoEm ? Date.parse(a.atualizadoEm) : NaN;
      const bms = b.atualizadoEm ? Date.parse(b.atualizadoEm) : NaN;
      if (Number.isFinite(ams) && Number.isFinite(bms)) return bms - ams;
      return 0;
    });

    return logs;
  } catch (error) {
    console.warn("[admin] fetchLessonLogsFromFirestore falling back to admin-data:", error?.message || error);
    const response = await fetchWithAuth("/api/admin-data?collection=lessonLogs", { method: "GET" });
    if (!response.ok) return [];
    const payload = await response.json().catch(() => null);
    const rows = Array.isArray(payload?.rows) ? payload.rows : [];
    return rows
      .map((row) => {
        const eventId = typeof row.eventId === "string" ? row.eventId.trim() : "";
        if (!eventId) return null;
        return {
          id: String(row.id || "").trim(),
          eventId,
          professorId: typeof row.professorId === "string" ? row.professorId.trim() : "",
          alunoId: typeof row.alunoId === "string" ? row.alunoId.trim() : "",
          dateKey: typeof row.dateKey === "string" ? row.dateKey.trim() : "",
          statusAula: typeof row.statusAula === "string" ? row.statusAula.trim().toLowerCase() : "",
          criadoEm: row.criadoEm || row.createdAt || "",
          atualizadoEm: row.atualizadoEm || row.updatedAt || "",
          payload: row,
        };
      })
      .filter(Boolean);
  }
};

const STUDENT_LIFECYCLE_STATE = {
  ACTIVE: "ativo",
  NOTICE: "em_aviso",
  SUSPENDED: "suspenso",
  INACTIVE: "inativo",
};

const STUDENT_CANCELLATION_REASON_OPTIONS = [
  "Preço",
  "Falta de tempo",
  "Insatisfação com professor",
  "Insatisfação com método",
  "Mudança de vida (viagem, trabalho...)",
  "Conseguiu objetivo",
  "Outro",
];

const RETENTION_THRESHOLDS = {
  pagamentoVencidaCriticaDias: 7,
  frequenciaAusenteCriticaDias: 14,
};

const isStudentCancellationActive = (cancelamento) =>
  Boolean(cancelamento && typeof cancelamento === "object" && !cancelamento.desfecho);

const toLifecycleMs = (value) => parseFirestoreDateToMs(value);

const toLifecycleDate = (value) => {
  const ms = toLifecycleMs(value);
  return Number.isFinite(ms) && ms > 0 ? new Date(ms) : null;
};

const addMonthsPreservingDay = (date, months) => {
  const base = date instanceof Date ? new Date(date.getTime()) : new Date();
  const originalDay = base.getDate();
  const copy = new Date(base.getTime());
  copy.setDate(1);
  copy.setMonth(copy.getMonth() + Number(months || 0));
  const lastDay = new Date(copy.getFullYear(), copy.getMonth() + 1, 0).getDate();
  copy.setDate(Math.min(originalDay, lastDay));
  return copy;
};

const toLifecycleIso = (value) => {
  if (value instanceof Date && !Number.isNaN(value.getTime())) return value.toISOString();
  const ms = toLifecycleMs(value);
  return Number.isFinite(ms) && ms > 0 ? new Date(ms).toISOString() : "";
};

const createStudentCancellationHistoryEntry = (acao, detalhe = "") => ({
  data: new Date().toISOString(),
  acao: String(acao || "").trim(),
  detalhe: String(detalhe || "").trim(),
});

const normalizeStudentCancellationRecord = (value) => {
  if (!value || typeof value !== "object") return null;
  const raw = clonePlainData(value);
  const origemRaw = String(raw.origem || raw.tipo || "").trim().toLowerCase();
  const origem =
    origemRaw === "abandono_confirmado" || origemRaw === "abandono"
      ? "abandono_confirmado"
      : "pedido";
  const dataPedido = raw.dataPedido || raw.data_pedido || raw.createdAt || null;
  const dataFimAviso = raw.dataFimAviso || raw.dataFimPrevista || raw.data_fim_aviso || null;
  const eventos = Array.isArray(raw.eventos)
    ? raw.eventos
    : Array.isArray(raw.historico)
      ? raw.historico
      : [];
  return {
    dataPedido,
    origem,
    motivo: String(raw.motivo || "").trim(),
    motivoDetalhe: String(raw.motivoDetalhe || raw.detalhe || "").trim(),
    dataFimAviso,
    aulasSuspensas: raw.aulasSuspensas === true,
    dataSuspensao: raw.dataSuspensao || null,
    desfecho: raw.desfecho ?? null,
    dataEfetivacao: raw.dataEfetivacao || null,
    eventos: eventos.map((event) => ({
      data: event?.data || event?.createdAt || new Date().toISOString(),
      acao: String(event?.acao || "").trim(),
      detalhe: String(event?.detalhe || "").trim(),
    })),
  };
};

const buildStudentCancellationRecord = ({
  dataPedido,
  origem = "pedido",
  motivo = "",
  motivoDetalhe = "",
  dataFimAviso = null,
  aulasSuspensas = false,
  dataSuspensao = null,
  desfecho = null,
  dataEfetivacao = null,
  eventos = [],
} = {}) => ({
  dataPedido: toLifecycleIso(dataPedido),
  origem: origem === "abandono_confirmado" ? "abandono_confirmado" : "pedido",
  motivo: String(motivo || "").trim(),
  motivoDetalhe: String(motivoDetalhe || "").trim(),
  dataFimAviso: dataFimAviso ? toLifecycleIso(dataFimAviso) : null,
  aulasSuspensas: Boolean(aulasSuspensas),
  dataSuspensao: dataSuspensao ? toLifecycleIso(dataSuspensao) : null,
  desfecho: desfecho ?? null,
  dataEfetivacao: dataEfetivacao ? toLifecycleIso(dataEfetivacao) : null,
  eventos: Array.isArray(eventos)
    ? eventos.map((event) => ({
        data: event?.data || new Date().toISOString(),
        acao: String(event?.acao || "").trim(),
        detalhe: String(event?.detalhe || "").trim(),
      }))
    : [],
});

const getStudentCancellationWindowRange = (cancelamento, referenceDate = new Date()) => {
  const normalized = normalizeStudentCancellationRecord(cancelamento);
  const startDate = toLifecycleDate(normalized?.dataPedido);
  const endDate = toLifecycleDate(normalized?.dataFimAviso);
  if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime())) return null;
  const today = endOfDay(referenceDate);
  const effectiveEnd = endDate instanceof Date && !Number.isNaN(endDate.getTime()) ? (endDate < today ? endDate : today) : today;
  if (effectiveEnd < startDate) return null;
  return {
    startDate,
    endDate: effectiveEnd,
    fromKey: createDateKey(startDate),
    toKey: createDateKey(effectiveEnd),
  };
};

const resolveStudentFinanceBinding = ({ aluno, financeStudents = [], charges = [] } = {}) => {
  const studentId = String(aluno?.id || aluno?.alunoId || "").trim();
  const email = String(aluno?.email || "").trim().toLowerCase();
  const phone = String(aluno?.telefone || "").replace(/\D+/g, "");
  const financeRows = Array.isArray(financeStudents) ? financeStudents : [];
  const chargeRows = Array.isArray(charges) ? charges : [];

  const byAlunoId = chargeRows.filter((row) => String(row?.aluno_id || "").trim() === studentId);
  if (studentId && byAlunoId.length) {
    return { status: "linked", strategy: "aluno_id", charges: byAlunoId, financeRow: null };
  }

  const emailMatches = email
    ? chargeRows.filter((row) => {
        const chargeEmail = String(row?.email || row?.aluno_email || "").trim().toLowerCase();
        return chargeEmail && chargeEmail === email;
      })
    : [];
  if (email && emailMatches.length) {
    return { status: "linked", strategy: "email", charges: emailMatches, financeRow: null };
  }

  const phoneMatches = phone
    ? chargeRows.filter((row) => String(row?.telefone || "").replace(/\D+/g, "") === phone)
    : [];
  if (phone && phoneMatches.length) {
    return { status: "linked", strategy: "telefone", charges: phoneMatches, financeRow: null };
  }

  const financeByEmail = email
    ? financeRows.filter((row) => String(row?.email || "").trim().toLowerCase() === email)
    : [];
  if (financeByEmail.length === 1) {
    const financeRow = financeByEmail[0];
    const relatedCharges = chargeRows.filter((row) => String(row?.email || row?.aluno_email || "").trim().toLowerCase() === email);
    return { status: relatedCharges.length ? "linked" : "student_only", strategy: "finance_email", charges: relatedCharges, financeRow };
  }

  const financeByPhone = phone
    ? financeRows.filter((row) => String(row?.telefone || "").replace(/\D+/g, "") === phone)
    : [];
  if (financeByPhone.length === 1) {
    const financeRow = financeByPhone[0];
    const relatedCharges = chargeRows.filter((row) => String(row?.telefone || "").replace(/\D+/g, "") === phone);
    return { status: relatedCharges.length ? "linked" : "student_only", strategy: "finance_telefone", charges: relatedCharges, financeRow };
  }

  return { status: "sem_vinculo", strategy: "", charges: [], financeRow: null };
};

const deriveSensorPagamento = (aluno, dataInicio, dataFim, { charges = [], financeStudents = [] } = {}) => {
  const binding = resolveStudentFinanceBinding({ aluno, financeStudents, charges });
  if (binding.status === "sem_vinculo") {
    return { estado: "sem_vinculo", detalhe: "Não foi possível vincular este aluno ao financeiro." };
  }
  const fromKey = typeof dataInicio === "string" ? dataInicio : createDateKey(dataInicio);
  const toKey = typeof dataFim === "string" ? dataFim : createDateKey(dataFim);
  const scopedCharges = (binding.charges || []).filter((row) => {
    const due = String(row?.vencimento || row?.data_vencimento || row?.due_date || "").trim();
    return isValidDateKey(due) && due >= fromKey && due <= toKey;
  });
  if (!scopedCharges.length) {
    return { estado: "sem_cobranca", detalhe: "Nenhuma cobrança no período analisado." };
  }
  const openCharges = scopedCharges.filter((row) => {
    const status = String(row?.status || "").trim().toLowerCase();
    return status !== "pago" && !row?.pago_em && status !== "cancelado";
  });
  const overdue = openCharges
    .map((row) => {
      const due = String(row?.vencimento || row?.data_vencimento || row?.due_date || "").trim();
      const days = financeDaysUntil(due);
      return { row, days };
    })
    .filter((item) => Number.isFinite(item.days) && item.days < 0)
    .sort((a, b) => a.days - b.days);
  if (!overdue.length) {
    return { estado: "em_dia", detalhe: "Nenhuma cobrança vencida em aberto no período." };
  }
  const mostOverdueDays = Math.abs(Number(overdue[0].days) || 0);
  if (mostOverdueDays >= RETENTION_THRESHOLDS.pagamentoVencidaCriticaDias) {
    return { estado: "vencida_critica", detalhe: `Cobrança vencida há ${mostOverdueDays} dia(s).` };
  }
  return { estado: "vencida", detalhe: `Cobrança vencida há ${mostOverdueDays} dia(s).` };
};

const deriveSensorFrequencia = (aluno, dataInicio, dataFim, { logs = [], events = [], classes = [] } = {}) => {
  const alunoId = String(aluno?.id || aluno?.alunoId || "").trim();
  const fromKey = typeof dataInicio === "string" ? dataInicio : createDateKey(dataInicio);
  const toKey = typeof dataFim === "string" ? dataFim : createDateKey(dataFim);
  const periodEvents = (Array.isArray(events) ? events : []).filter((event) => {
    if (!event || typeof event !== "object") return false;
    if (String(event?.type || "").trim() !== "lesson") return false;
    if (String(event?.alunoId || "").trim() !== alunoId) return false;
    const dateKey = String(event?.dateKey || "").trim();
    return isValidDateKey(dateKey) && dateKey >= fromKey && dateKey <= toKey;
  });
  if (!periodEvents.length) {
    const linkedClasses = (Array.isArray(classes) ? classes : []).filter((classRow) =>
      Array.isArray(classRow?.studentIds) ? classRow.studentIds.map((id) => String(id || "").trim()).includes(alunoId) : false
    );
    if (!linkedClasses.length) return { estado: "sem_aulas", detalhe: "Aluno sem aulas vinculadas no período." };
    return { estado: "sem_aulas", detalhe: "Nenhuma ocorrência de aula encontrada no período." };
  }

  const logsInPeriod = (Array.isArray(logs) ? logs : []).filter((log) => {
    if (!log || typeof log !== "object") return false;
    if (String(log?.alunoId || "").trim() !== alunoId) return false;
    const dateKey = String(log?.dateKey || "").trim();
    return isValidDateKey(dateKey) && dateKey >= fromKey && dateKey <= toKey;
  });
  const presenceLogs = logsInPeriod
    .filter((log) => normalizePedagogicoStatus(log?.statusAula) === PEDAGOGICO_STATUS.REALIZADA)
    .sort((a, b) => String(b?.dateKey || "").localeCompare(String(a?.dateKey || "")));
  if (!presenceLogs.length) {
    return { estado: "nunca_apareceu", detalhe: "Nenhuma presença registrada neste período." };
  }
  const lastPresenceDate = parseDateKey(String(presenceLogs[0].dateKey || "").trim());
  if (!(lastPresenceDate instanceof Date) || Number.isNaN(lastPresenceDate.getTime())) {
    return { estado: "nunca_apareceu", detalhe: "Nenhuma presença válida registrada no período." };
  }
  const daysSincePresence = Math.max(0, Math.round((startOfDay(new Date()).getTime() - startOfDay(lastPresenceDate).getTime()) / 86400000));
  if (daysSincePresence < 7) {
    return { estado: "frequentando", detalhe: `Última presença há ${daysSincePresence} dia(s).` };
  }
  if (daysSincePresence >= RETENTION_THRESHOLDS.frequenciaAusenteCriticaDias) {
    return { estado: "ausente_critico", detalhe: `Sem presença há ${daysSincePresence} dia(s).` };
  }
  return { estado: "ausente", detalhe: `Sem presença há ${daysSincePresence} dia(s).` };
};

const getLifecycleSensorTone = (estado) => {
  if (["em_dia", "frequentando"].includes(String(estado || ""))) return "green";
  if (["vencida", "ausente"].includes(String(estado || ""))) return "amber";
  if (["vencida_critica", "ausente_critico", "nunca_apareceu"].includes(String(estado || ""))) return "red";
  return "gray";
};

const getStudentLifecycleState = (aluno) => {
  const meta = aluno && typeof aluno === "object" ? aluno : {};
  const cancelamento = normalizeStudentCancellationRecord(meta.cancelamento);
  const wasEffectivelyCancelled = Boolean(cancelamento?.dataEfetivacao) || Boolean(cancelamento?.desfecho);
  const hasLegacyInactiveFlag =
    meta.ativo === false || Boolean(meta.desativadoEm || meta.canceladoEm || meta.cancelamentoEm || meta.dataCancelamento);
  if (wasEffectivelyCancelled) return STUDENT_LIFECYCLE_STATE.INACTIVE;
  if (isStudentCancellationActive(cancelamento) && cancelamento?.aulasSuspensas) return STUDENT_LIFECYCLE_STATE.SUSPENDED;
  if (isStudentCancellationActive(cancelamento)) return STUDENT_LIFECYCLE_STATE.NOTICE;
  if (hasLegacyInactiveFlag) return STUDENT_LIFECYCLE_STATE.INACTIVE;
  return STUDENT_LIFECYCLE_STATE.ACTIVE;
};

const RETENTION_CRITICAL_ATTENDANCE_STATES = new Set(["ausente_critico", "nunca_apareceu"]);
const RETENTION_CRITICAL_PAYMENT_STATES = new Set(["vencida_critica"]);

const getRetentionOriginLabel = (record) =>
  String(record?.origem || "").trim() === "abandono_confirmado" ? "Abandono" : "Pedido";

const getRetentionSensorLabel = (sensor, fallback) => {
  const state = String(sensor?.estado || "").trim();
  if (state === "vencida_critica") return "Pagamento crítico";
  if (state === "vencida") return "Pagamento vencido";
  if (state === "em_dia") return "Pagamento em dia";
  if (state === "sem_cobranca") return "Sem cobrança";
  if (state === "sem_vinculo") return "Sem vínculo financeiro";
  if (state === "ausente_critico") return "Frequência crítica";
  if (state === "ausente") return "Frequência em atenção";
  if (state === "frequentando") return "Frequência em dia";
  if (state === "nunca_apareceu") return "Nunca apareceu";
  if (state === "sem_aulas") return "Sem aulas";
  return String(fallback || "Sem dados");
};

const getRetentionSensorPriority = (sensor) => {
  const state = String(sensor?.estado || "").trim();
  if (state === "vencida_critica" || state === "ausente_critico" || state === "nunca_apareceu") return 3;
  if (state === "vencida" || state === "ausente") return 2;
  if (state === "em_dia" || state === "frequentando") return 1;
  return 0;
};

const formatRetentionDaysRemaining = (record, referenceDate = new Date()) => {
  const endDate = toLifecycleDate(record?.dataFimAviso);
  if (!(endDate instanceof Date) || Number.isNaN(endDate.getTime())) return "";
  const diff = Math.round((startOfDay(endDate).getTime() - startOfDay(referenceDate).getTime()) / 86400000);
  if (diff < 0) return `${Math.abs(diff)}d em atraso`;
  if (diff === 0) return "vence hoje";
  if (diff === 1) return "1 dia restante";
  return `${diff} dias restantes`;
};

const getRetentionDateKey = (value) => {
  if (!value) return "";
  if (typeof value === "string") {
    const raw = value.trim();
    if (/^\d{4}-\d{2}-\d{2}/.test(raw)) return raw.slice(0, 10);
    const br = raw.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    if (br) return `${br[3]}-${br[2]}-${br[1]}`;
  }
  const date = toLifecycleDate(value);
  return date instanceof Date && !Number.isNaN(date.getTime()) ? createDateKey(date) : "";
};

const getRetentionTimelineProgress = (record, referenceDate = new Date()) => {
  const startDate = toLifecycleDate(record?.dataPedido);
  const endDate = toLifecycleDate(record?.dataFimAviso);
  if (!(startDate instanceof Date) || Number.isNaN(startDate.getTime()) || !(endDate instanceof Date) || Number.isNaN(endDate.getTime())) {
    return { totalDays: 0, elapsedDays: 0, progressPct: 0, label: "Sem janela definida" };
  }
  const totalDays = Math.max(1, Math.floor((startOfDay(endDate).getTime() - startOfDay(startDate).getTime()) / 86400000) + 1);
  const elapsedRaw = Math.floor((startOfDay(referenceDate).getTime() - startOfDay(startDate).getTime()) / 86400000) + 1;
  const elapsedDays = Math.max(1, Math.min(totalDays, elapsedRaw));
  const progressPct = totalDays > 0 ? Math.max(0, Math.min(100, Math.round((elapsedDays / totalDays) * 100))) : 0;
  return { totalDays, elapsedDays, progressPct, label: `Dia ${elapsedDays} de ${totalDays}` };
};

const buildRetentionTimelineLabel = (record, referenceDate = new Date()) => getRetentionTimelineProgress(record, referenceDate).label;

const getRetentionStudentDisplayName = (student) => {
  const name = compactAdminPedName(student?.nome || student?.aluno_nome || "Aluno", 2);
  return name || "Aluno";
};

const buildRetentionDecisionEvidence = ({ paymentSensor, attendanceSensor }) =>
  [String(paymentSensor?.detalhe || "").trim(), String(attendanceSensor?.detalhe || "").trim()].filter(Boolean).join(" · ");

const getRetentionEffectiveRecords = (student) => {
  const records = [];
  const current = normalizeStudentCancellationRecord(student?.cancelamento);
  if (current) records.push(current);
  (Array.isArray(student?.cancelamentosAnteriores) ? student.cancelamentosAnteriores : []).forEach((item) => {
    const normalized = normalizeStudentCancellationRecord(item);
    if (normalized) records.push(normalized);
  });
  return records;
};

const buildRetentionQueues = ({
  students = [],
  lessonLogs = [],
  scheduleEvents = [],
  classes = [],
  financeStudents = [],
  charges = [],
  referenceDate = new Date(),
} = {}) => {
  const today = startOfDay(referenceDate);
  const todayKey = createDateKey(today);
  const last60Start = addDays(today, -59);
  const last60FromKey = createDateKey(last60Start);
  const last90Start = addDays(today, -89).getTime();
  const avisos = [];
  const decisoes = [];
  const efetivados = [];

  (Array.isArray(students) ? students : []).forEach((student) => {
    if (!student || typeof student !== "object") return;
    const normalizedCurrent = normalizeStudentCancellationRecord(student.cancelamento);
    const lifecycleState = getStudentLifecycleState(student);
    const activeCancellation =
      normalizedCurrent &&
      !normalizedCurrent.desfecho &&
      (lifecycleState === STUDENT_LIFECYCLE_STATE.NOTICE || lifecycleState === STUDENT_LIFECYCLE_STATE.SUSPENDED)
        ? normalizedCurrent
        : null;
    const studentName = getRetentionStudentDisplayName(student);
    const activeSensors = activeCancellation
      ? (() => {
          const range = getStudentCancellationWindowRange(activeCancellation, referenceDate);
          if (!range) return { payment: null, attendance: null };
          return {
            payment: deriveSensorPagamento(student, range.fromKey, range.toKey, {
              charges,
              financeStudents,
            }),
            attendance: deriveSensorFrequencia(student, range.fromKey, range.toKey, {
              logs: lessonLogs,
              events: scheduleEvents,
              classes,
            }),
          };
        })()
      : { payment: null, attendance: null };

    if (activeCancellation) {
      const daysRemaining = formatRetentionDaysRemaining(activeCancellation, referenceDate);
      const avisoRow = {
        type: "aviso",
        alunoId: String(student.id || "").trim(),
        alunoNome: studentName,
        origem: getRetentionOriginLabel(activeCancellation),
        timeline: buildRetentionTimelineLabel(activeCancellation, referenceDate),
        daysRemaining,
        paymentSensor: activeSensors.payment,
        attendanceSensor: activeSensors.attendance,
        paymentTone: getLifecycleSensorTone(activeSensors.payment?.estado),
        attendanceTone: getLifecycleSensorTone(activeSensors.attendance?.estado),
        aulasSuspensas: activeCancellation.aulasSuspensas === true,
        score:
          getRetentionSensorPriority(activeSensors.payment) * 10 +
          getRetentionSensorPriority(activeSensors.attendance) * 10 +
          (activeCancellation.aulasSuspensas ? 2 : 0),
      };
      avisos.push(avisoRow);

      const activeEndKey = getRetentionDateKey(activeCancellation?.dataFimAviso);
      if (activeEndKey && activeEndKey < todayKey) {
        decisoes.push({
          kind: "aviso_vencido",
          alunoId: avisoRow.alunoId,
          alunoNome: avisoRow.alunoNome,
          origem: avisoRow.origem,
          evidence: daysRemaining || "Aviso vencido",
          actionLabel: "Efetivar",
          secondaryActionLabel: "Abrir ficha",
          activeCancellation,
          paymentSensor: activeSensors.payment,
          attendanceSensor: activeSensors.attendance,
        });
      } else if (
        RETENTION_CRITICAL_PAYMENT_STATES.has(String(activeSensors.payment?.estado || "")) &&
        RETENTION_CRITICAL_ATTENDANCE_STATES.has(String(activeSensors.attendance?.estado || "")) &&
        activeCancellation.aulasSuspensas !== true
      ) {
        decisoes.push({
          kind: "aparenta_abandono_no_aviso",
          alunoId: avisoRow.alunoId,
          alunoNome: avisoRow.alunoNome,
          origem: avisoRow.origem,
          evidence: buildRetentionDecisionEvidence({ paymentSensor: activeSensors.payment, attendanceSensor: activeSensors.attendance }),
          actionLabel: "Suspender aulas",
          secondaryActionLabel: "Abrir ficha",
          activeCancellation,
          paymentSensor: activeSensors.payment,
          attendanceSensor: activeSensors.attendance,
        });
      }
    } else if (isStudentLifecycleActive(student)) {
      const payment60 = deriveSensorPagamento(student, last60FromKey, todayKey, {
        charges,
        financeStudents,
      });
      const attendance60 = deriveSensorFrequencia(student, last60FromKey, todayKey, {
        logs: lessonLogs,
        events: scheduleEvents,
        classes,
      });
      if (
        RETENTION_CRITICAL_PAYMENT_STATES.has(String(payment60?.estado || "")) &&
        RETENTION_CRITICAL_ATTENDANCE_STATES.has(String(attendance60?.estado || ""))
      ) {
        decisoes.push({
          kind: "candidato_abandono_silencioso",
          alunoId: String(student.id || "").trim(),
          alunoNome: studentName,
          origem: "Sem aviso",
          evidence: buildRetentionDecisionEvidence({ paymentSensor: payment60, attendanceSensor: attendance60 }),
          actionLabel: "Confirmar abandono",
          secondaryActionLabel: "Abrir ficha",
          activeCancellation: null,
          paymentSensor: payment60,
          attendanceSensor: attendance60,
        });
      }
    }

    getRetentionEffectiveRecords(student).forEach((record) => {
      const efetivacaoMs = parseFirestoreDateToMs(record?.dataEfetivacao);
      if (!Number.isFinite(efetivacaoMs) || efetivacaoMs < last90Start) return;
      if (!record?.desfecho) return;
      efetivados.push({
        alunoId: String(student.id || "").trim(),
        alunoNome: studentName,
        origem: getRetentionOriginLabel(record),
        desfecho: getRetentionOutcomeLabel(record.desfecho) || "Efetivado",
        dataEfetivacao: efetivacaoMs,
      });
    });
  });

  avisos.sort((a, b) => {
    if ((b.score || 0) !== (a.score || 0)) return (b.score || 0) - (a.score || 0);
    const ad = Math.abs(Number((a.daysRemaining.match(/\d+/) || [999])[0]) || 999);
    const bd = Math.abs(Number((b.daysRemaining.match(/\d+/) || [999])[0]) || 999);
    return ad - bd;
  });

  const decisionPriority = {
    aviso_vencido: 0,
    aparenta_abandono_no_aviso: 1,
    candidato_abandono_silencioso: 2,
  };
  decisoes.sort((a, b) => {
    const pa = decisionPriority[String(a.kind || "")] ?? 99;
    const pb = decisionPriority[String(b.kind || "")] ?? 99;
    if (pa !== pb) return pa - pb;
    return String(a.alunoNome || "").localeCompare(String(b.alunoNome || ""), "pt-BR");
  });

  efetivados.sort((a, b) => Number(b.dataEfetivacao || 0) - Number(a.dataEfetivacao || 0));

  return { avisos, decisoes, efetivados };
};

const RETENTION_OUTCOME_OPTIONS = [
  { value: "cumpriu_integral", label: "Cumpriu aviso integral" },
  { value: "pagou_sem_frequentar", label: "Pagou, mas não frequentou" },
  { value: "cumpriu_parcial", label: "Cumpriu aviso parcial" },
  { value: "abandono_durante_aviso", label: "Abandono durante aviso" },
  { value: "abandono_silencioso", label: "Abandono silencioso" },
];

const getRetentionOutcomeLabel = (value) => {
  const raw = String(value?.tipo || value || "").trim();
  return RETENTION_OUTCOME_OPTIONS.find((item) => item.value === raw)?.label || (raw === "revertido" ? "Revertido" : raw || "—");
};

const getRetentionOutcomeType = (desfecho) => String(desfecho?.tipo || desfecho || "").trim();

const countRetentionPaidMonths = (paymentSensor) => {
  const state = String(paymentSensor?.estado || "").trim();
  if (state === "em_dia") return 2;
  if (state === "vencida" || state === "vencida_critica") return 1;
  if (state === "sem_cobranca" || state === "sem_vinculo") return null;
  return 0;
};

const countRetentionPaidMonthsFromCharges = ({ aluno, fromKey, toKey, charges = [], financeStudents = [] } = {}) => {
  const binding = resolveStudentFinanceBinding({ aluno, financeStudents, charges });
  if (binding.status === "sem_vinculo") return null;
  const scopedCharges = (binding.charges || []).filter((row) => {
    const due = String(row?.vencimento || row?.data_vencimento || row?.due_date || "").trim();
    return isValidDateKey(due) && due >= fromKey && due <= toKey;
  });
  if (!scopedCharges.length) return null;
  const paidMonthKeys = new Set();
  scopedCharges.forEach((row) => {
    const status = String(row?.status || "").trim().toLowerCase();
    const isPaid = status === "pago" || Boolean(row?.pago_em || row?.paid_at || row?.data_pagamento);
    if (!isPaid) return;
    const due = String(row?.vencimento || row?.data_vencimento || row?.due_date || "").trim();
    if (isValidDateKey(due)) paidMonthKeys.add(due.slice(0, 7));
  });
  return Math.min(2, paidMonthKeys.size);
};

const suggestRetentionOutcome = ({ cancelamento, paymentSensor, attendanceSensor, paidMonthsOverride = undefined } = {}) => {
  const record = normalizeStudentCancellationRecord(cancelamento);
  if (String(record?.origem || "") === "abandono_confirmado") {
    return {
      value: "abandono_silencioso",
      confidence: "high",
      warning: "",
      paidMonths: null,
    };
  }
  const paymentState = String(paymentSensor?.estado || "").trim();
  const attendanceState = String(attendanceSensor?.estado || "").trim();
  if (paymentState === "sem_vinculo" || paymentState === "sem_cobranca") {
    return {
      value: "",
      confidence: "low",
      warning: "Sem dados financeiros suficientes — selecione o desfecho manualmente.",
      paidMonths: null,
    };
  }
  const paidMonths = paidMonthsOverride === null || Number.isFinite(Number(paidMonthsOverride)) ? paidMonthsOverride : countRetentionPaidMonths(paymentSensor);
  if (paidMonths >= 2) {
    return {
      value: attendanceState === "ausente_critico" || attendanceState === "nunca_apareceu" ? "pagou_sem_frequentar" : "cumpriu_integral",
      confidence: "high",
      warning: "",
      paidMonths,
    };
  }
  if (paidMonths === 1) return { value: "cumpriu_parcial", confidence: "medium", warning: "", paidMonths };
  return { value: "abandono_durante_aviso", confidence: "medium", warning: "", paidMonths: 0 };
};

const getRetentionMonthBounds = (monthKey) => {
  const key = /^\d{4}-\d{2}$/.test(String(monthKey || "")) ? String(monthKey) : createDateKey(new Date()).slice(0, 7);
  const start = new Date(`${key}-01T00:00:00`);
  const end = new Date(start.getFullYear(), start.getMonth() + 1, 0, 23, 59, 59, 999);
  return { key, start, end, startMs: start.getTime(), endMs: end.getTime() };
};

const addMonthsToMonthKey = (monthKey, offset) => {
  const bounds = getRetentionMonthBounds(monthKey);
  const date = new Date(bounds.start.getFullYear(), bounds.start.getMonth() + Number(offset || 0), 1);
  return createDateKey(date).slice(0, 7);
};

const formatRetentionMonthLabel = (monthKey) => {
  const { start } = getRetentionMonthBounds(monthKey);
  return start.toLocaleDateString("pt-BR", { month: "long", year: "numeric" });
};

const getRetentionStudentCreatedMs = (student) =>
  parseFirestoreDateToMs(student?.criadoEm || student?.createdAt || student?.created_at || student?.dataCadastro || student?.created);

const collectRetentionCancellationRecords = (student) => {
  const rows = [];
  const current = normalizeStudentCancellationRecord(student?.cancelamento);
  if (current) rows.push({ record: current, current: true });
  (Array.isArray(student?.cancelamentosAnteriores) ? student.cancelamentosAnteriores : []).forEach((item) => {
    const normalized = normalizeStudentCancellationRecord(item);
    if (normalized) rows.push({ record: normalized, current: false });
  });
  return rows;
};

const buildRetentionMetrics = (mesReferencia, dadosPreCarregados = {}, options = {}) => {
  const bounds = getRetentionMonthBounds(mesReferencia);
  const students = Array.isArray(dadosPreCarregados.students) ? dadosPreCarregados.students : [];
  const ativosAtuais = students.filter((student) => {
    const state = getStudentLifecycleState(student);
    return state === STUDENT_LIFECYCLE_STATE.ACTIVE || state === STUDENT_LIFECYCLE_STATE.NOTICE || state === STUDENT_LIFECYCLE_STATE.SUSPENDED;
  }).length;
  let novosNoMes = 0;
  let pedidosNoMes = 0;
  let churnNoMes = 0;
  let revertidosNoMes = 0;
  const byOutcome = new Map();
  const byReason = new Map();
  const monthlyRows = [];

  students.forEach((student) => {
    const createdMs = getRetentionStudentCreatedMs(student);
    if (Number.isFinite(createdMs) && createdMs >= bounds.startMs && createdMs <= bounds.endMs) novosNoMes += 1;
    collectRetentionCancellationRecords(student).forEach(({ record }) => {
      const pedidoMs = parseFirestoreDateToMs(record?.dataPedido);
      if (
        Number.isFinite(pedidoMs) &&
        pedidoMs >= bounds.startMs &&
        pedidoMs <= bounds.endMs &&
        String(record?.origem || "pedido") === "pedido"
      ) {
        pedidosNoMes += 1;
      }
      const effectiveMs = parseFirestoreDateToMs(record?.dataEfetivacao);
      const outcome = getRetentionOutcomeType(record?.desfecho);
      if (Number.isFinite(effectiveMs) && effectiveMs >= bounds.startMs && effectiveMs <= bounds.endMs) {
        if (outcome === "revertido") {
          revertidosNoMes += 1;
        } else if (outcome) {
          churnNoMes += 1;
          byOutcome.set(outcome, (byOutcome.get(outcome) || 0) + 1);
          const reason = String(record?.motivo || "Sem motivo").trim() || "Sem motivo";
          byReason.set(reason, (byReason.get(reason) || 0) + 1);
        }
      }
    });
  });

  // Sem snapshot histórico confiável de alunos ativos no primeiro dia; aproximamos por ativos atuais + churn efetivado no mês − cadastros do mês.
  const ativosInicioMes = Math.max(ativosAtuais, ativosAtuais + churnNoMes - novosNoMes);
  const percent = (value) => (ativosInicioMes > 0 ? (Number(value || 0) / ativosInicioMes) * 100 : 0);
  const casosFechadosNoMes = revertidosNoMes + churnNoMes;
  if (options.withSeries !== false) {
    for (let i = 5; i >= 0; i -= 1) {
      const monthKey = addMonthsToMonthKey(bounds.key, -i);
      const monthMetrics = monthKey === bounds.key ? null : buildRetentionMetrics(monthKey, dadosPreCarregados, { withSeries: false });
      monthlyRows.push(
        monthMetrics || {
          monthKey,
          pedidosNoMes: 0,
          churnNoMes: 0,
          revertidosNoMes: 0,
        }
      );
    }
    monthlyRows[monthlyRows.length - 1] = {
      monthKey: bounds.key,
      pedidosNoMes,
      churnNoMes,
      revertidosNoMes,
    };
  }

  return {
    monthKey: bounds.key,
    ativosAtuais,
    ativosInicioMes,
    ativosInicioMesApproach: "aproximado_por_ativos_atuais_churn_e_novos",
    novosNoMes,
    pedidosNoMes,
    churnNoMes,
    revertidosNoMes,
    pedidosPct: percent(pedidosNoMes),
    churnPct: percent(churnNoMes),
    casosFechadosNoMes,
    reversalRate: casosFechadosNoMes > 0 ? (revertidosNoMes / casosFechadosNoMes) * 100 : null,
    byOutcome: Object.fromEntries(byOutcome),
    byReason: Object.fromEntries(byReason),
    series6m: monthlyRows.map((row) => ({
      monthKey: row.monthKey,
      label: formatRetentionMonthLabel(row.monthKey).slice(0, 3),
      pedidos: row.pedidosNoMes || 0,
      churn: row.churnNoMes || 0,
      reversoes: row.revertidosNoMes || 0,
    })),
  };
};

const getStudentLifecycleBadgeMeta = (aluno) => {
  const state = getStudentLifecycleState(aluno);
  const cancelamento = normalizeStudentCancellationRecord(aluno?.cancelamento);
  if (state === STUDENT_LIFECYCLE_STATE.NOTICE) {
    if (String(cancelamento?.origem || "") === "abandono_confirmado") {
      return { state, label: "Abandono", tone: "warn" };
    }
    return { state, label: "Aviso prévio", tone: "warn" };
  }
  if (state === STUDENT_LIFECYCLE_STATE.SUSPENDED) {
    return { state, label: "Suspenso", tone: "muted" };
  }
  if (state === STUDENT_LIFECYCLE_STATE.INACTIVE) {
    return { state, label: "Inativo", tone: "gray" };
  }
  return { state, label: "", tone: "" };
};

const isStudentLifecycleInactive = (aluno) => getStudentLifecycleState(aluno) === STUDENT_LIFECYCLE_STATE.INACTIVE;
const isStudentLifecycleActive = (aluno) => !isStudentLifecycleInactive(aluno);

const getAdminStudentLatestLifecycleRecord = (aluno) => {
  const previous = Array.isArray(aluno?.cancelamentosAnteriores) ? aluno.cancelamentosAnteriores : [];
  const current = normalizeStudentCancellationRecord(aluno?.cancelamento);
  if (current) return current;
  return previous.length ? previous[previous.length - 1] : null;
};

const getAdminStudentFirstLessonDate = (alunoId) => {
  const id = String(alunoId || "").trim();
  if (!id) return null;
  let firstDate = null;
  const ingestDate = (candidate) => {
    if (!(candidate instanceof Date) || Number.isNaN(candidate.getTime())) return;
    if (!firstDate || candidate.getTime() < firstDate.getTime()) firstDate = candidate;
  };

  const events = Array.isArray(adminStudentsState.events) ? adminStudentsState.events : [];
  events.forEach((evt) => {
    if (!evt || typeof evt !== "object") return;
    if (evt.type !== "lesson") return;
    if (String(evt.alunoId || "").trim() !== id) return;
    const date = parseDateKey(String(evt.dateKey || "").trim());
    ingestDate(date);
  });

  const linkedClasses = getAdminStudentLinkedClasses(id);
  linkedClasses.forEach((classRow) => {
    const date = parseDateKey(String(classRow?.startDate || "").trim());
    ingestDate(date);
  });

  return firstDate;
};

const describeStudentCancellationType = (cancelamento) => {
  const origem = String(cancelamento?.origem || "").trim();
  if (origem === "abandono_confirmado") return "Abandono";
  return "Aviso prévio";
};

const buildStudentLifecycleSummary = (aluno) => {
  const state = getStudentLifecycleState(aluno);
  const cancelamento = normalizeStudentCancellationRecord(aluno?.cancelamento);
  const latest = getAdminStudentLatestLifecycleRecord(aluno);
  if (state === STUDENT_LIFECYCLE_STATE.INACTIVE) {
    return {
      state,
      title: "Aluno inativo",
      subtitle:
        latest?.desfecho || latest?.dataEfetivacao
          ? `${latest?.desfecho ? `Desfecho: ${latest.desfecho}` : ""}${latest?.desfecho && latest?.dataEfetivacao ? " · " : ""}${
              latest?.dataEfetivacao ? `Efetivado em ${formatAdminDate(latest.dataEfetivacao)}` : ""
            }`.trim()
          : "Sem ciclo de cancelamento ativo.",
    };
  }
  if (!cancelamento) {
    return { state, title: "Aluno ativo", subtitle: "Sem cancelamento ou abandono registrados." };
  }
  const endLabel = cancelamento?.dataFimAviso ? formatAdminDate(cancelamento.dataFimAviso) : "a definir";
  if (String(cancelamento.origem || "") === "abandono_confirmado") {
    return {
      state,
      title: cancelamento.aulasSuspensas ? "Abandono registrado com aulas suspensas" : "Abandono registrado",
      subtitle: "Efetivação pendente.",
      endLabel,
    };
  }
  return {
    state,
    title: `Em aviso prévio até ${endLabel}`,
    subtitle: cancelamento?.dataPedido ? `Pedido em ${formatAdminDate(cancelamento.dataPedido)}` : "",
    endLabel,
  };
};

const normalizeSupabaseStudentForAdmin = (row = {}) => {
  if (!row || typeof row !== "object") return null;
  const id = String(row.id || row.aluno_id || row.aluno_chave || row.email || row.telefone || row.aluno_nome || row.nome || "").trim();
  const nome = String(row.nome || row.aluno_nome || "Aluno").trim();
  if (!id || !nome) return null;
  const email = String(row.email || row.aluno_email || "").trim().toLowerCase();
  const ativo = row.ativo_acesso !== false && !["inativo", "cancelado", "cancelada", "inactive"].includes(String(row.status_acesso || row.status || "").toLowerCase());
  return {
    id,
    nome,
    email,
    firestoreDocIdRef: String(row.firestore_doc_id || "").trim(),
    sourceBusinessId: String(row.aluno_id || row.aluno_chave || row.id || "").trim(),
    tipo: "student",
    ativo,
    criadoEm: row.created_at || row.createdAt || null,
    initials: getInitials(nome),
    professorId: String(row.professor_id || row.teacherId || "").trim(),
    plano: String(row.plano || row.plan || "").trim(),
    pais: String(row.pais || row.country || "").trim(),
    canceladoEm: row.canceladoEm || row.cancelamentoEm || row.dataCancelamento || null,
    desativadoEm: row.desativadoEm || row.canceladoEm || row.cancelamentoEm || row.dataCancelamento || null,
    criadoKey: toDateKeyFromAny(row.created_at || row.createdAt),
    cancelKey: toDateKeyFromAny(row.canceladoEm || row.cancelamentoEm || row.dataCancelamento),
    desativadoKey: toDateKeyFromAny(row.desativadoEm || row.canceladoEm || row.cancelamentoEm || row.dataCancelamento),
    telefone: String(row.telefone || "").trim(),
    supabaseNome: nome,
    supabaseEmail: email,
    supabaseTelefone: String(row.telefone || "").trim(),
    supabasePlano: String(row.plano || row.plan || "").trim(),
    supabaseProfessorId: String(row.professor_id || row.teacherId || "").trim(),
    alunoChave: String(row.aluno_chave || "").trim(),
    english_level_start: String(row.english_level_start || row.englishLevelStart || "").trim(),
    photoURL: String(row.photoURL || row.photoUrl || "").trim(),
    source: row.source || "supabase",
  };
};

const mergeAdminStudentRows = (...groups) => {
  // OWNERSHIP: cadastro=Firestore, operação=Supabase (contrato 2026-07-12)
  const allRows = groups.flat().filter((row) => row && typeof row === "object");
  const firestoreRows = allRows.filter((row) => String(row?.source || "").trim().toLowerCase() === "firestore" || row?.firestoreCancelamento !== undefined);
  const supabaseRows = allRows.filter((row) => !firestoreRows.includes(row));
  const mergedByFirestoreId = new Map();
  firestoreRows.forEach((row) => {
    const firestoreId = String(row?.firestoreDocId || row?.docId || row?.documentId || row?.id || "").trim();
    if (!firestoreId) return;
    const previous = mergedByFirestoreId.get(firestoreId) || null;
    mergedByFirestoreId.set(firestoreId, previous ? mergeAdminStudentWithCachedProfile(previous, row) : row);
  });

  const firestoreEmailFrequency = new Map();
  mergedByFirestoreId.forEach((row) => {
    const email = String(row?.email || row?.firestoreEmail || "").trim().toLowerCase();
    if (!email) return;
    firestoreEmailFrequency.set(email, (firestoreEmailFrequency.get(email) || 0) + 1);
  });
  const firestoreByUniqueEmail = new Map();
  mergedByFirestoreId.forEach((row, firestoreId) => {
    const email = String(row?.email || row?.firestoreEmail || "").trim().toLowerCase();
    if (!email) return;
    if (firestoreEmailFrequency.get(email) === 1) firestoreByUniqueEmail.set(email, firestoreId);
  });

  const orphans = new Map();
  const registerOrphan = (row, reason) => {
    const orphanRow = { ...row, legacy_orphan: true, legacy_orphan_reason: reason };
    const key =
      String(orphanRow?.sourceBusinessId || orphanRow?.alunoChave || orphanRow?.aluno_chave || orphanRow?.id || orphanRow?.email || orphanRow?.telefone || "")
        .trim() || `orphan:${orphans.size + 1}`;
    const previous = orphans.get(key) || null;
    orphans.set(key, previous ? mergeAdminStudentWithCachedProfile(previous, orphanRow) : orphanRow);
  };

  supabaseRows.forEach((row) => {
    const explicitFirestoreId = String(row?.firestoreDocIdRef || row?.firestore_doc_id || "").trim();
    if (explicitFirestoreId) {
      const existing = mergedByFirestoreId.get(explicitFirestoreId) || null;
      if (existing) {
        mergedByFirestoreId.set(explicitFirestoreId, mergeAdminStudentWithCachedProfile(existing, row));
      } else {
        registerOrphan(row, "missing_firestore_match");
      }
      return;
    }
    const email = String(row?.supabaseEmail || row?.email || "").trim().toLowerCase();
    if (email && firestoreByUniqueEmail.has(email)) {
      const firestoreId = firestoreByUniqueEmail.get(email);
      const existing = mergedByFirestoreId.get(firestoreId) || null;
      if (existing) {
        mergedByFirestoreId.set(firestoreId, mergeAdminStudentWithCachedProfile(existing, row));
        return;
      }
    }
    if (email && (firestoreEmailFrequency.get(email) || 0) > 1) {
      console.warn("[ownership] ambiguous admin student email match", {
        email,
        firestoreCandidates: firestoreEmailFrequency.get(email),
        sourceBusinessId: row?.sourceBusinessId || row?.id || "",
      });
      registerOrphan(row, "ambiguous_email_match");
      return;
    }
    registerOrphan(row, "no_firestore_match");
  });

  return [...Array.from(mergedByFirestoreId.values()), ...Array.from(orphans.values())].sort((a, b) =>
    String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR")
  );
};

const ensureAdminStudentsBaseData = async ({ force = false } = {}) => {
  if (!isFinanceAccessRole(currentRole)) return;
  const now = Date.now();
  if (!force && adminStudentsState.loadedAt && now - adminStudentsState.loadedAt < 60_000) return;

  adminStudentsState.isLoading = true;
  adminStudentsState.loadError = "";
  setAdminStudentsStatus("Carregando…");
  if (adminStudentsError instanceof HTMLElement) adminStudentsError.hidden = true;

  try {
    const [teachersRes, firebaseStudentsRes, eventsRes, logsRes, pedagogicalOpsRes] = await Promise.allSettled([
      fetchAdminAgendaTeachers(),
      fetchUserRowsFromFirestore("student"),
      fetchWithAuth("/api/schedule-events", { method: "GET" }),
      fetchLessonLogsFromFirestore(),
      fetchWithAuth("/api/pedagogico/dashboard")
        .then((res) => (res.ok ? res.json() : { students: [] }))
        .catch(() => ({ students: [] })),
    ]);
    const teachers = teachersRes.status === "fulfilled" ? teachersRes.value : [];
    const firebaseStudents = firebaseStudentsRes.status === "fulfilled" ? firebaseStudentsRes.value : [];
    const eventsResValue = eventsRes.status === "fulfilled" ? eventsRes.value : null;
    const logs = logsRes.status === "fulfilled" ? logsRes.value : [];
    const pedagogicalOps = pedagogicalOpsRes.status === "fulfilled" ? pedagogicalOpsRes.value : { students: [] };

    if (teachersRes.status === "rejected") console.warn("[admin] teachers base load fell back to empty:", teachersRes.reason);
    if (firebaseStudentsRes.status === "rejected") console.warn("[admin] students base load fell back to empty:", firebaseStudentsRes.reason);
    if (eventsRes.status === "rejected") console.warn("[admin] schedule events base load fell back to empty:", eventsRes.reason);
    if (logsRes.status === "rejected") console.warn("[admin] lesson logs base load fell back to empty:", logsRes.reason);

    const supabaseStudents = (Array.isArray(pedagogicalOps?.students) ? pedagogicalOps.students : [])
      .map(normalizeSupabaseStudentForAdmin)
      .filter(Boolean);
    const students = mergeAdminStudentRows(firebaseStudents, supabaseStudents);
    console.warn("[ownership] admin students merge", {
      firebaseCount: firebaseStudents.length,
      supabaseCount: supabaseStudents.length,
      mergedCount: students.length,
      focused: ["kkeegmFko4Xi0wigwpXLDG0Bo5E3", "qsZScLZ3NpXnqKB3lIISldK97cL2"].map((id) => ({
        id,
        firebase: firebaseStudents.find((row) => String(row?.firestoreDocId || row?.id || "").trim() === id) || null,
        merged: students.find((row) => String(row?.firestoreDocId || row?.id || "").trim() === id) || null,
      })),
      legacyOrphans: students.filter((row) => row?.legacy_orphan).length,
    });

    adminStudentsState.teachers = Array.isArray(teachers) ? teachers : [];
    const teachersById = new Map();
    adminStudentsState.teachers.forEach((t) => {
      if (t && typeof t === "object" && t.id) teachersById.set(String(t.id), t);
    });
    adminStudentsState.teachersById = teachersById;
    const studentsById = new Map();
    (Array.isArray(students) ? students : []).forEach((row) => {
      const canonicalId = String(row?.firestoreDocId || row?.docId || row?.documentId || row?.id || "").trim();
      if (!canonicalId) return;
      studentsById.set(canonicalId, { ...row, id: canonicalId, firestoreDocId: canonicalId, docId: canonicalId, documentId: canonicalId });
    });
    const normalizedStudents = Array.from(studentsById.values());
    adminStudentsState.studentsById = studentsById;
    adminStudentsState.studentAliasToDocId = buildStudentAliasMap(normalizedStudents);
    adminStudentsState.students = normalizedStudents;

    const eventsData = eventsResValue && eventsResValue.ok ? await eventsResValue.json().catch(() => null) : null;
    if (!eventsResValue || !eventsResValue.ok) {
      console.warn("[admin] agenda temporariamente indisponível; exibindo alunos sem histórico de eventos.");
    }
    adminStudentsState.events = Array.isArray(eventsData?.events) ? eventsData.events : [];
    adminStudentsState.eventsLoadedAt = Date.now();

    adminStudentsState.logs = Array.isArray(logs) ? logs : [];
    adminStudentsState.logsLoadedAt = Date.now();

    adminStudentsState.loadedAt = Date.now();
    setAdminStudentsStatus("");
    // Derived lists now default to "all students".
    const derived = deriveAdminStudentsSummaries({ teacherId: "", logs: adminStudentsState.logs });
    adminStudentsState.summariesAll = derived.summaries;
    syncAdminStudentsFiltersBadge();
    applyAdminStudentsFilters();
  } catch (error) {
    console.error("[admin] students base load failed:", error);
    adminStudentsState.loadError = typeof error?.message === "string" && error.message ? error.message : "Não foi possível carregar agora.";
    if (adminStudentsError instanceof HTMLElement) adminStudentsError.hidden = false;
    setAdminStudentsStatus("Não foi possível carregar agora.", "error");
  } finally {
    adminStudentsState.isLoading = false;
    if (currentRole === "admin" && activeModalKind === "event-form") {
      syncAdminEventUserSelects();
      validateCreateEventDraft();
    }
  }
};

const adminStudentsPopulateTeacherSelect = () => {}; // legacy no-op (teacher select removed)

const loadLessonLogsForTeacher = async (teacherId, { force = false } = {}) => {
  const id = String(teacherId || "").trim();
  if (!id) return [];
  await ensureAdminStudentsBaseData({ force });
  const logs = Array.isArray(adminStudentsState.logs) ? adminStudentsState.logs : [];
  return logs.filter((l) => String(l?.professorId || "").trim() === id);
};

const deriveAdminStudentsSummaries = ({ teacherId, logs } = {}) => {
  const tId = String(teacherId || "").trim();
  const events = Array.isArray(adminStudentsState.events) ? adminStudentsState.events : [];
  const logsArr = Array.isArray(logs) ? logs : [];
  const studentsById = adminStudentsState.studentsById instanceof Map ? adminStudentsState.studentsById : new Map();

  const eventsById = new Map();
  events.forEach((evt) => {
    if (!evt || typeof evt !== "object") return;
    if (!evt.id) return;
    eventsById.set(String(evt.id), evt);
  });

  const lastEventByAluno = new Map();
  events.forEach((evt) => {
    if (!evt || typeof evt !== "object") return;
    if (evt.type !== "lesson") return;
    const a = String(evt.alunoId || "").trim();
    if (!a) return;
    if (tId && String(evt.professorId || "") !== tId) return;
    const prev = lastEventByAluno.get(a) || null;
    if (!prev) {
      lastEventByAluno.set(a, evt);
      return;
    }
    const pk = String(prev.dateKey || "");
    const nk = String(evt.dateKey || "");
    if (nk && pk && nk !== pk) {
      if (nk > pk) lastEventByAluno.set(a, evt);
      return;
    }
    const ps = Number(prev.startMin) || 0;
    const ns = Number(evt.startMin) || 0;
    if (ns > ps) lastEventByAluno.set(a, evt);
  });

  const alunoIds = new Set();
  if (!tId) {
    // School-wide: start with all registered students.
    studentsById.forEach((_v, k) => {
      const id = String(k || "").trim();
      if (id) alunoIds.add(id);
    });
    // Also include any student ids present in events/logs even if the user doc is missing.
    events
      .filter((evt) => evt && typeof evt === "object" && evt.type === "lesson" && evt.alunoId)
      .forEach((evt) => alunoIds.add(String(evt.alunoId)));
  } else {
    events
      .filter((evt) => evt && typeof evt === "object" && evt.type === "lesson" && String(evt.professorId || "") === tId)
      .forEach((evt) => {
        const a = String(evt.alunoId || "").trim();
        if (a) alunoIds.add(a);
      });
  }
  logsArr.forEach((log) => {
    const a = String(log?.alunoId || "").trim();
    const p = String(log?.professorId || "").trim();
    if (a && (!tId || p === tId)) alunoIds.add(a);
  });

  const perAluno = new Map();
  logsArr.forEach((log) => {
    if (!log || typeof log !== "object") return;
    if (tId && String(log.professorId || "") !== tId) return;
    const alunoId = String(log.alunoId || "").trim();
    if (!alunoId) return;
    const bucket = perAluno.get(alunoId) || { total: 0, faltas: 0, remarcadas: 0, lastLog: null, lastRisk: "", hasAlert: false };
    bucket.total += 1;
    const status = String(log.statusAula || "").trim().toLowerCase();
    if (status === "falta_aluno") bucket.faltas += 1;
    if (status === "remarcada") bucket.remarcadas += 1;

    const updatedAt = String(log.atualizadoEm || log.criadoEm || "").trim();
    const candidateMs = updatedAt ? Date.parse(updatedAt) : NaN;
    const lastMs = bucket.lastLog?.atualizadoEm ? Date.parse(String(bucket.lastLog.atualizadoEm)) : NaN;
    if (!bucket.lastLog || (Number.isFinite(candidateMs) && (!Number.isFinite(lastMs) || candidateMs > lastMs))) {
      bucket.lastLog = log;
    }

    const risk = String(log?.payload?.riscoEvasao || log?.payload?.risco_evasao || "").trim().toLowerCase();
    if (risk && (risk === "baixo" || risk === "medio" || risk === "médio" || risk === "alto")) {
      bucket.lastRisk = risk;
    }

    const avisos = Array.isArray(log?.payload?.avisosCoordenacao) ? log.payload.avisosCoordenacao : [];
    const needsAlert =
      log?.payload?.precisaIntervencao === true ||
      avisos.some((v) => String(v).startsWith("🔴") || String(v).startsWith("🟡")) ||
      (status === "remarcada" && String(log?.payload?.motivoRemarcacao || "") === "professor_remarcou");
    if (needsAlert) bucket.hasAlert = true;
    perAluno.set(alunoId, bucket);
  });

  const teacherMeta = tId ? (adminStudentsState.teachersById instanceof Map ? adminStudentsState.teachersById.get(tId) || null : null) : null;

  const summaries = Array.from(alunoIds)
    .map((alunoId) => {
      const meta = studentsById.get(alunoId) || null;
      const bucket = perAluno.get(alunoId) || { total: 0, faltas: 0, remarcadas: 0, lastLog: null, lastRisk: "", hasAlert: false };
      const lastLog = bucket.lastLog;
      let lastLabel = "—";
      if (lastLog?.eventId) {
        const evt = eventsById.get(String(lastLog.eventId)) || null;
        if (evt && evt.dateKey) {
          lastLabel = `${formatPedagogicoDate(evt.dateKey)} • ${formatHmFromMinutes(evt.startMin)}–${formatHmFromMinutes(evt.endMin)}`;
        } else if (lastLog.dateKey) {
          lastLabel = formatPedagogicoDate(lastLog.dateKey);
        }
      } else if (lastLog?.dateKey) {
        lastLabel = formatPedagogicoDate(lastLog.dateKey);
      }
      const lastEvent = lastEventByAluno.get(alunoId) || null;
      if (lastLabel === "—" && lastEvent && lastEvent.dateKey) {
        lastLabel = `${formatPedagogicoDate(lastEvent.dateKey)} • ${formatHmFromMinutes(lastEvent.startMin)}–${formatHmFromMinutes(lastEvent.endMin)}`;
      }

      const riskLabel = normalizeRiskLabel(bucket.lastRisk) || "Sem dados";
      const lifecycleBadge = meta ? getStudentLifecycleBadgeMeta(meta) : { label: "", state: "", tone: "" };
      const lifecycleState = lifecycleBadge.state || (meta ? getStudentLifecycleState(meta) : STUDENT_LIFECYCLE_STATE.ACTIVE);
      const statusLabel = lifecycleBadge.label || (meta ? (meta.ativo ? "Ativo" : "Inativo") : "—");

      const inferredTeacherId =
        tId ||
        String(meta?.professorId || "").trim() ||
        String(lastEvent?.professorId || "").trim() ||
        String(lastLog?.professorId || "").trim() ||
        "";
      const inferredTeacher =
        inferredTeacherId && adminStudentsState.teachersById instanceof Map ? adminStudentsState.teachersById.get(inferredTeacherId) || null : null;

      return {
        alunoId,
        nome: meta?.nome || "Aluno",
        email: meta?.email || "",
        ativo: typeof meta?.ativo === "boolean" ? meta.ativo : true,
        lifecycleState,
        statusLabel,
        teacherId: inferredTeacherId,
        teacherName: inferredTeacher?.nome || teacherMeta?.nome || "—",
        firestoreDocId: String(meta?.firestoreDocId || alunoId || "").trim(),
        plano: String(meta?.plano || "").trim(),
        pais: String(meta?.pais || "").trim(),
        estadoEua: String(meta?.estadoEua || "").trim(),
        trabalho: String(meta?.trabalho || "").trim(),
        criadoKey: String(meta?.criadoKey || ""),
        cancelKey: String(meta?.cancelKey || ""),
        desativadoKey: String(meta?.desativadoKey || meta?.cancelKey || ""),
        criadoLabel: meta?.criadoEm ? formatAdminDate(meta.criadoEm) : "—",
        cancelLabel: meta?.canceladoEm ? formatAdminDate(meta.canceladoEm) : "—",
        desativadoLabel: meta?.desativadoEm ? formatAdminDate(meta.desativadoEm) : "—",
        lastLessonLabel: lastLabel,
        totalLogs: bucket.total,
        faltas: bucket.faltas,
        remarcadas: bucket.remarcadas,
        riskLabel,
        hasAlert: Boolean(bucket.hasAlert),
      };
    })
    .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"));

  return { summaries, logsByAluno: perAluno, eventsById, teacherMeta };
};

const refreshAdminStudentsDerivedState = () => {
  const derived = deriveAdminStudentsSummaries({ teacherId: "", logs: adminStudentsState.logs });
  adminStudentsState.summariesAll = Array.isArray(derived?.summaries) ? derived.summaries : [];
  applyAdminStudentsFilters();
};

const renderAdminStudentsList = () => {
  if (!(adminStudentsList instanceof HTMLElement)) return;
  if (adminStudentsError instanceof HTMLElement) adminStudentsError.hidden = true;

  const summaries = Array.isArray(adminStudentsState.summaries) ? adminStudentsState.summaries : [];
  const allSummaries = Array.isArray(adminStudentsState.summariesAll) ? adminStudentsState.summariesAll : [];
  if (adminStudentsCount instanceof HTMLElement) {
    adminStudentsCount.textContent = formatAdminStudentsCountLabel(summaries.length, allSummaries.length);
  }

  if (adminStudentsEmpty instanceof HTMLElement) {
    adminStudentsEmpty.hidden = summaries.length > 0;
    if (summaries.length === 0) adminStudentsEmpty.textContent = "Nenhum aluno encontrado.";
  }

  adminStudentsList.innerHTML = summaries
    .map((row) => {
      const alertBadge = row.hasAlert ? `<span class="admin-students-alert">Alerta</span>` : "";
      const statusTone = row.statusLabel === "Ativo" ? "green" : row.statusLabel === "Inativo" ? "gray" : "muted";
      const statusPill = row.statusLabel ? `<span class="admin-students-chip is-${statusTone}">${escapeHtml(row.statusLabel)}</span>` : "";
      const teacherChip =
        row.teacherName && row.teacherName !== "—" ? `<span class="admin-students-chip">${escapeHtml(row.teacherName)}</span>` : "";
      const planChip = row.plano ? `<span class="admin-students-chip">${escapeHtml(row.plano)}</span>` : "";
      const countryChip = row.pais ? `<span class="admin-students-chip is-country">${escapeHtml(row.pais)}</span>` : "";
      const chips = [statusPill, teacherChip, planChip, countryChip].filter(Boolean).join("");

      return `
        <div class="admin-students-row" role="button" tabindex="0" data-admin-student-open="${escapeHtml(row.firestoreDocId || row.alunoId)}">
          <div class="admin-students-avatar" aria-hidden="true">${escapeHtml(getInitials(row.nome))}</div>
          <div class="admin-students-main">
            <div class="admin-students-name">
              <span>${escapeHtml(row.nome)}</span>
              ${alertBadge}
            </div>
            <div class="admin-students-chips">${chips || `<span class="admin-students-chip is-muted">Sem tags</span>`}</div>
          </div>
        </div>
      `;
    })
    .join("");
};

