const updateAdminTeacherCachedRow = (teacherId, patch = {}) => {
  const id = String(teacherId || "").trim();
  if (!id) return null;
  if (adminTeachersState.history?.teacherMeta && String(adminTeachersState.history.teacherMeta.id || "") === id) {
    adminTeachersState.history.teacherMeta = { ...adminTeachersState.history.teacherMeta, ...patch };
  }
  if (adminPedagogicoState.teachersById instanceof Map) {
    const prev = adminPedagogicoState.teachersById.get(id);
    if (prev) adminPedagogicoState.teachersById.set(id, { ...prev, ...patch });
  }
  if (Array.isArray(adminPedagogicoState.teachers)) {
    adminPedagogicoState.teachers = adminPedagogicoState.teachers.map((row) => (String(row?.id || "") === id ? { ...row, ...patch } : row));
  }
  if (Array.isArray(adminUsersState.teacher?.rows)) {
    adminUsersState.teacher.rows = adminUsersState.teacher.rows.map((row) => (String(row?.id || "") === id ? { ...row, ...patch } : row));
  }
  return adminPedagogicoState.teachersById instanceof Map ? adminPedagogicoState.teachersById.get(id) || null : null;
};

const saveAdminTeacherInlinePatch = async ({ teacherId, patch = {} } = {}) => {
  const id = String(teacherId || "").trim();
  if (!id) throw new Error("missing_teacher_id");
  const cleanPatch = Object.fromEntries(Object.entries(patch || {}).filter(([, value]) => value !== undefined));
  const response = await withTimeout(
    fetchWithAuth("/api/admin-users", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        uid: id,
        patch: cleanPatch,
      }),
    }),
    12_000,
    "admin_teacher_inline_patch"
  );
  const data = await response.json().catch(() => null);
  if (!response.ok) throw new Error(data?.error || "admin_teacher_inline_patch_failed");
  updateAdminTeacherCachedRow(id, cleanPatch);
  return true;
};

const resolveAdminTeacherInlinePatch = ({ field, value } = {}) => {
  const key = String(field || "").trim();
  const nextValue = String(value || "").trim();
  if (!key) return null;
  if (key === "email") {
    return {
      patch: { email: nextValue.toLowerCase() },
      displayValue: nextValue || "—",
    };
  }
  if (key === "telefone") {
    return {
      patch: { telefone: nextValue },
      displayValue: nextValue || "—",
    };
  }
  if (key === "especialidade") {
    return {
      patch: { especialidade: nextValue, specialty: nextValue },
      displayValue: nextValue || "—",
    };
  }
  if (key === "criadoEm") {
    if (!nextValue) return null;
    const date = new Date(`${nextValue}T12:00:00`);
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    const iso = date.toISOString();
    return {
      patch: { criadoEm: iso },
      displayValue: formatAdminDate(iso),
    };
  }
  return null;
};

const saveAdminTeacherInlineField = async ({ field, sheetEl } = {}) => {
  const hist = adminTeachersState.history;
  const teacherId = String(hist?.teacherId || "").trim();
  if (!teacherId) return;
  const cell = getAdminTeacherInlineCell(sheetEl, field);
  if (!(cell instanceof HTMLElement)) return;
  const control = cell.querySelector("[data-admin-teacher-inline-control]");
  if (hist.inlineSavingField) return;
  const currentValue = String(cell.dataset.currentValue || "").trim();
  const nextValue = control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement ? String(control.value || "").trim() : "";
  if (nextValue === currentValue) {
    cancelAdminTeacherInlineEditing({ sheetEl, field });
    return;
  }
  const resolved = resolveAdminTeacherInlinePatch({ field, value: nextValue });
  if (!resolved) {
    cancelAdminTeacherInlineEditing({ sheetEl, field });
    return;
  }
  const saveLabel =
    field === "email" ? "Salvando e-mail…" : field === "telefone" ? "Salvando telefone…" : field === "especialidade" ? "Salvando especialidade…" : "Salvando…";
  hist.inlineSavingField = field;
  setAdminTeacherInlineStatus(sheetEl, field, saveLabel, "loading");
  if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) control.disabled = true;
  try {
    await saveAdminTeacherInlinePatch({ teacherId, patch: resolved.patch });
    updateAdminTeacherCachedRow(teacherId, resolved.patch);
    setAdminTeacherInlineDisplay(sheetEl, field, resolved.displayValue);
    setAdminTeacherInlineStatus(sheetEl, field, "Salvo ✓", "success");
    if (hist.inlineSaveTimer) window.clearTimeout(hist.inlineSaveTimer);
    hist.inlineSaveTimer = window.setTimeout(() => {
      if (hist.inlineSavingField !== field) return;
      hist.inlineSavingField = "";
      hist.editingField = "";
      hist.inlineSaveTimer = 0;
      renderAdminTeacherSheet();
      renderAdminPedagogicoTeachersPanel();
    }, 2000);
  } catch (error) {
    console.error("[admin] teacher inline save failed:", error);
    setAdminTeacherInlineStatus(sheetEl, field, "Não foi possível salvar agora.", "error");
    hist.inlineSavingField = "";
    if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) {
      control.disabled = false;
      control.focus?.();
    }
  } finally {
    if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) {
      control.disabled = hist.inlineSavingField === field;
    }
  }
};

const updateAdminStudentCachedRow = (alunoId, patch = {}) => {
  const rawId = String(alunoId || "").trim();
  if (!rawId) return null;
  const aliasMap = adminStudentsState.studentAliasToDocId instanceof Map ? adminStudentsState.studentAliasToDocId : new Map();
  const id = String(aliasMap.get(rawId) || rawId).trim();
  if (adminStudentsState.history?.alunoMeta && String(adminStudentsState.history.alunoMeta.id || "") === id) {
    adminStudentsState.history.alunoMeta = mergeAdminStudentWithCachedProfile(adminStudentsState.history.alunoMeta, patch);
  }
  if (adminStudentsState.studentsById instanceof Map) {
    const prev = adminStudentsState.studentsById.get(id);
    if (prev) adminStudentsState.studentsById.set(id, mergeAdminStudentWithCachedProfile(prev, patch));
  }
  if (Array.isArray(adminStudentsState.students)) {
    adminStudentsState.students = adminStudentsState.students.map((row) =>
      String(row?.id || "") === id ? mergeAdminStudentWithCachedProfile(row, patch) : row
    );
  }
  if (adminPedagogicoState.studentsById instanceof Map) {
    const prev = adminPedagogicoState.studentsById.get(id);
    if (prev) adminPedagogicoState.studentsById.set(id, mergeAdminStudentWithCachedProfile(prev, patch));
  }
  if (Array.isArray(adminPedagogicoState.students)) {
    adminPedagogicoState.students = adminPedagogicoState.students.map((row) =>
      String(row?.id || "") === id ? mergeAdminStudentWithCachedProfile(row, patch) : row
    );
  }
  if (Array.isArray(adminUsersState.student?.rows)) {
    adminUsersState.student.rows = adminUsersState.student.rows.map((row) =>
      String(row?.id || "") === id ? mergeAdminStudentWithCachedProfile(row, patch) : row
    );
  }
  const updated = getAdminStudentMetaById(id);
  if (updated) {
    adminStudentsState.studentAliasToDocId = buildStudentAliasMap(adminStudentsState.students);
    adminPedagogicoState.studentAliasToDocId = buildStudentAliasMap(adminPedagogicoState.students);
    refreshAdminStudentsDerivedState();
  }
  return updated;
};

const mergeAdminStudentWithCachedProfile = (existingStudent, incomingStudent) => {
  const prev = existingStudent && typeof existingStudent === "object" ? existingStudent : null;
  const next = incomingStudent && typeof incomingStudent === "object" ? incomingStudent : null;
  if (!next) return prev;
  if (!prev) return next;
  const pickName = (...candidates) => {
    for (const candidate of candidates) {
      const safe = String(candidate || "").trim();
      if (!safe) continue;
      if (safe.toLowerCase() === "aluno sem nome") continue;
      return safe;
    }
    return "";
  };
  const nextName = pickName(next.nome, next.nomeCompleto, next.name, next.displayName);
  const prevName = pickName(prev.nome, prev.nomeCompleto, prev.name, prev.displayName);
  const nextEmail = String(next.email || "").trim();
  const prevEmail = String(prev.email || "").trim();
  const nextPhone = String(next.telefone || "").trim();
  const firestoreNome = String(next.firestoreNome || prev.firestoreNome || "").trim();
  const firestoreEmail = String(next.firestoreEmail || prev.firestoreEmail || "").trim();
  const firestoreTelefone = String(next.firestoreTelefone || prev.firestoreTelefone || "").trim();
  const firestorePlano = String(next.firestorePlano || prev.firestorePlano || "").trim();
  const firestoreProfessorId = String(next.firestoreProfessorId || prev.firestoreProfessorId || "").trim();
  const firestoreProfessorNome = String(next.firestoreProfessorNome || prev.firestoreProfessorNome || "").trim();
  const firestoreTipo = String(next.firestoreTipo || prev.firestoreTipo || "").trim();
  const supabaseNome = String(next.supabaseNome || prev.supabaseNome || "").trim();
  const supabaseEmail = String(next.supabaseEmail || prev.supabaseEmail || "").trim();
  const supabaseTelefone = String(next.supabaseTelefone || prev.supabaseTelefone || "").trim();
  const supabasePlano = String(next.supabasePlano || prev.supabasePlano || "").trim();
  const supabaseProfessorId = String(next.supabaseProfessorId || prev.supabaseProfessorId || "").trim();
  const nextTeacherName = String(next.professorNome || next.teacherNome || "").trim();
  const nextTeacherId = String(next.professorId || next.teacherId || "").trim();
  return {
    ...prev,
    ...next,
    nome: firestoreNome || nextName || prevName || supabaseNome || nextEmail || prevEmail || supabaseEmail || "Aluno sem nome",
    email: firestoreEmail || nextEmail || prevEmail || supabaseEmail,
    telefone: firestoreTelefone || nextPhone || String(prev.telefone || "").trim() || supabaseTelefone,
    professorNome: firestoreProfessorNome || nextTeacherName || String(prev.professorNome || prev.teacherNome || "").trim(),
    teacherNome: firestoreProfessorNome || nextTeacherName || String(prev.teacherNome || prev.professorNome || "").trim(),
    professorId: firestoreProfessorId || nextTeacherId || String(prev.professorId || prev.teacherId || "").trim() || supabaseProfessorId,
    teacherId: firestoreProfessorId || nextTeacherId || String(prev.teacherId || prev.professorId || "").trim() || supabaseProfessorId,
    plano: firestorePlano || String(next.plano || "").trim() || String(prev.plano || "").trim() || supabasePlano,
    turma: String(next.turma || "").trim() || String(prev.turma || "").trim(),
    tipo: firestoreTipo || String(next.tipo || prev.tipo || "student"),
    cancelamento: next.firestoreCancelamento ?? prev.firestoreCancelamento ?? next.cancelamento ?? prev.cancelamento ?? null,
    cancelamentosAnteriores: Array.isArray(next.cancelamentosAnteriores)
      ? next.cancelamentosAnteriores
      : Array.isArray(prev.cancelamentosAnteriores)
        ? prev.cancelamentosAnteriores
        : [],
    ativo:
      typeof next.firestoreAtivo === "boolean"
        ? next.firestoreAtivo
        : typeof prev.firestoreAtivo === "boolean"
          ? prev.firestoreAtivo
          : typeof next.ativo === "boolean"
            ? next.ativo
            : typeof prev.ativo === "boolean"
              ? prev.ativo
              : true,
    canceladoEm: next.canceladoEm || next.cancelamentoEm || next.dataCancelamento || prev.canceladoEm || prev.cancelamentoEm || prev.dataCancelamento || null,
    desativadoEm: next.desativadoEm || prev.desativadoEm || next.canceladoEm || prev.canceladoEm || null,
    criadoEm: next.criadoEm || next.createdAt || next.created_at || prev.criadoEm || prev.createdAt || prev.created_at || null,
    sourceBusinessId: String(next.sourceBusinessId || prev.sourceBusinessId || next.userId || prev.userId || next.alunoId || prev.alunoId || "").trim(),
    firestoreDocId: String(next.firestoreDocId || next.firestoreDocIdRef || prev.firestoreDocId || prev.firestoreDocIdRef || next.id || prev.id || "").trim(),
    firestoreDocIdRef: String(next.firestoreDocIdRef || prev.firestoreDocIdRef || "").trim(),
    docId: String(next.docId || prev.docId || next.firestoreDocId || prev.firestoreDocId || "").trim(),
    documentId: String(next.documentId || prev.documentId || next.firestoreDocId || prev.firestoreDocId || "").trim(),
    id: String(next.id || next.firestoreDocId || prev.id || prev.firestoreDocId || "").trim(),
  };
};

const getAdminStudentMergeKeys = (row = {}) => {
  const keys = new Set();
  const email = String(row?.email || "").trim().toLowerCase();
  if (email) keys.add(`email:${email}`);
  const phone = String(row?.telefone || "").replace(/\D+/g, "");
  if (phone) keys.add(`phone:${phone}`);
  const sourceBusinessId = String(row?.sourceBusinessId || row?.alunoChave || row?.aluno_chave || "").trim();
  if (sourceBusinessId) keys.add(`source:${sourceBusinessId}`);
  const firestoreDocIdRef = String(row?.firestoreDocIdRef || row?.firestore_doc_id || "").trim();
  if (firestoreDocIdRef) keys.add(`id:${firestoreDocIdRef}`);
  getStudentIdentityAliases(row).forEach((alias) => {
    const safe = String(alias || "").trim();
    if (safe) keys.add(`id:${safe}`);
  });
  const fallbackId = String(row?.id || "").trim();
  if (fallbackId) keys.add(`id:${fallbackId}`);
  return Array.from(keys);
};

window.auditLegacyStudentFlags = () => {
  const students = Array.isArray(adminStudentsState.students) ? adminStudentsState.students : [];
  const flagged = students
    .filter((student) => {
      if (!student || typeof student !== "object") return false;
      const cancelamento = normalizeStudentCancellationRecord(student.cancelamento);
      const hasEffectiveCancellation = Boolean(cancelamento?.desfecho) || Boolean(cancelamento?.dataEfetivacao);
      const hasLegacyInactiveFlag =
        student.ativo === false || Boolean(student.canceladoEm || student.cancelamentoEm || student.desativadoEm || student.dataCancelamento);
      return hasLegacyInactiveFlag && !hasEffectiveCancellation;
    })
    .map((student) => ({
      firestoreDocId: String(student.firestoreDocId || student.docId || student.documentId || student.id || "").trim(),
      nome: String(student.nome || student.nomeCompleto || student.name || student.email || "Aluno sem nome").trim(),
      ativo: student.ativo,
      canceladoEm: student.canceladoEm || student.cancelamentoEm || student.dataCancelamento || null,
      desativadoEm: student.desativadoEm || null,
      cancelamento: student.cancelamento || null,
      lifecycleState: getStudentLifecycleState(student),
    }));
  console.groupCollapsed(`[auditLegacyStudentFlags] ${flagged.length} aluno(s) com flags legadas`);
  console.table(flagged);
  console.groupEnd();
  return flagged;
};

window.auditOwnership = () => {
  const students = Array.isArray(adminStudentsState.students) ? adminStudentsState.students : [];
  const drift = students
    .map((student) => {
      if (!student || typeof student !== "object") return null;
      const diffs = [];
      const compare = (field, left, right) => {
        const a = String(left || "").trim();
        const b = String(right || "").trim();
        if (!a || !b) return;
        if (a.toLowerCase() !== b.toLowerCase()) diffs.push({ field, firestore: a, supabase: b });
      };
      compare("nome", student.firestoreNome, student.supabaseNome);
      compare("email", student.firestoreEmail, student.supabaseEmail);
      compare("telefone", student.firestoreTelefone, student.supabaseTelefone);
      compare("plano", student.firestorePlano, student.supabasePlano);
      compare("professorId", student.firestoreProfessorId, student.supabaseProfessorId);
      if (!diffs.length) return null;
      return {
        firestoreDocId: String(student.firestoreDocId || student.id || "").trim(),
        nome: String(student.nome || student.firestoreNome || student.supabaseNome || "Aluno sem nome").trim(),
        diffs,
      };
    })
    .filter(Boolean);
  console.groupCollapsed(`[auditOwnership] ${drift.length} divergência(s) cadastro Firestore vs espelho Supabase`);
  drift.forEach((item) => console.log(item));
  console.groupEnd();
  return drift;
};

const saveAdminStudentInlinePatch = async ({ alunoId, patch = {} } = {}) => {
  const id = String(alunoId || "").trim();
  if (!id) throw new Error("missing_student_id");
  const cleanPatch = Object.fromEntries(Object.entries(patch || {}).filter(([, value]) => value !== undefined));
  const response = await withTimeout(
    fetchWithAuth("/api/admin-users", {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        uid: id,
        patch: cleanPatch,
      }),
    }),
    12_000,
    "admin_student_inline_patch"
  );
  const data = await response.json().catch(() => null);
  if (!response.ok) {
    throw new Error(data?.error || "admin_student_inline_patch_failed");
  }
  updateAdminStudentCachedRow(id, cleanPatch);
  return true;
};

const resolveAdminStudentInlinePatch = ({ field, value, alunoMeta } = {}) => {
  const key = String(field || "").trim();
  const nextValue = String(value || "").trim();
  if (!key) return null;
  if (key === "email") {
    return {
      patch: {
        email: nextValue.toLowerCase(),
      },
      displayValue: nextValue || "—",
    };
  }
  if (key === "telefone") {
    return {
      patch: {
        telefone: nextValue,
      },
      displayValue: nextValue || "—",
    };
  }
  if (key === "professorId") {
    const teachers = Array.isArray(adminStudentsState.teachers) ? adminStudentsState.teachers : [];
    const teacher = teachers.find((item) => String(item?.id || "") === nextValue) || null;
    return {
      patch: {
        professorId: nextValue,
        teacherId: nextValue,
        professorNome: teacher?.nome || "",
        teacherNome: teacher?.nome || "",
      },
      displayValue: teacher?.nome || "Sem professor",
    };
  }
  if (key === "turma") {
    const classes = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
    const found = classes.find((item) => {
      const id = String(item?.id || item?.groupId || item?.classId || "").trim();
      const label = String(item?.nome || item?.name || item?.title || item?.groupName || item?.className || "").trim();
      return nextValue && (id === nextValue || label === nextValue);
    }) || null;
    const label = String(found?.nome || found?.name || found?.title || found?.groupName || found?.className || nextValue || "").trim();
    const id = String(found?.id || found?.groupId || found?.classId || label).trim();
    return {
      patch: {
        groupId: id,
        groupName: label,
        turma: label,
        turmaNome: label,
        classId: id,
        className: label,
      },
      displayValue: label || "Sem turma",
    };
  }
  if (key === "english_level_start") {
    const normalized = normalizeAdminStudentEnglishStartValue(nextValue);
    return {
      patch: {
        english_level_start: normalized,
        englishLevelStart: normalized,
      },
      displayValue: normalized || "—",
    };
  }
  if (key === "criadoEm") {
    if (!nextValue) return null;
    const date = new Date(`${nextValue}T12:00:00`);
    if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
    const iso = date.toISOString();
    return {
      patch: {
        criadoEm: iso,
      },
      displayValue: formatAdminDate(iso),
    };
  }
  return null;
};

const saveAdminStudentInlineField = async ({ field, sheetEl } = {}) => {
  const hist = adminStudentsState.history;
  const alunoId = String(hist?.alunoId || "").trim();
  if (!alunoId) return;
  const cell = getAdminStudentInlineCell(sheetEl, field);
  if (!(cell instanceof HTMLElement)) return;
  const control = cell.querySelector("[data-admin-student-inline-control]");
  const statusEl = cell.querySelector("[data-admin-student-inline-status]");
  if (hist.inlineSavingField) return;
  const currentValue = String(cell.dataset.currentValue || "").trim();
  const nextValue = control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement ? String(control.value || "").trim() : "";
  if (String(nextValue || "").trim() === String(currentValue || "").trim()) {
    cancelAdminStudentInlineEditing({ sheetEl, field });
    return;
  }
  const resolved = resolveAdminStudentInlinePatch({ field, value: nextValue, alunoMeta: hist.alunoMeta });
  if (!resolved) {
    cancelAdminStudentInlineEditing({ sheetEl, field });
    return;
  }

  const saveLabel =
    field === "email"
      ? "Salvando e-mail…"
      : field === "telefone"
        ? "Salvando telefone…"
        : field === "professorId"
          ? "Salvando professor…"
          : field === "turma"
            ? "Salvando turma…"
            : field === "english_level_start"
              ? "Salvando nível…"
              : "Salvando…";
  hist.inlineSavingField = field;
  setAdminStudentInlineStatus(sheetEl, field, saveLabel, "loading");
  if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) control.disabled = true;

  try {
    await saveAdminStudentInlinePatch({ alunoId, patch: resolved.patch });
    updateAdminStudentCachedRow(alunoId, resolved.patch);
    setAdminStudentInlineDisplay(sheetEl, field, resolved.displayValue);
    setAdminStudentInlineStatus(sheetEl, field, "Salvo ✓", "success");
    if (hist.inlineSaveTimer) window.clearTimeout(hist.inlineSaveTimer);
    hist.inlineSaveTimer = window.setTimeout(() => {
      if (hist.inlineSavingField !== field) return;
      hist.inlineSavingField = "";
      hist.editingField = "";
      hist.inlineSaveTimer = 0;
      renderAdminStudentSheet();
    }, 2000);
  } catch (error) {
    console.error("[admin] student inline save failed:", error);
    const message = "Não foi possível salvar agora.";
    setAdminStudentInlineStatus(sheetEl, field, message, "error");
    setAdminStudentsStatus(message, "error");
    hist.inlineSavingField = "";
    if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) {
      control.disabled = false;
      control.focus?.();
    }
  } finally {
    if (control instanceof HTMLInputElement || control instanceof HTMLSelectElement || control instanceof HTMLTextAreaElement) {
      control.disabled = hist.inlineSavingField === field;
    }
  }
};

const buildAdminStudentCommentItem = (row = {}) => {
  const id = String(
    row.id ||
      row.commentId ||
      row.docId ||
      (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function" ? crypto.randomUUID() : `comment_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`)
  ).trim();
  const createdAt = String(row.criadoEm || row.createdAt || row.updatedAt || "").trim();
  const ms = createdAt ? Date.parse(createdAt) : NaN;
  return {
    kind: "comment",
    id,
    alunoId: String(row.alunoId || "").trim(),
    professorId: String(row.professorId || row.autorId || "").trim(),
    createdAt,
    sortMs: Number.isFinite(ms) ? ms : Date.now(),
    title: "Comentário",
    summaryText: String(row.texto || row.comment || row.comentario || "").trim(),
    professorName: String(row.autorNome || row.autorNomeCompleto || "").trim(),
    authorName: String(row.autorNome || row.autorNomeCompleto || "").trim(),
    noteTone: "blue",
    raw: row,
  };
};

const fetchAdminStudentCommentsFromFirestore = async () => {
  try {
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_student_comments");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) {
      const e = new Error("firebase_not_authenticated");
      e.code = "auth/no-current-user";
      throw e;
    }
    const q = firebase.query(firebase.collection(firebase.primaryDb, "lessonLogs"));
    const snap = await withTimeout(firebase.getDocs(q), 12_000, "firestore_getDocs_lessonLogs_comments");
    const comments = [];
    snap.forEach((docSnap) => {
      const data = docSnap.data ? docSnap.data() : null;
      if (!data || typeof data !== "object") return;
      const type = String(data.type || data.tipo || "").trim().toLowerCase();
      if (type !== "comentario" && type !== "comment") return;
      comments.push({
        id: docSnap.id,
        alunoId: typeof data.alunoId === "string" ? data.alunoId.trim() : "",
        texto: typeof data.texto === "string" ? data.texto.trim() : typeof data.comment === "string" ? data.comment.trim() : typeof data.comentario === "string" ? data.comentario.trim() : "",
        autorId: typeof data.autorId === "string" ? data.autorId.trim() : "",
        autorNome: typeof data.autorNome === "string" ? data.autorNome.trim() : "",
        professorId: typeof data.professorId === "string" ? data.professorId.trim() : "",
        criadoEm: data.criadoEm ? (typeof data.criadoEm?.toDate === "function" ? data.criadoEm.toDate().toISOString() : String(data.criadoEm)) : "",
        atualizadoEm: data.atualizadoEm ? (typeof data.atualizadoEm?.toDate === "function" ? data.atualizadoEm.toDate().toISOString() : String(data.atualizadoEm)) : "",
        type,
      });
    });
    return comments;
  } catch (error) {
    console.warn("[admin] fetchAdminStudentCommentsFromFirestore falling back to admin-data:", error?.message || error);
    const response = await fetchWithAuth("/api/admin-data?collection=lessonLogs", { method: "GET" });
    if (!response.ok) return [];
    const payload = await response.json().catch(() => null);
    const rows = Array.isArray(payload?.rows) ? payload.rows : [];
    return rows
      .filter((row) => {
        const type = String(row?.type || row?.tipo || "").trim().toLowerCase();
        return type === "comentario" || type === "comment";
      })
      .map((row) => ({
        id: String(row?.id || row?.commentId || row?.docId || "").trim(),
        alunoId: String(row?.alunoId || "").trim(),
        texto: String(row?.texto || row?.comment || row?.comentario || "").trim(),
        autorId: String(row?.autorId || "").trim(),
        autorNome: String(row?.autorNome || "").trim(),
        professorId: String(row?.professorId || "").trim(),
        criadoEm: row?.criadoEm || row?.createdAt || row?.updatedAt || "",
        atualizadoEm: row?.atualizadoEm || row?.updatedAt || "",
        type: "comentario",
      }));
  }
};

