const setAdminPedagogicoStatus = (text, tone = "", detail = "") => {
  if (!(adminPedStatus instanceof HTMLElement)) return;
  adminPedStatus.textContent = String(text || "");
  adminPedStatus.dataset.tone = String(tone || "");
  adminPedStatus.title = String(detail || "");
};

const normalizeClassType = (value) => {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "group" || raw === "grupo" || raw === "em_grupo") return "group";
  return "individual";
};

const normalizeClassStatus = (value) => {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "paused" || raw === "pausada" || raw === "pausado") return "paused";
  if (
    raw === "ended" ||
    raw === "encerrada" ||
    raw === "encerrado" ||
    raw === "inactive" ||
    raw === "inativa" ||
    raw === "inativo" ||
    raw === "cancelado" ||
    raw === "cancelada" ||
    raw === "cancelled" ||
    raw === "canceled" ||
    raw === "deleted"
  )
    return "ended";
  return "active";
};

const normalizePlanKeyLoose = (value) => {
  const raw = String(value || "").trim().toLowerCase();
  if (!raw) return "";
  if (raw.includes("diamond")) return "diamond";
  if (raw.includes("gold")) return "gold";
  if (raw.includes("turma")) return "turma";
  return raw;
};

const slugifyClassRoomPart = (value) =>
  String(value || "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 64);

const buildAdminPedShortRoomSlug = (classId) => {
  const raw = String(classId || "").trim();
  if (!raw) return Math.random().toString(36).slice(2, 10);
  const compact = raw
    .replace(/^class[_-]?/i, "")
    .replace(/[^a-z0-9]+/gi, "")
    .toLowerCase();
  return compact || Math.random().toString(36).slice(2, 10);
};

const buildAdminPedClassLiveUrl = (classRow) => {
  const c = classRow && typeof classRow === "object" ? classRow : {};
  const shortRoomSlug = String(c.roomSlug || c.roomId || "").trim();
  const firstStudent = (Array.isArray(c.studentNames) && c.studentNames[0]) || (Array.isArray(c.studentIds) && c.studentIds[0]) || "";
  const title = c.title || c.groupName || (c.type === "group" ? "turma" : firstStudent) || "aula";
  const teacher = c.teacherName || c.teacherId || "professor";
  const days = (Array.isArray(c.daysOfWeek) ? c.daysOfWeek : []).map(daysLabelShort).join("-");
  const time = Number.isFinite(Number(c.startMin)) ? formatHmFromMinutes(c.startMin).replace(/:/g, "") : "";
  const legacyParts = [
    "space",
    "aula",
    slugifyClassRoomPart(title),
    slugifyClassRoomPart(firstStudent),
    slugifyClassRoomPart(teacher),
    slugifyClassRoomPart(days),
    slugifyClassRoomPart(time),
    slugifyClassRoomPart(c.id),
  ].filter(Boolean);
  const roomId = shortRoomSlug || legacyParts.join("-").slice(0, 180) || `space-aula-${Date.now()}`;
  const origin = typeof window !== "undefined" && window.location && window.location.origin ? window.location.origin : "";
  return `${origin}/sala/${encodeURIComponent(roomId)}`;
};

const normalizeDaysOfWeek = (value) => {
  const out = [];
  const arr = Array.isArray(value) ? value : [];
  arr.forEach((item) => {
    const n = Number(item);
    if (Number.isFinite(n) && n >= 0 && n <= 6) {
      if (!out.includes(n)) out.push(n);
      return;
    }
    const raw = String(item || "").trim().toLowerCase();
    const map = {
      mon: 1,
      monday: 1,
      seg: 1,
      tue: 2,
      tuesday: 2,
      ter: 2,
      wed: 3,
      wednesday: 3,
      qua: 3,
      thu: 4,
      thursday: 4,
      qui: 4,
      fri: 5,
      friday: 5,
      sex: 5,
      sat: 6,
      saturday: 6,
      sab: 6,
      dom: 0,
      sun: 0,
      sunday: 0,
    };
    const dow = map[raw];
    if (dow != null && !out.includes(dow)) out.push(dow);
  });
  out.sort((a, b) => a - b);
  return out;
};

const normalizeMinutesValue = (value) => {
  if (typeof value === "number" && Number.isFinite(value)) return clampInt(Math.round(value), 0, 24 * 60, 0);
  const raw = String(value || "").trim();
  if (!raw) return 0;
  if (/^\d{2}:\d{2}$/.test(raw)) {
    const mins = timeToMinutes(raw);
    return Number.isFinite(mins) ? clampInt(mins, 0, 24 * 60, 0) : 0;
  }
  const n = Number(raw);
  return Number.isFinite(n) ? clampInt(Math.round(n), 0, 24 * 60, 0) : 0;
};

const ADMIN_PED_WEEKLY_DAY_DEFS = [
  { weekday: 0, label: "Dom" },
  { weekday: 1, label: "Seg" },
  { weekday: 2, label: "Ter" },
  { weekday: 3, label: "Qua" },
  { weekday: 4, label: "Qui" },
  { weekday: 5, label: "Sex" },
  { weekday: 6, label: "Sáb" },
];

const normalizeAdminPedWeeklyScheduleDays = (value) => {
  const defaults = new Map(
    ADMIN_PED_WEEKLY_DAY_DEFS.map((def) => [def.weekday, { weekday: def.weekday, enabled: false, startTime: "", endTime: "" }])
  );
  const weekdayFromRaw = (raw) => {
    const direct = Number(raw);
    if (Number.isFinite(direct) && direct >= 0 && direct <= 6) return direct;
    const key = String(raw || "").trim().toLowerCase();
    const map = {
      dom: 0,
      sun: 0,
      sunday: 0,
      seg: 1,
      mon: 1,
      monday: 1,
      ter: 2,
      tue: 2,
      tuesday: 2,
      qua: 3,
      wed: 3,
      wednesday: 3,
      qui: 4,
      thu: 4,
      thursday: 4,
      sex: 5,
      fri: 5,
      friday: 5,
      sab: 6,
      sat: 6,
      saturday: 6,
    };
    return map[key] != null ? map[key] : null;
  };
  const applyItem = (item) => {
    if (!item || typeof item !== "object") return;
    const weekday = weekdayFromRaw(item.weekday ?? item.dow ?? item.day ?? item.diaSemana ?? item.value);
    if (!Number.isFinite(weekday) || weekday < 0 || weekday > 6) return;
    const current = defaults.get(weekday) || { weekday, enabled: false, startTime: "", endTime: "" };
    const startTime = String(item.startTime || item.start || item.horaInicio || item.startTimeValue || "").trim();
    const endTime = String(item.endTime || item.end || item.horaFim || item.endTimeValue || "").trim();
    const enabled = item.enabled === false ? false : Boolean(item.enabled ?? (startTime || endTime));
    defaults.set(weekday, {
      weekday,
      enabled,
      startTime: startTime || current.startTime || "",
      endTime: endTime || current.endTime || "",
    });
  };

  if (Array.isArray(value)) {
    value.forEach((item) => {
      if (item && typeof item === "object") {
        applyItem(item);
        return;
      }
      const weekday = Number(item);
      if (Number.isFinite(weekday) && weekday >= 0 && weekday <= 6) {
        const current = defaults.get(weekday);
        if (current) current.enabled = true;
      }
    });
  } else if (value && typeof value === "object") {
    Object.entries(value).forEach(([key, item]) => {
      const weekday = Number(key);
      if (Number.isFinite(weekday) && weekday >= 0 && weekday <= 6) {
        if (item && typeof item === "object") {
          applyItem({ weekday, ...item });
        } else {
          const current = defaults.get(weekday);
          if (current) current.enabled = Boolean(item);
        }
      }
    });
  }

  return ADMIN_PED_WEEKLY_DAY_DEFS.map((def) => defaults.get(def.weekday) || { weekday: def.weekday, enabled: false, startTime: "", endTime: "" });
};

const compactAdminPedName = (value, parts = 2) => {
  const tokens = String(value || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean);
  if (!tokens.length) return "";
  return tokens.slice(0, Math.max(1, parts)).join(" ");
};

const buildAdminPedLessonTitle = ({ studentName = "", teacherName = "" } = {}) => {
  const studentShort = compactAdminPedName(studentName, 2) || "Aluno";
  const teacherShort = compactAdminPedName(teacherName, 1) || "—";
  return `Aluno ${studentShort} + Prof. ${teacherShort}`;
};

const buildAdminPedWeeklyScheduleHtml = (scheduleDays) => {
  const rows = normalizeAdminPedWeeklyScheduleDays(scheduleDays);
  return rows
    .map((day) => {
      const dayDef = ADMIN_PED_WEEKLY_DAY_DEFS.find((def) => def.weekday === day.weekday) || ADMIN_PED_WEEKLY_DAY_DEFS[0];
      const enabled = Boolean(day.enabled);
      const startValue = enabled ? String(day.startTime || "").trim() : "";
      const endValue = enabled ? String(day.endTime || "").trim() : "";
      return `
        <div class="admin-ped-schedule-row ${enabled ? "is-active" : "is-disabled"}" data-admin-ped-schedule-row="${escapeHtml(String(day.weekday))}">
          <label class="admin-ped-schedule-day">
            <input type="checkbox" data-admin-ped-schedule-enabled="${escapeHtml(String(day.weekday))}" ${enabled ? "checked" : ""} />
            <span>${escapeHtml(dayDef.label)}</span>
          </label>
          <div class="admin-ped-schedule-times" data-admin-ped-schedule-times="${escapeHtml(String(day.weekday))}" ${enabled ? "" : "hidden"}>
            <label class="admin-ped-modal-field">
              <span>Início</span>
              <input class="admin-ped-modal-input" type="time" data-admin-ped-schedule-start="${escapeHtml(String(day.weekday))}" value="${escapeHtml(startValue)}" />
            </label>
            <label class="admin-ped-modal-field">
              <span>Fim</span>
              <input class="admin-ped-modal-input" type="time" data-admin-ped-schedule-end="${escapeHtml(String(day.weekday))}" value="${escapeHtml(endValue)}" />
            </label>
            <button class="admin-ped-schedule-copy" type="button" data-admin-ped-schedule-copy="${escapeHtml(String(day.weekday))}" aria-label="Copiar horário para os outros dias ativos">📋</button>
          </div>
          <div class="admin-ped-schedule-unavailable" data-admin-ped-schedule-unavailable="${escapeHtml(String(day.weekday))}" ${enabled ? "hidden" : ""}>Indisponível</div>
        </div>
      `;
    })
    .join("");
};

const formatAdminPedScheduleSummary = (row) => {
  const scheduleDays = normalizeAdminPedWeeklyScheduleDays(row?.scheduleDays || row?.repeatDays || row?.weeklySchedule || row?.schedule || []);
  const activeDays = scheduleDays.filter((day) => day && day.enabled && String(day.startTime || "").trim() && String(day.endTime || "").trim());
  if (activeDays.length) {
    return activeDays
      .map((day) => `${daysLabelShort(day.weekday)} ${String(day.startTime).slice(0, 5)}–${String(day.endTime).slice(0, 5)}`)
      .join(" · ");
  }
  const days = normalizeDaysOfWeek(row?.daysOfWeek || row?.weekDays || row?.diasSemana || []);
  const time =
    Number.isFinite(Number(row?.startMin)) && Number.isFinite(Number(row?.endMin)) && Number(row?.endMin) > Number(row?.startMin)
      ? `${formatHmFromMinutes(row.startMin)}–${formatHmFromMinutes(row.endMin)}`
      : "—";
  return `${days.map(daysLabelShort).join(", ") || "—"} · ${time}`;
};

const getAdminStudentLinkedClasses = (studentId) => {
  const safe = String(studentId || "").trim();
  if (!safe) return [];
  const rows = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  return rows
    .filter((row) => {
      const ids = Array.isArray(row?.studentIds) ? row.studentIds : [];
      return ids.map((id) => String(id || "").trim()).includes(safe);
    })
    .slice()
    .sort((a, b) => {
      const statusDiff =
        (normalizeClassStatus(a?.status) === "active" ? 0 : 1) - (normalizeClassStatus(b?.status) === "active" ? 0 : 1);
      if (statusDiff) return statusDiff;
      return (Number(b?.updatedAtMs || 0) || Number(b?.createdAtMs || 0)) - (Number(a?.updatedAtMs || 0) || Number(a?.createdAtMs || 0));
    });
};

const getAdminStudentLiveClassDiagnostics = () => {
  const classes = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  const studentsById = adminPedagogicoState.studentsById instanceof Map ? adminPedagogicoState.studentsById : new Map();
  const countsByStudentId = new Map();
  let orphanRows = 0;
  classes.forEach((row) => {
    const studentIds = Array.isArray(row?.studentIds) ? row.studentIds.map((id) => String(id || "").trim()).filter(Boolean) : [];
    if (!studentIds.length) {
      orphanRows += 1;
      return;
    }
    let rowHasRealStudent = false;
    studentIds.forEach((studentId) => {
      if (studentsById.has(studentId)) {
        rowHasRealStudent = true;
        countsByStudentId.set(studentId, Number(countsByStudentId.get(studentId) || 0) + 1);
      }
    });
    if (!rowHasRealStudent) orphanRows += 1;
  });
  const studentsWithMultipleRooms = [...countsByStudentId.entries()].filter(([, count]) => count > 1).length;
  return { studentsWithMultipleRooms, orphanRows };
};

const getAdminStudentLiveClassHostLabel = (liveUrl) => {
  const raw = String(liveUrl || "").trim();
  if (!raw) return "";
  try {
    const parsed = new URL(raw, typeof window !== "undefined" && window.location ? window.location.origin : "https://plataforma.spaceschoolbr.com");
    return parsed.host || raw;
  } catch (error) {
    return raw;
  }
};

const getAdminPedStudentActiveClass = (studentId) => {
  const safe = String(studentId || "").trim();
  if (!safe) return null;
  const rows = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  const matching = rows.filter((row) => {
    const ids = Array.isArray(row.studentIds) ? row.studentIds : [];
    return ids.map((id) => String(id || "").trim()).includes(safe);
  });
  matching.sort((a, b) => (Number(b.updatedAtMs || 0) || Number(b.createdAtMs || 0)) - (Number(a.updatedAtMs || 0) || Number(a.createdAtMs || 0)));
  return matching[0] || null;
};

const normalizeClassRow = ({ id, data }) => {
  const docId = String(id || "").trim();
  const src = data && typeof data === "object" ? data : {};
  if (!docId) return null;

  const type = normalizeClassType(src.type);
  const status = src.deletedAt || src.deleted_at || src.cancelledAt || src.canceladoEm ? "ended" : normalizeClassStatus(src.status || src.statusAula);
  const title = String(src.title || "").trim();
  const teacherId = String(src.teacherId || src.professorId || "").trim();
  const teacherName = String(src.teacherName || src.professorNome || src.professorName || "").trim();
  const groupId = String(src.groupId || "").trim();
  const groupName = String(src.groupName || "").trim();
  const planId = String(src.planId || "").trim();
  const planName = String(src.planName || "").trim();
  const plan = normalizePlanKeyLoose(src.plan || src.plano || planName || "");
  const scheduleDays = normalizeAdminPedWeeklyScheduleDays(src.scheduleDays || src.repeatDays || src.weeklySchedule || src.schedule || []);
  const daysOfWeek = normalizeDaysOfWeek(
    scheduleDays.some((day) => day && day.enabled)
      ? scheduleDays.filter((day) => day && day.enabled).map((day) => day.weekday)
      : src.daysOfWeek || src.weekDays || src.diasSemana || []
  );
  const firstActiveDay = scheduleDays.find((day) => day && day.enabled && /^\d{2}:\d{2}$/.test(String(day.startTime || "")) && /^\d{2}:\d{2}$/.test(String(day.endTime || ""))) || null;
  const startMin = firstActiveDay ? normalizeMinutesValue(firstActiveDay.startTime) : normalizeMinutesValue(src.startMin ?? src.startTime ?? src.horaInicio);
  const endMin = firstActiveDay ? normalizeMinutesValue(firstActiveDay.endTime) : normalizeMinutesValue(src.endMin ?? src.endTime ?? src.horaFim);
  const startDate = String(src.startDate || src.startDateKey || src.dateKey || "").trim();
  const endDate = String(src.endDate || src.endDateKey || "").trim();

  const studentIdsRaw = Array.isArray(src.studentIds) ? src.studentIds : Array.isArray(src.alunoIds) ? src.alunoIds : [];
  const studentIds = studentIdsRaw.map((v) => String(v || "").trim()).filter(Boolean);
  const studentNamesRaw = Array.isArray(src.studentNames) ? src.studentNames : Array.isArray(src.alunoNomes) ? src.alunoNomes : [];
  const studentNames = studentNamesRaw.map((v) => String(v || "").trim()).filter(Boolean);
  const linkedEventIds = Array.isArray(src.linkedEventIds) ? src.linkedEventIds.map((v) => String(v || "").trim()).filter(Boolean) : [];
  const linkedEventGroupId = String(src.linkedEventGroupId || src.grupoRecorrenciaId || "").trim();
  const roomSlug = String(src.roomSlug || src.roomId || "").trim();

  const createdAtMs = parseFirestoreDateToMs(src.createdAt || src.criadoEm);
  const updatedAtMs = parseFirestoreDateToMs(src.updatedAt || src.atualizadoEm);

  return {
    id: docId,
    type,
    status,
    title,
    teacherId,
    teacherName,
    groupId,
    groupName,
    planId,
    planName,
    plan,
    daysOfWeek,
    scheduleDays,
    startMin,
    endMin,
    startDate: isValidDateKey(startDate) ? startDate : "",
    endDate: isValidDateKey(endDate) ? endDate : "",
    studentIds,
    studentNames,
    linkedEventIds,
    linkedEventGroupId,
    roomSlug,
    notes: String(src.notes || src.observacoes || "").trim(),
    createdAtMs,
    updatedAtMs,
    createdBy: String(src.createdBy || "").trim(),
    updatedBy: String(src.updatedBy || "").trim(),
  };
};

const fetchClassesFromFirestore = async () => {
  let sourceRows = null;
  if (currentRole === "admin") {
    const response = await fetchWithAuth("/api/admin-data?collection=classes");
    if (response.ok) {
      const payload = await response.json().catch(() => null);
      sourceRows = Array.isArray(payload?.rows) ? payload.rows : [];
    }
  }

  if (!sourceRows) {
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_pedagogico");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) {
      const e = new Error("firebase_not_authenticated");
      e.code = "auth/no-current-user";
      throw e;
    }
    const col = firebase.collection(firebase.primaryDb, "classes");
    const snap = await withTimeout(firebase.getDocs(col), 12_000, "firestore_admin_classes_list");
    sourceRows = [];
    snap.forEach((docSnap) => sourceRows.push({ id: docSnap.id, ...(docSnap.data ? docSnap.data() : {}) }));
  }

  const rows = [];
  sourceRows.forEach((data) => {
    const row = normalizeClassRow({ id: data.id, data });
    if (row) rows.push(row);
  });
  rows.sort((a, b) => {
    const ta = String(a.teacherName || "").localeCompare(String(b.teacherName || ""), "pt-BR");
    if (ta) return ta;
    const sa = (a.startMin || 0) - (b.startMin || 0);
    if (sa) return sa;
    return String(a.id).localeCompare(String(b.id));
  });
  return rows;
};

