const fetchLiveLessonFeedbacks = async () => {
  try {
    const res = await fetchWithAuth("/api/live-lessons/feedbacks?limit=500");
    const data = await res.json().catch(() => null);
    if (!res.ok) throw new Error(data?.error || "live_lesson_feedbacks_failed");
    return {
      summary: data?.summary && typeof data.summary === "object" ? data.summary : {},
      feedbacks: Array.isArray(data?.feedbacks) ? data.feedbacks : [],
    };
  } catch (error) {
    console.error("[live-lessons] feedbacks load failed:", error);
    return { summary: {}, feedbacks: [] };
  }
};

const daysLabelShort = (dow) => {
  const n = Number(dow);
  if (n === 1) return "Seg";
  if (n === 2) return "Ter";
  if (n === 3) return "Qua";
  if (n === 4) return "Qui";
  if (n === 5) return "Sex";
  if (n === 6) return "Sáb";
  if (n === 0) return "Dom";
  return "—";
};

const daysLabelLong = (dow) => {
  const n = Number(dow);
  if (n === 1) return "Segunda";
  if (n === 2) return "Terça";
  if (n === 3) return "Quarta";
  if (n === 4) return "Quinta";
  if (n === 5) return "Sexta";
  if (n === 6) return "Sábado";
  if (n === 0) return "Domingo";
  return "—";
};

const adminPedPaginate = (rows, page, pageSize) => {
  const total = Array.isArray(rows) ? rows.length : 0;
  const safePageSize = Math.max(1, Number(pageSize) || 1);
  const totalPages = Math.max(1, Math.ceil(total / safePageSize));
  const safePage = Math.min(Math.max(1, Number(page) || 1), totalPages);
  const start = (safePage - 1) * safePageSize;
  const pageRows = (Array.isArray(rows) ? rows : []).slice(start, start + safePageSize);
  return { pageRows, total, totalPages, safePage };
};

const adminPedMatchesQuery = (row, query) => {
  const needle = String(query || "").trim().toLowerCase();
  if (!needle) return true;
  const haystack = [
    row?.nome,
    row?.email,
    row?.teacherName,
    row?.groupName,
    row?.plan,
    row?.statusLabel,
    row?.risk,
    row?.source,
  ]
    .map((value) => String(value || "").toLowerCase())
    .join(" ");
  return haystack.includes(needle);
};

