let adminPedLessonRecordsFiltersPopoverEl = null;

const ADMIN_PED_LESSON_RECORD_PERIOD_PRESETS = [
  { key: "today", label: "Hoje" },
  { key: "yesterday", label: "Ontem" },
  { key: "this_week", label: "Esta semana" },
  { key: "last_week", label: "Semana passada" },
  { key: "this_month", label: "Este mês" },
  { key: "last_month", label: "Mês passado" },
  { key: "custom", label: "Personalizado" },
];

const getAdminPedLessonRecordFilters = () => {
  const current = adminPedagogicoState.lessonRecords && typeof adminPedagogicoState.lessonRecords === "object" ? adminPedagogicoState.lessonRecords : {};
  return { ...ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS, ...current };
};

const countActiveAdminPedLessonRecordFilters = (filters) => {
  const current = filters && typeof filters === "object" ? filters : {};
  let count = 0;
  if (String(current.periodPreset || ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.periodPreset) !== ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.periodPreset) count += 1;
  if (String(current.status || ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.status) !== ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.status) count += 1;
  if (String(current.teacherQuery || "").trim()) count += 1;
  if (String(current.studentQuery || "").trim()) count += 1;
  return count;
};

const setAdminPedLessonRecordFilters = (patch = {}) => {
  const current = getAdminPedLessonRecordFilters();
  adminPedagogicoState.lessonRecords = { ...current, ...patch };
};

const closeAdminPedLessonRecordsFiltersPopover = () => {
  if (adminPedLessonRecordsFiltersPopoverEl instanceof HTMLElement) adminPedLessonRecordsFiltersPopoverEl.remove();
  adminPedLessonRecordsFiltersPopoverEl = null;
};

const syncAdminPedLessonRecordsFiltersPopoverUi = (pop) => {
  if (!(pop instanceof HTMLElement)) return;
  const periodEl = pop.querySelector('[data-admin-ped-lesson-record-pop-filter="periodPreset"]');
  const customWrap = pop.querySelector("[data-admin-ped-lesson-record-pop-custom]");
  if (!(periodEl instanceof HTMLSelectElement) || !(customWrap instanceof HTMLElement)) return;
  customWrap.hidden = String(periodEl.value || "") !== "custom";
};

const openAdminPedLessonRecordsFiltersPopover = ({ triggerEl } = {}) => {
  if (!(triggerEl instanceof HTMLElement)) return;
  closeAdminPedLessonRecordsFiltersPopover();

  const current = getAdminPedLessonRecordFilters();
  const pop = document.createElement("div");
  pop.className = "admin-ped-students-filters-popover pedrecords-filters-popover";
  pop.setAttribute("data-admin-ped-lesson-records-filters-popover", "true");
  pop.innerHTML = `
    <div class="admin-ped-students-filters-row">
      <label>Período</label>
      <select data-admin-ped-lesson-record-pop-filter="periodPreset">
        ${ADMIN_PED_LESSON_RECORD_PERIOD_PRESETS.map(
          (preset) => `<option value="${escapeHtml(preset.key)}">${escapeHtml(preset.label)}</option>`
        ).join("")}
      </select>
    </div>
    <div class="admin-ped-students-filters-row" data-admin-ped-lesson-record-pop-custom hidden>
      <label>Intervalo personalizado</label>
      <div class="admin-students-filters-grid2">
        <input type="date" data-admin-ped-lesson-record-pop-filter="customFrom" />
        <input type="date" data-admin-ped-lesson-record-pop-filter="customTo" />
      </div>
    </div>
    <div class="admin-ped-students-filters-row">
      <label>Status do registro</label>
      <select data-admin-ped-lesson-record-pop-filter="status">
        <option value="all">Todos</option>
        <option value="presenca">Presença</option>
        <option value="falta">Falta</option>
        <option value="sem_registro">Sem registro</option>
      </select>
    </div>
    <div class="admin-ped-students-filters-row">
      <label>Professor</label>
      <input type="search" placeholder="Buscar professor..." data-admin-ped-lesson-record-pop-filter="teacherQuery" />
    </div>
    <div class="admin-ped-students-filters-row">
      <label>Aluno</label>
      <input type="search" placeholder="Buscar aluno..." data-admin-ped-lesson-record-pop-filter="studentQuery" />
    </div>
    <div class="admin-ped-students-filters-actions">
      <button type="button" class="admin-ped-students-filters-clear" data-admin-ped-lesson-record-filters-clear>Limpar filtros</button>
      <button type="button" class="admin-ped-students-filters-apply" data-admin-ped-lesson-record-filters-apply>Aplicar</button>
    </div>
  `;

  document.body.appendChild(pop);
  adminPedLessonRecordsFiltersPopoverEl = pop;

  pop.querySelectorAll("[data-admin-ped-lesson-record-pop-filter]").forEach((el) => {
    const key = String(el.getAttribute("data-admin-ped-lesson-record-pop-filter") || "").trim();
    if (!key) return;
    if (el instanceof HTMLSelectElement || el instanceof HTMLInputElement) {
      el.value = String(current?.[key] || "");
    }
  });
  syncAdminPedLessonRecordsFiltersPopoverUi(pop);

  const rect = triggerEl.getBoundingClientRect();
  const popRect = pop.getBoundingClientRect();
  const margin = 10;
  const spaceBelow = window.innerHeight - rect.bottom;
  const shouldFlipUp = spaceBelow < popRect.height + margin;
  const top = shouldFlipUp ? rect.top - margin - popRect.height : rect.bottom + margin;
  const left = Math.min(Math.max(rect.right - popRect.width, margin), Math.max(margin, window.innerWidth - popRect.width - margin));
  pop.style.top = `${clampToViewport(top, margin, window.innerHeight - popRect.height - margin)}px`;
  pop.style.left = `${left}px`;
};

const fetchAdminPedScheduleEvents = async () => {
  const response = await fetchWithAuth("/api/schedule-events", { method: "GET" });
  const payload = await response.json().catch(() => null);
  if (!response.ok) throw new Error(payload?.error || "schedule_events_failed");
  return Array.isArray(payload?.events) ? payload.events : [];
};

const getAdminPedLessonRecordPeriodRange = (preset, customFrom, customTo, referenceDate = new Date()) => {
  const today = startOfDay(referenceDate);
  const monthStart = new Date(today.getFullYear(), today.getMonth(), 1);
  const monthEnd = new Date(today.getFullYear(), today.getMonth() + 1, 0);
  const weekOffset = (today.getDay() + 6) % 7;
  const weekStart = addDays(today, -weekOffset);
  const weekEnd = addDays(weekStart, 6);
  const lastWeekStart = addDays(weekStart, -7);
  const lastWeekEnd = addDays(weekEnd, -7);
  const lastMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
  const lastMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0);

  const presetKey = String(preset || "this_month").trim();
  if (presetKey === "today") return { fromKey: createDateKey(today), toKey: createDateKey(today), label: "Hoje" };
  if (presetKey === "yesterday") {
    const yesterday = addDays(today, -1);
    return { fromKey: createDateKey(yesterday), toKey: createDateKey(yesterday), label: "Ontem" };
  }
  if (presetKey === "this_week") return { fromKey: createDateKey(weekStart), toKey: createDateKey(weekEnd), label: "Esta semana" };
  if (presetKey === "last_week") return { fromKey: createDateKey(lastWeekStart), toKey: createDateKey(lastWeekEnd), label: "Semana passada" };
  if (presetKey === "last_month") return { fromKey: createDateKey(lastMonthStart), toKey: createDateKey(lastMonthEnd), label: "Mês passado" };
  if (presetKey === "custom") {
    const fromKey = isValidDateKey(customFrom) ? customFrom : createDateKey(monthStart);
    const toKey = isValidDateKey(customTo) ? customTo : fromKey;
    const orderedFrom = fromKey <= toKey ? fromKey : toKey;
    const orderedTo = fromKey <= toKey ? toKey : fromKey;
    return { fromKey: orderedFrom, toKey: orderedTo, label: "Personalizado" };
  }
  return { fromKey: createDateKey(monthStart), toKey: createDateKey(monthEnd), label: "Este mês" };
};

const getAdminPedLessonRecordFilterMatch = (query, teacherOrStudent) => {
  const needle = normalizeSearchText(query);
  if (!needle) return true;
  const haystack = [
    teacherOrStudent?.nome,
    teacherOrStudent?.email,
    teacherOrStudent?.telefone,
    teacherOrStudent?.plan,
    teacherOrStudent?.teacherName,
  ]
    .map((value) => normalizeSearchText(value))
    .join(" ");
  return haystack.includes(needle);
};

const buildAdminPedLessonLogsByEventId = (logs) => {
  const byEventId = new Map();
  (Array.isArray(logs) ? logs : []).forEach((log) => {
    const eventId = String(log?.eventId || "").trim();
    if (!eventId) return;
    const nextMs = Date.parse(String(log?.atualizadoEm || log?.criadoEm || "")) || 0;
    const prev = byEventId.get(eventId);
    const prevMs = prev ? Date.parse(String(prev?.atualizadoEm || prev?.criadoEm || "")) || 0 : 0;
    if (prev && prevMs > nextMs) return;
    byEventId.set(eventId, log);
  });
  return byEventId;
};

const buildAdminPedLessonRecordSparkline = (values, color) => {
  const points = Array.isArray(values) ? values.map((value) => Math.max(0, Number(value) || 0)) : [];
  if (!points.length) return "";
  const max = Math.max(...points, 1);
  const width = 180;
  const height = 34;
  const step = points.length <= 1 ? width : width / (points.length - 1);
  const line = points
    .map((value, index) => {
      const x = Number((index * step).toFixed(2));
      const y = Number((height - (value / max) * (height - 4) - 2).toFixed(2));
      return `${x},${y}`;
    })
    .join(" ");
  return `<svg viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" aria-hidden="true"><polyline fill="none" stroke="${escapeHtml(
    color || "#a0bcff"
  )}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" points="${escapeHtml(line)}"></polyline></svg>`;
};

const buildAdminPedLessonRecordRowsFromClasses = ({ classes, fromKey, toKey, studentsById, teachersById }) => {
  const rows = [];
  (Array.isArray(classes) ? classes : []).forEach((classRow) => {
    if (!classRow || typeof classRow !== "object") return;
    const teacherId = String(classRow.teacherId || "").trim();
    const teacherName = String(classRow.teacherName || teachersById.get(teacherId)?.nome || "Professor").trim();
    const studentIds = Array.isArray(classRow.studentIds) ? classRow.studentIds.map((id) => String(id || "").trim()).filter(Boolean) : [];
    const studentNames = studentIds.map((id, index) => String(studentsById.get(id)?.nome || classRow.studentNames?.[index] || "Aluno").trim());
    const scheduleDays = normalizeAdminPedWeeklyScheduleDays(classRow.scheduleDays || []);
    const activeDays = scheduleDays.filter((day) => day && day.enabled && /^\d{2}:\d{2}$/.test(String(day.startTime || "")) && /^\d{2}:\d{2}$/.test(String(day.endTime || "")));
    if (!activeDays.length) return;
    const rangeStart = parseDateKey(fromKey);
    const rangeEnd = parseDateKey(toKey);
    if (!(rangeStart instanceof Date) || !(rangeEnd instanceof Date)) return;
    const classStart = isValidDateKey(classRow.startDate) ? parseDateKey(classRow.startDate) : rangeStart;
    const classEnd = isValidDateKey(classRow.endDate) ? parseDateKey(classRow.endDate) : rangeEnd;
    const startDate = classStart && classStart > rangeStart ? classStart : rangeStart;
    const endDate = classEnd && classEnd < rangeEnd ? classEnd : rangeEnd;
    if (!(startDate instanceof Date) || !(endDate instanceof Date) || startDate > endDate) return;
    for (let cursor = new Date(startDate); cursor <= endDate; cursor = addDays(cursor, 1)) {
      const weekday = cursor.getDay();
      const schedule = activeDays.find((day) => Number(day.weekday) === weekday);
      if (!schedule) continue;
      const startMin = normalizeMinutesValue(schedule.startTime);
      const endMin = normalizeMinutesValue(schedule.endTime);
      if (!Number.isFinite(startMin) || !Number.isFinite(endMin) || endMin <= startMin) continue;
      const dateKey = createDateKey(cursor);
      rows.push({
        id: `${String(classRow.id || "class")}::${dateKey}::${startMin}`,
        alunoId: studentIds[0] || "",
        alunoNome: studentNames.filter(Boolean).join(", ") || "Aluno",
        professorId: teacherId,
        professorNome: teacherName || "Professor",
        dateKey,
        startMin,
        endMin,
        title: String(classRow.title || "").trim(),
        source: "classes",
      });
    }
  });
  return rows;
};

const buildAdminPedLessonRecordSeries = (rows, fromKey, toKey) => {
  const fromDate = parseDateKey(fromKey);
  const toDate = parseDateKey(toKey);
  if (!(fromDate instanceof Date) || !(toDate instanceof Date)) return [];
  const daySpan = Math.max(1, Math.round((startOfDay(toDate).getTime() - startOfDay(fromDate).getTime()) / 86400000) + 1);
  if (daySpan <= 7) {
    const keys = [];
    for (let cursor = new Date(fromDate); cursor <= toDate; cursor = addDays(cursor, 1)) keys.push(createDateKey(cursor));
    return keys.map((dateKey) => {
      const subset = rows.filter((row) => row.dateKey === dateKey);
      return {
        label: dateKey,
        total: subset.length,
        presenca: subset.filter((row) => row.statusKey === "presenca").length,
        falta: subset.filter((row) => row.statusKey === "falta").length,
        semRegistro: subset.filter((row) => row.statusKey === "sem_registro").length,
      };
    });
  }
  const bucketByKey = new Map();
  rows.forEach((row) => {
    const date = parseDateKey(row.dateKey);
    if (!(date instanceof Date)) return;
    const bucketDate = daySpan <= 31 ? addDays(startOfDay(date), -((date.getDay() + 6) % 7)) : new Date(date.getFullYear(), date.getMonth(), 1);
    const bucketKey = createDateKey(bucketDate);
    const prev = bucketByKey.get(bucketKey) || { label: bucketKey, total: 0, presenca: 0, falta: 0, semRegistro: 0 };
    prev.total += 1;
    if (row.statusKey === "presenca") prev.presenca += 1;
    if (row.statusKey === "falta") prev.falta += 1;
    if (row.statusKey === "sem_registro") prev.semRegistro += 1;
    bucketByKey.set(bucketKey, prev);
  });
  return [...bucketByKey.values()].sort((a, b) => String(a.label || "").localeCompare(String(b.label || "")));
};

const buildAdminPedLessonRecordDataset = () => {
  const filters = getAdminPedLessonRecordFilters();
  const range = getAdminPedLessonRecordPeriodRange(filters.periodPreset, filters.customFrom, filters.customTo);
  const studentsById = adminPedagogicoState.studentsById instanceof Map ? adminPedagogicoState.studentsById : new Map();
  const teachersById = adminPedagogicoState.teachersById instanceof Map ? adminPedagogicoState.teachersById : new Map();
  const normalizedEvents = normalizePedov2ScheduleEvents(adminPedagogicoState.scheduleEvents || []);
  const fallbackClassRows =
    normalizedEvents.length > 0
      ? []
      : buildAdminPedLessonRecordRowsFromClasses({
          classes: adminPedagogicoState.classes,
          fromKey: range.fromKey,
          toKey: range.toKey,
          studentsById,
          teachersById,
        });
  const baseRows = (normalizedEvents.length ? normalizedEvents : fallbackClassRows)
    .filter((event) => String(event.dateKey || "").trim() >= range.fromKey && String(event.dateKey || "").trim() <= range.toKey)
    .map((event) => {
      const alunoId = String(event.alunoId || "").trim();
      const professorId = String(event.professorId || "").trim();
      const student = alunoId ? studentsById.get(alunoId) : null;
      const teacher = professorId ? teachersById.get(professorId) : null;
      return {
        id: String(event.id || "").trim(),
        alunoId,
        alunoNome: String(student?.nome || event.alunoNome || event.studentName || event.title || "Aluno").trim(),
        professorId,
        professorNome: String(teacher?.nome || event.professorNome || event.teacherName || "Professor").trim(),
        dateKey: String(event.dateKey || "").trim(),
        startMin: Number(event.startMin) || 0,
        endMin: Number(event.endMin) || 0,
        startMs: Number(event.startMs) || buildDateFromDateKeyAndMinutes(event.dateKey, event.startMin)?.getTime() || 0,
        endMs: Number(event.endMs) || buildDateFromDateKeyAndMinutes(event.dateKey, event.endMin)?.getTime() || 0,
        source: String(event.source || (normalizedEvents.length ? "schedule-events" : "classes")),
      };
    });

  const logsByEventId = buildAdminPedLessonLogsByEventId(adminPedagogicoState.lessonLogs || []);
  const nowMs = Date.now();
  const rows = baseRows.map((row) => {
    const log = logsByEventId.get(String(row.id || "")) || null;
    const normalizedStatus = log ? normalizePedagogicoStatus(log.statusAula) : "";
    let statusKey = "agendada";
    let statusLabel = "Agendada";
    let tone = "slate";
    if (normalizedStatus === PEDAGOGICO_STATUS.REALIZADA) {
      statusKey = "presenca";
      statusLabel = "Presença";
      tone = "green";
    } else if (normalizedStatus === PEDAGOGICO_STATUS.FALTA_ALUNO) {
      statusKey = "falta";
      statusLabel = "Falta";
      tone = "coral";
    } else if (normalizedStatus === PEDAGOGICO_STATUS.REMARCADA) {
      statusKey = "remarcada";
      statusLabel = "Remarcada";
      tone = "amber";
    } else if (normalizedStatus === PEDAGOGICO_STATUS.CANCELADA) {
      statusKey = "cancelada";
      statusLabel = "Cancelada";
      tone = "muted";
    } else if (row.endMs < nowMs) {
      statusKey = "sem_registro";
      statusLabel = "Sem registro";
      tone = "muted";
    }
    return { ...row, log, statusKey, statusLabel, tone };
  });

  const teacherQuery = String(filters.teacherQuery || "").trim();
  const studentQuery = String(filters.studentQuery || "").trim();
  const filteredRows = rows.filter((row) => {
    if (filters.status === "presenca" && row.statusKey !== "presenca") return false;
    if (filters.status === "falta" && row.statusKey !== "falta") return false;
    if (filters.status === "sem_registro" && row.statusKey !== "sem_registro") return false;
    if (teacherQuery && !getAdminPedLessonRecordFilterMatch(teacherQuery, { nome: row.professorNome, email: teachersById.get(row.professorId)?.email })) return false;
    if (studentQuery && !getAdminPedLessonRecordFilterMatch(studentQuery, { nome: row.alunoNome, email: studentsById.get(row.alunoId)?.email })) return false;
    return true;
  });

  const sortedRows = filteredRows.slice().sort((a, b) => {
    const priority = (row) => {
      if (row.statusKey === "sem_registro") return 0;
      if (row.statusKey === "falta") return 1;
      if (row.statusKey === "presenca") return 2;
      if (row.statusKey === "remarcada") return 3;
      return 4;
    };
    const pa = priority(a);
    const pb = priority(b);
    if (pa !== pb) return pa - pb;
    if (pa === 0) return (a.startMs || 0) - (b.startMs || 0);
    return (b.startMs || 0) - (a.startMs || 0);
  });

  const summarySource = buildAdminPedLessonRecordSeries(filteredRows, range.fromKey, range.toKey);
  const summary = {
    total: filteredRows.length,
    presenca: filteredRows.filter((row) => row.statusKey === "presenca").length,
    falta: filteredRows.filter((row) => row.statusKey === "falta").length,
    semRegistro: filteredRows.filter((row) => row.statusKey === "sem_registro").length,
    series: summarySource,
  };

  return { filters, range, rows: sortedRows, summary };
};

const getAdminPedLessonRecordDrawer = () =>
  getOrCreateAdminDrawer({
    selector: "[data-admin-ped-lesson-record-drawer]",
    template: ADMIN_PED_LESSON_RECORD_DRAWER_TEMPLATE,
  });

const getAdminPedLessonRecordStatusMeta = (status) => {
  const raw = String(status || "").trim();
  if (raw === "sem_registro") return { label: "Sem registro", tone: "muted" };
  if (raw === "presenca") return { label: "Realizada", tone: "green" };
  if (raw === "falta") return { label: "Falta", tone: "coral" };
  const normalized = normalizePedagogicoStatus(raw);
  if (normalized === PEDAGOGICO_STATUS.FALTA_ALUNO) return { label: "Falta", tone: "coral" };
  if (normalized === PEDAGOGICO_STATUS.REMARCADA) return { label: "Remarcada", tone: "amber" };
  if (normalized === PEDAGOGICO_STATUS.CANCELADA) return { label: "Cancelada", tone: "muted" };
  if (normalized === PEDAGOGICO_STATUS.REALIZADA) return { label: "Realizada", tone: "green" };
  return { label: "Sem registro", tone: "muted" };
};

const formatAdminPedLessonRecordOption = (options, value) => {
  const safe = String(value || "").trim();
  if (!safe) return "";
  const found = (Array.isArray(options) ? options : []).find((option) => String(option?.[0] || "") === safe);
  return found ? String(found[1] || safe) : safe.replace(/_/g, " ");
};

const renderAdminPedLessonRecordValue = (value) => {
  const text = Array.isArray(value)
    ? value.map((item) => String(item || "").trim()).filter(Boolean).join(", ")
    : String(value ?? "").trim();
  return escapeHtml(text || "Não informado");
};

const renderAdminPedLessonRecordField = (label, value) => `
  <div class="admin-ped-record-field">
    <dt>${escapeHtml(label)}</dt>
    <dd>${renderAdminPedLessonRecordValue(value)}</dd>
  </div>
`;

const renderAdminPedLessonRecordStars = (value) => {
  const rating = clampInt(Number(value || 0), 0, 5, 0);
  const stars = [1, 2, 3, 4, 5]
    .map((idx) => `<span class="${idx <= rating ? "is-on" : ""}" aria-hidden="true">★</span>`)
    .join("");
  return `<span class="admin-ped-record-stars" aria-label="${escapeHtml(rating > 0 ? `${rating} de 5` : "Não informado")}">${stars}<em>${escapeHtml(rating > 0 ? `${rating}/5` : "Não informado")}</em></span>`;
};

const renderAdminPedLessonRecordRatingField = (label, value) => `
  <div class="admin-ped-record-field">
    <dt>${escapeHtml(label)}</dt>
    <dd>${renderAdminPedLessonRecordStars(value)}</dd>
  </div>
`;

const renderAdminPedLessonRecordSection = (title, fieldsHtml) => `
  <section class="admin-ped-record-section">
    <h3>${escapeHtml(title)}</h3>
    <dl>${fieldsHtml}</dl>
  </section>
`;

const renderAdminPedLessonRecordDynamicSections = (record) => {
  const logPayload = record?.log?.payload && typeof record.log.payload === "object" ? record.log.payload : {};
  const draft = sanitizeLessonLogDraft(logPayload);
  const status = record?.log ? normalizePedagogicoStatus(draft.statusAula || record.log.statusAula) : "";
  const hasLogField = (...keys) => keys.some((key) => Object.prototype.hasOwnProperty.call(logPayload, key) && String(logPayload[key] ?? "").trim());
  const valueIfPresent = (value, ...keys) => (hasLogField(...keys) ? value : "");

  if (status === PEDAGOGICO_STATUS.FALTA_ALUNO) {
    return renderAdminPedLessonRecordSection(
      "Falta",
      [
        renderAdminPedLessonRecordField("Motivo da falta", formatAdminPedLessonRecordOption(PED_MOTIVO_FALTA, valueIfPresent(draft.motivoFalta, "motivoFalta"))),
        renderAdminPedLessonRecordField("Responsável", formatAdminPedLessonRecordOption(
          [
            ["aluno", "Aluno"],
            ["professor", "Professor"],
            ["escola", "Escola"],
            ["outro", "Outro"],
          ],
          valueIfPresent(draft.responsavelFalta, "responsavelFalta")
        )),
        renderAdminPedLessonRecordField(
          "Reposição necessária",
          valueIfPresent(draft.reposicaoNecessaria, "reposicaoNecessaria") === "nao" ? "Não" : valueIfPresent(draft.reposicaoNecessaria, "reposicaoNecessaria") === "sim" ? "Sim" : ""
        ),
        renderAdminPedLessonRecordField("Risco de evasão", formatAdminPedLessonRecordOption(PED_RISCO_EVASAO, valueIfPresent(draft.riscoEvasao, "riscoEvasao"))),
        renderAdminPedLessonRecordField("Observação", valueIfPresent(draft.observacao, "observacao", "observacoesInternas")),
      ].join("")
    );
  }

  if (status === PEDAGOGICO_STATUS.REMARCADA) {
    const novaData = draft.novaDataRemarcacao ? formatPedagogicoDate(draft.novaDataRemarcacao) : "";
    const novoHorario = draft.horarioInicioRemarcacao || draft.horarioFimRemarcacao ? `${draft.horarioInicioRemarcacao || "—"}–${draft.horarioFimRemarcacao || "—"}` : "";
    const situationLabel =
      draft.situacaoReposicao === "agendada_agora"
        ? "Já tenho novo horário"
        : draft.situacaoReposicao === "aguardando_aluno"
          ? "Aguardando resposta do aluno"
          : draft.situacaoReposicao === "incompatibilidade_horario"
            ? "Incompatibilidade de horário"
            : "";
    const eligibilityLabel = draft.elegibilidade?.motivo
      ? `${draft.elegibilidade.elegivel ? "Elegível" : "Não elegível"} — ${draft.elegibilidade.motivo}`
      : "";
    return renderAdminPedLessonRecordSection(
      "Remarcação",
      [
        renderAdminPedLessonRecordField("Responsável", formatResponsavelRemarcacao(draft.responsavelRemarcacao)),
        renderAdminPedLessonRecordField("Aviso recebido em", draft.dataAvisoRemarcacao ? new Date(draft.dataAvisoRemarcacao).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" }) : ""),
        renderAdminPedLessonRecordField("Elegibilidade", eligibilityLabel),
        renderAdminPedLessonRecordField("Situação", situationLabel),
        renderAdminPedLessonRecordField("Motivo", formatAdminPedLessonRecordOption(PED_MOTIVO_REMARCACAO, valueIfPresent(draft.motivoRemarcacao, "motivoRemarcacao"))),
        renderAdminPedLessonRecordField("Nova data", novaData),
        renderAdminPedLessonRecordField("Novo horário", novoHorario),
        renderAdminPedLessonRecordField("Risco de evasão", formatAdminPedLessonRecordOption(PED_RISCO_EVASAO, valueIfPresent(draft.riscoEvasao, "riscoEvasao"))),
        renderAdminPedLessonRecordField("Observação", valueIfPresent(draft.observacao, "observacao", "observacoesInternas")),
      ].join("")
    );
  }

  if (status === PEDAGOGICO_STATUS.CANCELADA) {
    return renderAdminPedLessonRecordSection("Cancelamento", renderAdminPedLessonRecordField("Motivo / observação", draft.observacao || draft.observacoesInternas));
  }

  if (status === PEDAGOGICO_STATUS.REALIZADA) {
    return [
      renderAdminPedLessonRecordSection(
        "Conteúdo da aula",
        [
          renderAdminPedLessonRecordField("O que foi trabalhado", draft.conteudoTrabalhado),
          renderAdminPedLessonRecordField("Gramática", draft.gramaticaTrabalhada),
          renderAdminPedLessonRecordField("Vocabulário", draft.vocabularioTrabalhado),
          renderAdminPedLessonRecordField("Pronúncia", draft.pronunciaConversacao),
          renderAdminPedLessonRecordField("Atividade", draft.atividadeRealizada),
          renderAdminPedLessonRecordField("Materiais", draft.materiaisUsados),
          renderAdminPedLessonRecordField("Homework", draft.homework),
          renderAdminPedLessonRecordField("Próxima aula", draft.proximaAula),
          renderAdminPedLessonRecordField("Avisos", draft.avisosCoordenacao),
          renderAdminPedLessonRecordField("Observações internas", draft.observacoesInternas),
        ].join("")
      ),
      renderAdminPedLessonRecordSection(
        "Avaliação do aluno",
        [
          renderAdminPedLessonRecordRatingField("Engajamento", draft.engajamentoNota),
          renderAdminPedLessonRecordRatingField("Evolução", draft.evolucaoNota),
          renderAdminPedLessonRecordRatingField("Confiança", draft.confiancaNota),
          renderAdminPedLessonRecordField("Humor", draft.humorAluno),
        ].join("")
      ),
    ].join("");
  }

  return renderAdminPedLessonRecordSection(
    "Registro",
    [
      renderAdminPedLessonRecordField("Status", "Sem registro salvo"),
      renderAdminPedLessonRecordField("Conteúdo", ""),
      renderAdminPedLessonRecordField("Observação", ""),
    ].join("")
  );
};

const renderAdminPedLessonRecordDetail = (record) => {
  const statusMeta = getAdminPedLessonRecordStatusMeta(record?.log?.statusAula || record?.statusKey);
  const titleEl = getAdminPedLessonRecordDrawer()?.querySelector("[data-admin-ped-lesson-record-title]");
  const subEl = getAdminPedLessonRecordDrawer()?.querySelector("[data-admin-ped-lesson-record-sub]");
  const bodyEl = getAdminPedLessonRecordDrawer()?.querySelector("[data-admin-ped-lesson-record-body]");
  if (titleEl instanceof HTMLElement) titleEl.textContent = record?.alunoNome || "Aluno";
  if (subEl instanceof HTMLElement) {
    subEl.textContent = `${record?.professorNome || "Professor"} · ${formatPedagogicoDate(record?.dateKey)} · ${formatHmFromMinutes(record?.startMin)}–${formatHmFromMinutes(record?.endMin)}`;
  }
  if (!(bodyEl instanceof HTMLElement)) return;
  bodyEl.innerHTML = `
    <section class="admin-ped-record-hero">
      <div>
        <span class="admin-ped-record-kicker">Registro de aula</span>
        <h2>${escapeHtml(record?.alunoNome || "Aluno")}</h2>
        <p>${escapeHtml(record?.professorNome || "Professor")} · ${escapeHtml(formatPedagogicoDate(record?.dateKey))} · ${escapeHtml(
          `${formatHmFromMinutes(record?.startMin)}–${formatHmFromMinutes(record?.endMin)}`
        )}</p>
      </div>
      <span class="pedrecords-status-badge is-${escapeHtml(statusMeta.tone)}">${escapeHtml(statusMeta.label)}</span>
    </section>
    ${renderAdminPedLessonRecordDynamicSections(record)}
  `;
};

const openAdminPedLessonRecordDrawer = (record) => {
  if (!record || typeof record !== "object") return;
  const drawer = getAdminPedLessonRecordDrawer();
  if (!(drawer instanceof HTMLElement)) return;
  renderAdminPedLessonRecordDetail(record);
  lockAdminStudentDrawerBackgroundScroll();
  drawer.hidden = false;
  window.requestAnimationFrame(() => {
    drawer.classList.add("is-open");
  });
};

const closeAdminPedLessonRecordDrawer = () => {
  const drawer = getAdminPedLessonRecordDrawer();
  if (drawer instanceof HTMLElement) {
    drawer.classList.remove("is-open");
    window.setTimeout(() => {
      const nextDrawer = getAdminPedLessonRecordDrawer();
      if (nextDrawer instanceof HTMLElement) nextDrawer.hidden = true;
    }, 220);
  }
  unlockAdminStudentDrawerBackgroundScroll();
};

const renderAdminPedLessonRecordActiveFilters = ({ filters, range }) => {
  const chips = [];
  if (String(filters.periodPreset || ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.periodPreset) !== ADMIN_PED_LESSON_RECORD_FILTER_DEFAULTS.periodPreset) {
    const periodLabel =
      String(filters.periodPreset || "") === "custom"
        ? `${range.fromKey} → ${range.toKey}`
        : ADMIN_PED_LESSON_RECORD_PERIOD_PRESETS.find((preset) => preset.key === String(filters.periodPreset || ""))?.label || "Período";
    chips.push({ key: "periodPreset", label: periodLabel });
  }
  if (String(filters.status || "all") !== "all") {
    const labels = { presenca: "Presença", falta: "Falta", sem_registro: "Sem registro" };
    chips.push({ key: "status", label: labels[String(filters.status)] || "Status" });
  }
  if (String(filters.teacherQuery || "").trim()) chips.push({ key: "teacherQuery", label: `Prof. ${String(filters.teacherQuery).trim()}` });
  if (String(filters.studentQuery || "").trim()) chips.push({ key: "studentQuery", label: `${String(filters.studentQuery).trim()}` });
  if (!chips.length) return "";
  return `
    <div class="pedrecords-active-filters">
      ${chips
        .map(
          (chip) => `<button class="pedrecords-filter-chip" type="button" data-admin-ped-lesson-record-filter-remove="${escapeHtml(String(chip.key || ""))}">${escapeHtml(
            chip.label
          )} <span aria-hidden="true">×</span></button>`
        )
        .join("")}
      ${chips.length > 1 ? `<button class="pedrecords-clear-filters" type="button" data-admin-ped-lesson-record-clear-filters>Limpar filtros</button>` : ""}
    </div>
  `;
};

const syncAdminPedRetentionBadge = (count = 0) => {
  const safe = Math.max(0, Number(count) || 0);
  document.querySelectorAll("[data-admin-ped-retention-badge]").forEach((badge) => {
    if (!(badge instanceof HTMLElement)) return;
    badge.hidden = safe <= 0;
    badge.textContent = String(safe);
  });
};

const syncAdminPedReposicoesBadge = (count = 0) => {
  const safe = Math.max(0, Number(count) || 0);
  document.querySelectorAll("[data-admin-ped-reposicoes-badge]").forEach((badge) => {
    if (!(badge instanceof HTMLElement)) return;
    badge.hidden = safe <= 0;
    badge.textContent = String(safe);
  });
};

const getReposicaoDateLimitKey = (payload = {}) => {
  const eligibility = payload?.elegibilidade && typeof payload.elegibilidade === "object" ? payload.elegibilidade : {};
  return String(eligibility.dataLimiteReposicao || payload.dataLimiteReposicao || "").trim();
};

const getReposicaoDaysRemaining = (dateLimitKey, referenceDate = new Date()) => {
  const limit = parseDateKey(dateLimitKey);
  if (!limit) return null;
  const today = parseDateKey(createDateKey(referenceDate));
  if (!today) return null;
  return Math.ceil((limit.getTime() - today.getTime()) / 86400000);
};

const formatReposicaoDaysRemaining = (days) => {
  if (!Number.isFinite(Number(days))) return "Sem prazo";
  const n = Number(days);
  if (n < 0) return `${Math.abs(n)}d em atraso`;
  if (n === 0) return "Vence hoje";
  if (n === 1) return "1 dia restante";
  return `${n} dias restantes`;
};

const getReposicaoStudentIdFromLog = (log = {}, event = null) =>
  String(log?.alunoId || log?.studentId || log?.payload?.alunoId || event?.alunoId || "").trim();

const getReposicaoTeacherIdFromLog = (log = {}, event = null) =>
  String(log?.professorId || log?.teacherId || log?.payload?.professorId || event?.professorId || "").trim();

const buildReposicaoQueues = (dadosPreCarregados = {}) => {
  const {
    lessonLogs = [],
    scheduleEvents = [],
    students = [],
    teachers = [],
    teachersById = new Map(),
    referenceDate = new Date(),
  } = dadosPreCarregados || {};
  const eventsById = new Map();
  (Array.isArray(scheduleEvents) ? scheduleEvents : []).forEach((event) => {
    const id = String(event?.id || "").trim();
    if (id) eventsById.set(id, event);
  });
  const studentsById = new Map();
  (Array.isArray(students) ? students : []).forEach((student) => {
    const ids = [student?.id, student?.alunoId, student?.firestoreDocId, student?.docId].map((id) => String(id || "").trim()).filter(Boolean);
    ids.forEach((id) => studentsById.set(id, student));
  });
  const localTeachersById = teachersById instanceof Map ? new Map(teachersById) : new Map();
  (Array.isArray(teachers) ? teachers : []).forEach((teacher) => {
    const id = String(teacher?.id || teacher?.uid || teacher?.firestoreDocId || "").trim();
    if (id && !localTeachersById.has(id)) localTeachersById.set(id, teacher);
  });

  const baseRows = [];
  (Array.isArray(lessonLogs) ? lessonLogs : []).forEach((log) => {
    const payload = log?.payload && typeof log.payload === "object" ? log.payload : {};
    const status = normalizePedagogicoStatus(log?.statusAula || payload.statusAula);
    if (status !== PEDAGOGICO_STATUS.REMARCADA) return;
    const situation = normalizeSituacaoReposicao(payload.situacaoReposicao || payload.situacao_reposicao || "");
    if (!situation) return;
    const resolved = payload.reposicaoResolvida === true || payload.reposicaoStatus === "resolvido" || payload.reposicao_resolvida === true;
    if (resolved) return;
    const eventId = String(log?.eventId || payload.eventId || "").trim();
    const event = eventsById.get(eventId) || null;
    const alunoId = getReposicaoStudentIdFromLog(log, event);
    const professorId = getReposicaoTeacherIdFromLog(log, event);
    const student = studentsById.get(alunoId) || null;
    const teacher = localTeachersById.get(professorId) || null;
    const dateLimitKey = getReposicaoDateLimitKey(payload);
    const daysRemaining = getReposicaoDaysRemaining(dateLimitKey, referenceDate);
    const expired = Number.isFinite(Number(daysRemaining)) && Number(daysRemaining) < 0;
    const urgent = Number.isFinite(Number(daysRemaining)) && Number(daysRemaining) <= 3;
    const decisionUrgent = Number.isFinite(Number(daysRemaining)) && Number(daysRemaining) <= 2;
    baseRows.push({
      id: String(log?.id || log?.documentId || log?.docId || eventId || "").trim(),
      eventId,
      alunoId,
      alunoNome: getRetentionStudentDisplayName(student) || String(event?.alunoNome || event?.title || "Aluno"),
      professorId,
      professorNome: String(teacher?.nome || teacher?.name || event?.professorNome || event?.teacherName || "Professor").trim(),
      dateKey: String(log?.dateKey || payload.dateKey || event?.dateKey || "").trim(),
      startMin: Number(log?.startMin ?? payload.startMin ?? event?.startMin ?? 0) || 0,
      endMin: Number(log?.endMin ?? payload.endMin ?? event?.endMin ?? 0) || 0,
      motivo: String(payload.motivoRemarcacao || "").trim(),
      observacao: String(payload.observacao || payload.observacoesInternas || "").trim(),
      situacaoReposicao: situation,
      needsAdminReview: payload.needsAdminReview === true || payload.needs_admin_review === true || situation === "incompatibilidade_horario",
      elegibilidade: payload.elegibilidade && typeof payload.elegibilidade === "object" ? payload.elegibilidade : {},
      dateLimitKey,
      daysRemaining,
      daysLabel: formatReposicaoDaysRemaining(daysRemaining),
      expired,
      urgent,
      decisionUrgent,
      novaDataRemarcacao: String(payload.novaDataRemarcacao || payload.novaData || "").trim(),
      horarioInicioRemarcacao: String(payload.horarioInicioRemarcacao || payload.novoInicio || "").trim(),
      horarioFimRemarcacao: String(payload.horarioFimRemarcacao || payload.novoFim || "").trim(),
    });
  });

  const aguardando = baseRows
    .filter((row) => row.situacaoReposicao === "aguardando_aluno" && !row.expired)
    .sort((a, b) => Number(a.daysRemaining ?? 999) - Number(b.daysRemaining ?? 999));
  const decisoes = baseRows
    .filter((row) => row.needsAdminReview || (row.situacaoReposicao === "aguardando_aluno" && row.decisionUrgent))
    .sort((a, b) => Number(a.daysRemaining ?? 999) - Number(b.daysRemaining ?? 999));
  const agendadas = baseRows
    .filter((row) => row.situacaoReposicao === "agendada_agora")
    .sort((a, b) => String(a.novaDataRemarcacao || "").localeCompare(String(b.novaDataRemarcacao || "")) || a.horarioInicioRemarcacao.localeCompare(b.horarioInicioRemarcacao));
  const expiradas = baseRows
    .filter((row) => row.situacaoReposicao !== "agendada_agora" && row.expired)
    .sort((a, b) => Number(a.daysRemaining ?? 999) - Number(b.daysRemaining ?? 999));
  return { aguardando, decisoes, agendadas, expiradas, all: baseRows };
};

const formatRetentionDecisionTitle = (kind) => {
  if (kind === "aviso_vencido") return "Aviso vencido";
  if (kind === "aparenta_abandono_no_aviso") return "Aparenta abandono no aviso";
  if (kind === "candidato_abandono_silencioso") return "Candidato a abandono silencioso";
  return "Decisão pendente";
};

