const runAdminPedagogicoRenderers = () => {
  const renderers = [
    renderAdminPedagogicoMetrics,
    renderAdminPedagogicoTabs,
    renderAdminPedOverviewV2,
    renderAdminPedagogicoClassesList,
    renderAdminPedagogicoRetentionPanel,
    renderAdminPedagogicoReposicoesPanel,
    renderAdminPedagogicoGroups,
    renderAdminPedagogicoStudentsPanel,
    renderAdminPedagogicoTeachersPanel,
    renderAdminPedagogicoPeoplePanel,
    renderAdminPedagogicoQualityPanel,
    renderAdminPedagogicoPlansPanel,
    renderAdminPedagogicoSurveysPanel,
    renderAdminPedagogicoNpsCsatPanel,
    renderAdminPedagogicoAlertsPanel,
    renderAdminPedagogicoFeedbacksPanel,
    renderAdminPedagogicoReportsPanel,
    renderAdminPedagogicoOnboardingPanel,
    renderAdminPedagogicoConflicts,
    renderAdminPedagogicoLinksPanel,
  ];
  let failed = 0;
  const failedNames = [];
  renderers.forEach((render) => {
    try {
      render();
    } catch (error) {
      failed += 1;
      failedNames.push(render?.name || "unknown");
      console.error("[admin-ped] partial render failed", render?.name || "unknown", error);
    }
  });
  return { failed, failedNames };
};

const renderAdminControlePedagogicoPanel = async ({ force = false } = {}) => {
  if (currentRole !== "admin") return;
  if (!(adminPedRoot instanceof HTMLElement)) return;
  if (adminPedagogicoState.isLoading) return;

  const now = Date.now();
  if (!force && adminPedagogicoState.loadedAt && now - adminPedagogicoState.loadedAt < 45_000) {
    const { failed, failedNames } = runAdminPedagogicoRenderers();
    refreshAdminPedagogicoRetentionState({ force: false }).catch((error) => console.warn("[admin-ped] retention refresh skipped", error));
    refreshAdminPedagogicoReposicoesState({ force: false }).catch((error) => console.warn("[admin-ped] reposições refresh skipped", error));
    const detail = failedNames.length ? `Renderers com falha: ${failedNames.join(", ")}` : "";
    if (failedNames.length) console.warn("[admin-ped] renderers failed", failedNames);
    setAdminPedagogicoStatus(failed ? "Alguns blocos não puderam ser exibidos agora." : "", failed ? "warn" : "", detail);
    return;
  }

  adminPedagogicoState.isLoading = true;
  setAdminPedagogicoStatus("Carregando…");
  if (adminPedError instanceof HTMLElement) adminPedError.hidden = true;

  try {
    const loadFallback = (label, promise, fallback) =>
      promise.catch((error) => {
        console.error(`[admin-ped] ${label} load failed`, error);
        return fallback;
      });
    const [
      teachers,
      students,
      classes,
      groups,
      plans,
      surveys,
      teacherAlerts,
      pedagogicalFeedbacks,
      liveLessonFeedbacksData,
      lessonLogs,
      onboardingContentsAll,
      onboardingQuizzes,
      onboardingProgressAll,
      teacherQuizSubmissionsAll,
      liveLessons,
      scheduleEvents,
      pedagogicalOps,
    ] = await Promise.all([
      loadFallback("teachers", fetchUserRowsFromFirestore("teacher"), []),
      loadFallback("students", fetchUserRowsFromFirestore("student"), []),
      loadFallback("classes", fetchClassesFromFirestore(), []),
      loadFallback("groups", fetchGroupsFromFirestore(), []),
      loadFallback("plans", fetchPlansFromFirestore(), []),
      loadFallback("surveys", fetchSurveysFromFirestore(), []),
      loadFallback("teacherAlerts", fetchTeacherAlertsFromFirestore(), []),
      loadFallback("pedagogicalFeedbacks", fetchPedagogicalFeedbacksFromFirestore(), []),
      loadFallback("liveLessonFeedbacks", fetchLiveLessonFeedbacks(), { summary: {}, feedbacks: [] }),
      loadFallback("lessonLogs", fetchLessonLogsFromFirestore(), []),
      loadFallback("onboardingContents", fetchOnboardingContentsFromFirestore({ includeInactive: true }), []),
      loadFallback("onboardingQuizzes", fetchOnboardingQuizzesFromFirestore(), []),
      loadFallback("onboardingProgress", fetchAllTeacherOnboardingProgressFromFirestore(), []),
      loadFallback("teacherQuizSubmissions", fetchAllTeacherQuizSubmissionsFromFirestore(), []),
      loadFallback("liveLessons", fetchLiveLessonsForAdminPedagogico(), []),
      loadFallback("scheduleEvents", fetchAdminPedScheduleEvents(), []),
      fetchWithAuth("/api/pedagogico/dashboard")
        .then(async (res) => (res.ok ? res.json() : { metrics: {} }))
        .catch((error) => {
          console.error("[admin-ped] pedagogical dashboard load failed", error);
          return { metrics: {} };
        }),
    ]);

    const liveClasses = normalizeLiveLessonsAsAdminClasses(liveLessons);
    const liveTeachers = liveClasses
      .filter((row) => row.teacherId || row.teacherName)
      .map((row) => ({
        id: row.teacherId || `name:${row.teacherName}`,
        nome: row.teacherName || "Professor",
        ativo: true,
        source: "supabase",
      }));
    const liveStudents = liveClasses.flatMap((row) =>
      row.studentIds.map((id, index) => ({
        id: id || `name:${row.studentNames[index] || ""}`,
        nome: row.studentNames[index] || "Aluno",
        ativo: true,
        professorId: row.teacherId || "",
        source: "supabase",
      }))
    );
    const opsStudents = (Array.isArray(pedagogicalOps?.students) ? pedagogicalOps.students : []).map((row) => ({
      ...row,
      id: String(row.id || row.aluno_id || row.aluno_chave || ""),
      sourceBusinessId: String(row.aluno_id || row.aluno_chave || row.id || ""),
      nome: String(row.nome || row.aluno_nome || "Aluno"),
      email: String(row.email || ""),
      ativo: row.ativo_acesso !== false,
      ativo_acesso: row.ativo_acesso !== false,
      status_acesso: row.status_acesso || "ativo",
      professorId: row.professor_id || "",
      plano: row.plano || "",
      source: row.source || "supabase",
    }));
    const personMergeKey = (row) => {
      if (row && typeof row === "object" && (row.firestoreDocId || row.sourceBusinessId || row.cancelamento || row.cancelamentosAnteriores || row.tipo === "student")) {
        const studentKeys = getAdminStudentMergeKeys(row);
        if (studentKeys.length) return studentKeys[0];
      }
      const email = String(row?.email || "").trim().toLowerCase();
      if (email) return `email:${email}`;
      const phone = String(row?.telefone || "").replace(/\D+/g, "");
      if (phone) return `phone:${phone}`;
      const name = String(row?.nome || row?.aluno_nome || "").trim().toLowerCase();
      return name ? `name:${name}` : `id:${String(row?.id || "")}`;
    };
    const mergePeople = (primary, fallback) => {
      // OWNERSHIP: cadastro=Firestore, operação=Supabase (contrato 2026-07-12)
      const byId = new Map();
      const canonicalByAlias = new Map();
      [...(Array.isArray(primary) ? primary : []), ...(Array.isArray(fallback) ? fallback : [])].forEach((row) => {
        if (!row || typeof row !== "object") return;
        const mergeKeys =
          row && typeof row === "object" && (row.firestoreDocId || row.sourceBusinessId || row.cancelamento || row.cancelamentosAnteriores || row.tipo === "student")
            ? getAdminStudentMergeKeys(row)
            : [personMergeKey(row)].filter(Boolean);
        const key = mergeKeys.find((candidate) => canonicalByAlias.has(candidate)) || mergeKeys[0];
        if (!key || key === "id:") return;
        const previous = byId.get(key);
        const merged =
          previous && (previous?.firestoreDocId || row?.firestoreDocId || previous?.cancelamento || row?.cancelamento)
            ? mergeAdminStudentWithCachedProfile(previous, row)
            : previous
              ? { ...row, ...previous, aluno_chave: row.aluno_chave || previous.aluno_chave }
              : row;
        byId.set(key, merged);
        const aliases =
          merged && typeof merged === "object" && (merged.firestoreDocId || merged.sourceBusinessId || merged.cancelamento || merged.cancelamentosAnteriores || merged.tipo === "student")
            ? getAdminStudentMergeKeys(merged)
            : [personMergeKey(merged)].filter(Boolean);
        aliases.forEach((alias) => canonicalByAlias.set(alias, key));
      });
      return Array.from(byId.values());
    };

    adminPedagogicoState.teachers = mergePeople(teachers, liveTeachers);
    adminPedagogicoState.teachersById = new Map(adminPedagogicoState.teachers.map((t) => [String(t.id || ""), t]));
    const mergedStudents = mergePeople(students, [...opsStudents, ...liveStudents]).map((student) => {
      const canonicalId = String(student?.firestoreDocId || student?.docId || student?.documentId || student?.id || "").trim();
      return canonicalId ? { ...student, id: canonicalId, firestoreDocId: canonicalId, docId: canonicalId, documentId: canonicalId } : student;
    });
    adminPedagogicoState.students = mergedStudents;
    adminPedagogicoState.studentsById = new Map(
      mergedStudents
        .map((s) => [String(s?.firestoreDocId || s?.id || ""), s])
        .filter(([id]) => Boolean(id))
    );
    adminPedagogicoState.studentAliasToDocId = buildStudentAliasMap(mergedStudents);
    adminPedagogicoState.classes = mergeAdminPedagogicoClasses(classes, liveClasses);
    adminPedagogicoState.groups = Array.isArray(groups) ? groups : [];
    adminPedagogicoState.groupsById = new Map(adminPedagogicoState.groups.map((g) => [String(g.id || ""), g]));
    adminPedagogicoState.groupsByClassId = new Map(
      adminPedagogicoState.groups.filter((g) => g && g.classId).map((g) => [String(g.classId || ""), g])
    );
    adminPedagogicoState.plans = Array.isArray(plans) ? plans : [];
    adminPedagogicoState.plansById = new Map(adminPedagogicoState.plans.map((p) => [String(p.id || ""), p]));
    adminPedagogicoState.surveys = Array.isArray(surveys) ? surveys : [];
    adminPedagogicoState.teacherAlerts = Array.isArray(teacherAlerts) ? teacherAlerts : [];
    adminPedagogicoState.pedagogicalFeedbacks = Array.isArray(pedagogicalFeedbacks) ? pedagogicalFeedbacks : [];
    adminPedagogicoState.liveLessonFeedbacks = Array.isArray(liveLessonFeedbacksData?.feedbacks) ? liveLessonFeedbacksData.feedbacks : [];
    adminPedagogicoState.lessonLogs = Array.isArray(lessonLogs) ? lessonLogs : [];
    adminPedagogicoState.scheduleEvents = Array.isArray(scheduleEvents) ? scheduleEvents : [];
    adminPedagogicoState.onboardingContentsAll = Array.isArray(onboardingContentsAll) ? onboardingContentsAll : [];
    adminPedagogicoState.onboardingContents = adminPedagogicoState.onboardingContentsAll.slice().sort((a, b) => (a.order || 0) - (b.order || 0));
    adminPedagogicoState.onboardingQuizzes = Array.isArray(onboardingQuizzes) ? onboardingQuizzes : [];
    adminPedagogicoState.teacherOnboardingProgressAll = Array.isArray(onboardingProgressAll) ? onboardingProgressAll : [];
    adminPedagogicoState.teacherQuizSubmissionsAll = Array.isArray(teacherQuizSubmissionsAll) ? teacherQuizSubmissionsAll : [];
    adminPedagogicoState.pedagogicalOps =
      pedagogicalOps && typeof pedagogicalOps === "object"
        ? pedagogicalOps
        : { metrics: {}, onboarding: [], alerts: [], pendingLessons: [], riskStudents: [], flexge: [] };
    adminPedagogicoState.conflicts = computeAdminPedagogicoConflicts(adminPedagogicoState.classes);
    adminPedagogicoState.loadedAt = Date.now();

    const teacherSelect = adminPedRoot.querySelector('[data-admin-ped-filter="teacherId"]');
    if (teacherSelect instanceof HTMLSelectElement) {
      const selected = String(adminPedagogicoState.filters.teacherId || "");
      teacherSelect.innerHTML =
        `<option value="">Todos</option>` +
        adminPedagogicoState.teachers
          .slice()
          .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
          .map((t) => `<option value="${escapeHtml(String(t.id))}">${escapeHtml(String(t.nome || "Professor"))}</option>`)
          .join("");
      teacherSelect.value = selected;
    }

    const studentSelect = adminPedRoot.querySelector('[data-admin-ped-filter="studentId"]');
    if (studentSelect instanceof HTMLSelectElement) {
      const selected = String(adminPedagogicoState.filters.studentId || "");
      studentSelect.innerHTML =
        `<option value="">Todos</option>` +
        adminPedagogicoState.students
          .slice()
          .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
          .map((s) => `<option value="${escapeHtml(String(s.id))}">${escapeHtml(String(s.nome || "Aluno"))}</option>`)
          .join("");
      studentSelect.value = selected;
    }

    const planSelect = adminPedRoot.querySelector('[data-admin-ped-filter="plan"]');
    if (planSelect instanceof HTMLSelectElement) {
      const selected = String(adminPedagogicoState.filters.plan || "");
      const plans = Array.isArray(adminPedagogicoState.plans) ? adminPedagogicoState.plans : [];
      const keys = plans
        .filter((p) => p && typeof p === "object" && String(p.status || "").toLowerCase() !== "inactive")
        .map((p) => normalizePlanKeyLoose(p.name))
        .filter(Boolean);
      const unique = [...new Set(keys.length ? keys : ["turma", "gold", "diamond"])]
        .slice()
        .sort((a, b) => String(a).localeCompare(String(b), "pt-BR"));
      planSelect.innerHTML = `<option value="">Todos</option>` + unique.map((k) => `<option value="${escapeHtml(k)}">${escapeHtml(k.toUpperCase())}</option>`).join("");
      planSelect.value = selected;
    }

    const { failed, failedNames } = runAdminPedagogicoRenderers();
    refreshAdminPedagogicoRetentionState({ force: true }).catch((error) => console.warn("[admin-ped] retention refresh skipped", error));
    refreshAdminPedagogicoReposicoesState({ force: true }).catch((error) => console.warn("[admin-ped] reposições refresh skipped", error));
    const degraded = Boolean(adminPedagogicoState.pedagogicalOps?.degraded);
    const degradedReason = String(adminPedagogicoState.pedagogicalOps?.degradedReason || "").trim();
    const detail = [
      failedNames.length ? `Renderers com falha: ${failedNames.join(", ")}` : "",
      degradedReason ? `Backend: ${degradedReason}` : degraded ? "Backend: algum sub-bloco pedagógico falhou" : "",
    ]
      .filter(Boolean)
      .join(" · ");
    if (failedNames.length || degraded) {
      console.warn("[admin-ped] panel degraded", { failedRenderers: failedNames, degradedReason });
    }
    setAdminPedagogicoStatus(
      failed || degraded ? "Painel carregado com alguns dados temporariamente indisponíveis." : "",
      failed || degraded ? "warn" : "",
      detail
    );
  } catch (error) {
    console.error("[admin] controle-pedagogico load failed:", error);
    setAdminPedagogicoStatus("Não foi possível carregar agora.", "error");
    if (adminPedError instanceof HTMLElement) adminPedError.hidden = false;
  } finally {
    adminPedagogicoState.isLoading = false;
  }
};

const findAdminPedClassById = (id) => {
  const safe = String(id || "").trim();
  if (!safe) return null;
  const arr = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  return arr.find((c) => String(c?.id || "") === safe) || null;
};

const rerenderAdminStudentSheetIfOpen = () => {
  if (!adminStudentsState.history?.isOpen) return;
  renderAdminStudentSheet();
};

const buildAdminPedDaysCheckboxesHtml = (selectedDays) => {
  const set = new Set(Array.isArray(selectedDays) ? selectedDays : []);
  const defs = [
    { d: 1, label: "Seg" },
    { d: 2, label: "Ter" },
    { d: 3, label: "Qua" },
    { d: 4, label: "Qui" },
    { d: 5, label: "Sex" },
    { d: 6, label: "Sáb" },
  ];
  return defs
    .map(
      (it) => `
      <label class="admin-ped-day">
        <input type="checkbox" value="${it.d}" ${set.has(it.d) ? "checked" : ""} data-admin-ped-day />
        <span>${escapeHtml(it.label)}</span>
      </label>
    `
    )
    .join("");
};

const openAdminPedClassModal = ({ mode = "create", classRow = null, prefill = null, returnFocusEl = null } = {}) => {
  const isEdit = mode === "edit" && classRow && classRow.id;
  const row = classRow && typeof classRow === "object" ? classRow : null;
  const seed = prefill && typeof prefill === "object" ? prefill : null;

  const teachers = Array.isArray(adminPedagogicoState.teachers) ? adminPedagogicoState.teachers : [];
  const students = Array.isArray(adminPedagogicoState.students) ? adminPedagogicoState.students : [];
  const plans = Array.isArray(adminPedagogicoState.plans) ? adminPedagogicoState.plans : [];

  const teacherOptions =
    `<option value="">Selecione...</option>` +
    teachers
      .slice()
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
      .map((t) => `<option value="${escapeHtml(String(t.id))}">${escapeHtml(String(t.nome || "Professor"))}</option>`)
      .join("");

  const planKeys = plans
    .filter((p) => p && typeof p === "object" && String(p.status || "").toLowerCase() !== "inactive")
    .map((p) => normalizePlanKeyLoose(p.name))
    .filter(Boolean);
  const uniquePlanKeys = [...new Set(planKeys.length ? planKeys : ["turma", "gold", "diamond"])];
  const planOptions =
    `<option value="">Selecione...</option>` +
    uniquePlanKeys
      .slice()
      .sort((a, b) => String(a).localeCompare(String(b), "pt-BR"))
      .map((k) => `<option value="${escapeHtml(String(k))}">${escapeHtml(String(k).toUpperCase())}</option>`)
      .join("");

  const statusOptions = `
    <option value="active">Ativa</option>
    <option value="paused">Pausada</option>
    <option value="ended">Encerrada</option>
  `;

  const classId = isEdit ? String(row.id) : `class_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
  const typeValue = isEdit ? normalizeClassType(row.type) : normalizeClassType(seed?.type) || "individual";
  const statusValue = isEdit ? normalizeClassStatus(row.status) : normalizeClassStatus(seed?.status) || "active";
  const teacherValue = isEdit ? String(row.teacherId || "") : String(seed?.teacherId || "");
  const planValue = isEdit ? normalizePlanKeyLoose(row.plan) : normalizePlanKeyLoose(seed?.plan || "");
  const groupNameValue = isEdit ? String(row.groupName || "") : String(seed?.groupName || "");
  const startDateValue = isEdit ? String(row.startDate || "") : String(seed?.startDate || createDateKey(new Date()));
  const endDateValue = isEdit ? String(row.endDate || "") : String(seed?.endDate || "");
  const teacherNameValue = String(adminPedagogicoState.teachersById?.get(teacherValue)?.nome || "").trim();
  const lockedStudentIds = (() => {
    const fromRow = isEdit ? (Array.isArray(row.studentIds) ? row.studentIds : []) : [];
    const fromSeed = Array.isArray(seed?.studentIds) ? seed.studentIds : seed?.studentId ? [seed.studentId] : [];
    const out = (fromRow.length ? fromRow : fromSeed).map((id) => String(id || "").trim()).filter(Boolean);
    return [...new Set(out)];
  })();
  const lockedStudentId = lockedStudentIds.length === 1 ? lockedStudentIds[0] : "";
  const lockedStudentMeta = lockedStudentId ? (adminPedagogicoState.studentsById instanceof Map ? adminPedagogicoState.studentsById.get(lockedStudentId) || null : null) : null;
  const studentIdsValue = lockedStudentIds.length ? lockedStudentIds : isEdit ? (Array.isArray(row.studentIds) ? row.studentIds : []) : (Array.isArray(seed?.studentIds) ? seed.studentIds : []);
  const studentNamesValue = studentIdsValue
    .map((id) => String(adminPedagogicoState.studentsById?.get(String(id))?.nome || "").trim())
    .filter(Boolean);
  const existingEventIds = isEdit
    ? Array.isArray(row.linkedEventIds)
      ? row.linkedEventIds.map((id) => String(id || "").trim()).filter(Boolean)
      : []
    : [];
  const linkedGroupId = isEdit
    ? String(row.linkedEventGroupId || row.grupoRecorrenciaId || "").trim()
    : String(seed?.linkedEventGroupId || seed?.grupoRecorrenciaId || classId).trim() || classId;

  const initialSchedule = (() => {
    const source = isEdit ? row?.scheduleDays : seed?.scheduleDays;
    const normalized = normalizeAdminPedWeeklyScheduleDays(source || []);
    const hasAny = normalized.some((day) => day.enabled);
    if (hasAny) return normalized;
    const legacyDays = normalizeDaysOfWeek(isEdit ? row?.daysOfWeek : seed?.daysOfWeek || []);
    if (legacyDays.length) {
      const legacyStart = isEdit ? formatHmFromMinutes(row.startMin || 0) : clampTime(seed?.startTime || "14:00", "14:00");
      const legacyEnd = isEdit ? formatHmFromMinutes(row.endMin || 0) : clampTime(seed?.endTime || "14:30", "14:30");
      return normalizeAdminPedWeeklyScheduleDays(
        legacyDays.map((weekday) => ({
          weekday,
          enabled: true,
          startTime: legacyStart,
          endTime: legacyEnd,
        }))
      );
    }
    const fallbackStart = clampTime(seed?.startTime || "14:00", "14:00");
    const fallbackEnd = clampTime(seed?.endTime || "14:30", "14:30");
    return normalizeAdminPedWeeklyScheduleDays([
      { weekday: 1, enabled: true, startTime: fallbackStart, endTime: fallbackEnd },
    ]);
  })();
  const activeScheduleDays = initialSchedule.filter((day) => day && day.enabled);
  const initialStartTime = activeScheduleDays[0]?.startTime || clampTime(seed?.startTime || "14:00", "14:00");
  const initialEndTime = activeScheduleDays[0]?.endTime || clampTime(seed?.endTime || "14:30", "14:30");
  const notesValue = isEdit ? String(row.notes || "") : String(seed?.notes || "");
  const titleValue = buildAdminPedLessonTitle({
    studentName: lockedStudentMeta?.nome || studentNamesValue[0] || String(seed?.studentName || ""),
    teacherName: teacherNameValue || String(seed?.teacherName || ""),
  });
  const typeLocked = lockedStudentId && typeValue === "individual";

  const studentsHtml = students
    .slice()
    .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
    .map((s) => {
      const id = String(s.id || "");
      const checked = studentIdsValue.includes(id);
      return `
        <label class="admin-ped-student">
          <input type="checkbox" value="${escapeHtml(id)}" ${checked ? "checked" : ""} data-admin-ped-student />
          <span>${escapeHtml(String(s.nome || "Aluno"))}</span>
        </label>
      `;
    })
    .join("");

  const studentFixedHtml = lockedStudentId
    ? `
      <div class="admin-ped-modal-fixed-student">
        <span>Aluno</span>
        <strong>${escapeHtml(String(lockedStudentMeta?.nome || studentNamesValue[0] || "Aluno"))}</strong>
      </div>
    `
    : `
      <div class="admin-ped-modal-field">
        <span>Alunos</span>
        <div class="admin-ped-students-picker" data-admin-ped-students>
          ${studentsHtml || `<div class="admin-ped-students-empty">Nenhum aluno encontrado.</div>`}
        </div>
      </div>
    `;

  openModal({
    title: isEdit ? "Editar aula" : "Criar aula",
    bodyHtml: `
      <div class="admin-ped-modal" data-admin-ped-class-form data-admin-ped-class-id="${escapeHtml(classId)}">
        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Tipo de aula</span>
            <select class="admin-ped-modal-select" data-admin-ped-field="type" ${typeLocked ? "disabled" : ""}>
              <option value="individual">Individual</option>
              <option value="group">Grupo</option>
            </select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Professor</span>
            <select class="admin-ped-modal-select" data-admin-ped-field="teacherId">
              ${teacherOptions}
            </select>
          </label>
        </div>

        <label class="admin-ped-modal-field admin-ped-modal-group" data-admin-ped-group-name>
          <span>Nome da turma (somente grupo)</span>
          <input class="admin-ped-modal-input" type="text" data-admin-ped-field="groupName" placeholder="Ex: Turma 01" />
        </label>

        ${studentFixedHtml}

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Plano</span>
            <select class="admin-ped-modal-select" data-admin-ped-field="plan">
              ${planOptions}
            </select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Status</span>
            <select class="admin-ped-modal-select" data-admin-ped-field="status">
              ${statusOptions}
            </select>
          </label>
        </div>

        <label class="admin-ped-modal-field">
          <span>Horários por dia</span>
          <div class="admin-ped-schedule" data-admin-ped-schedule>
            ${buildAdminPedWeeklyScheduleHtml(initialSchedule)}
          </div>
        </label>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Data de início</span>
            <input class="admin-ped-modal-input" type="date" data-admin-ped-field="startDate" />
          </label>
          <label class="admin-ped-modal-field">
            <span>Data de término (opcional)</span>
            <input class="admin-ped-modal-input" type="date" data-admin-ped-field="endDate" />
          </label>
        </div>

        <label class="admin-ped-modal-field">
          <span>Observações (opcional)</span>
          <textarea class="admin-ped-modal-textarea" data-admin-ped-field="notes"></textarea>
        </label>

        <div class="admin-ped-modal-error" data-admin-ped-error hidden></div>
      </div>
    `,
    primaryLabel: isEdit ? "Salvar" : "Criar aula",
    secondaryLabel: "Cancelar",
    hideSecondary: false,
    showTrash: false,
    returnFocusEl,
    onPrimary: () => {
      const form = modalBody?.querySelector("[data-admin-ped-class-form]");
      if (!(form instanceof HTMLElement)) return false;
      const errEl = form.querySelector("[data-admin-ped-error]");
      const setErr = (msg) => {
        if (!(errEl instanceof HTMLElement)) return;
        errEl.textContent = String(msg || "");
        errEl.hidden = !msg;
      };

      const read = (key) => {
        const el = form.querySelector(`[data-admin-ped-field="${CSS.escape(String(key))}"]`);
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || el instanceof HTMLSelectElement) return String(el.value || "").trim();
        return "";
      };

      const type = normalizeClassType(read("type") || typeValue);
      const teacherId = read("teacherId");
      const groupName = read("groupName");
      const plan = normalizePlanKeyLoose(read("plan"));
      const status = normalizeClassStatus(read("status"));
      const startDate = read("startDate");
      const endDate = read("endDate");
      const notes = read("notes");

      const rawStudents = [];
      if (lockedStudentId) {
        rawStudents.push(lockedStudentId);
      } else {
        form.querySelectorAll("[data-admin-ped-student]").forEach((el) => {
          if (!(el instanceof HTMLInputElement) || !el.checked) return;
          const id = String(el.value || "").trim();
          if (id) rawStudents.push(id);
        });
      }
      const studentIds = [...new Set(rawStudents)];

      const scheduleDays = [];
      form.querySelectorAll("[data-admin-ped-schedule-row]").forEach((rowEl) => {
        if (!(rowEl instanceof HTMLElement)) return;
        const weekday = Number(rowEl.getAttribute("data-admin-ped-schedule-row"));
        if (!Number.isFinite(weekday) || weekday < 0 || weekday > 6) return;
        const enabledEl = rowEl.querySelector(`[data-admin-ped-schedule-enabled="${CSS.escape(String(weekday))}"]`);
        const startEl = rowEl.querySelector(`[data-admin-ped-schedule-start="${CSS.escape(String(weekday))}"]`);
        const endEl = rowEl.querySelector(`[data-admin-ped-schedule-end="${CSS.escape(String(weekday))}"]`);
        const enabled = enabledEl instanceof HTMLInputElement ? Boolean(enabledEl.checked) : false;
        const startTime = startEl instanceof HTMLInputElement ? String(startEl.value || "").trim() : "";
        const endTime = endEl instanceof HTMLInputElement ? String(endEl.value || "").trim() : "";
        scheduleDays.push({ weekday, enabled, startTime, endTime });
      });

      const activeSchedule = scheduleDays.filter((day) => day.enabled);
      const firstSchedule = activeSchedule[0] || null;

      if (!teacherId) {
        setErr("Selecione um professor para salvar.");
        return false;
      }
      if (type === "group" && !groupName) {
        setErr("Informe o nome da turma.");
        return false;
      }
      if (!studentIds.length) {
        setErr(type === "group" ? "Selecione pelo menos 1 aluno para a turma." : "Selecione um aluno para a aula.");
        return false;
      }
      if (type === "individual" && studentIds.length !== 1) {
        setErr("A aula individual deve ter exatamente 1 aluno.");
        return false;
      }
      if (!activeSchedule.length) {
        setErr("Selecione pelo menos um dia da semana.");
        return false;
      }
      if (!isValidDateKey(startDate)) {
        setErr("Selecione uma data de início válida.");
        return false;
      }
      if (endDate && !isValidDateKey(endDate)) {
        setErr("Selecione uma data de término válida ou deixe em branco.");
        return false;
      }
      if (endDate && startDate > endDate) {
        setErr("A data de término deve ser posterior à data de início.");
        return false;
      }

      for (const day of activeSchedule) {
        if (!/^\d{2}:\d{2}$/.test(String(day.startTime || "")) || !/^\d{2}:\d{2}$/.test(String(day.endTime || ""))) {
          setErr("Preencha o início e o fim de cada dia ativo.");
          return false;
        }
        if (timeToMinutes(day.endTime) <= timeToMinutes(day.startTime)) {
          setErr("O horário final deve ser maior que o horário inicial.");
          return false;
        }
      }

      const teacherName = String(adminPedagogicoState.teachersById?.get(teacherId)?.nome || "").trim();
      const studentNames = studentIds
        .map((id) => String(adminPedagogicoState.studentsById?.get(id)?.nome || "").trim())
        .filter(Boolean);
      const title = buildAdminPedLessonTitle({ studentName: studentNames[0] || lockedStudentMeta?.nome || "", teacherName });
      const daysOfWeek = activeSchedule.map((day) => day.weekday).filter((day) => Number.isFinite(day));
      const classStartMin = firstSchedule ? timeToMinutes(firstSchedule.startTime) : 0;
      const classEndMin = firstSchedule ? timeToMinutes(firstSchedule.endTime) : 0;

      const nextRow = {
        id: classId,
        type,
        title,
        teacherId,
        teacherName,
        groupName: type === "group" ? groupName : "",
        plan,
        status,
        daysOfWeek,
        scheduleDays: normalizeAdminPedWeeklyScheduleDays(scheduleDays),
        startMin: classStartMin,
        endMin: classEndMin,
        startDate,
        endDate,
        studentIds,
        studentNames,
        notes,
        linkedEventGroupId: linkedGroupId,
        linkedEventIds: existingEventIds,
        roomSlug: isEdit ? String(row?.roomSlug || "") : buildAdminPedShortRoomSlug(classId),
      };

      const all = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
      const candidates = isEdit ? all.filter((c) => String(c.id || "") !== String(classId)) : all;
      const tempList = candidates.concat([nextRow]);
      const conflicts = computeAdminPedagogicoConflicts(tempList);
      const hit = conflicts.find((c) => {
        const a = c.classA || {};
        const b = c.classB || {};
        return String(a.id || "") === String(nextRow.id) || String(b.id || "") === String(nextRow.id);
      });
      if (hit) {
        setErr(`Conflito detectado: ${hit.reason}. Ajuste dias/horários para continuar.`);
        return false;
      }

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = isEdit ? "Salvando…" : "Criando…";
      let createdEventIdForRollback = "";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_pedagogico_save");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");

          if (isEdit && existingEventIds.length) {
            await fetchWithAuth(
              `/api/schedule-events?id=${encodeURIComponent(existingEventIds[0])}&mode=future`,
              { method: "DELETE" }
            ).then(async (res) => {
              if (!res.ok) throw new Error("recurrence_delete_failed");
            });
          }

          const scheduleDaysPayload = activeSchedule
            .map((day) => ({
              weekday:
                ADMIN_PED_WEEKLY_DAY_DEFS.find((def) => def.weekday === day.weekday)?.label?.toLowerCase() || String(day.weekday),
              startTime: String(day.startTime || "").trim(),
              endTime: String(day.endTime || "").trim(),
            }))
            .filter((day) => day.weekday);

          const schedulePayload = {
            id: classId,
            eventType: "lesson",
            alunoId: studentIds[0] || "",
            professorId: teacherId,
            alunoNome: studentNames[0] || lockedStudentMeta?.nome || "",
            alunoEmail: String(adminPedagogicoState.studentsById?.get(studentIds[0] || "")?.email || "").trim(),
            alunoTelefone: String(adminPedagogicoState.studentsById?.get(studentIds[0] || "")?.telefone || "").trim(),
            professorNome: teacherName,
            dateKey: startDate,
            startMin: classStartMin,
            endMin: classEndMin,
            recorrente: true,
            grupoRecorrenciaId: linkedGroupId,
            repeat: { enabled: true, type: "weekly_custom", days: scheduleDaysPayload },
          };
          if (endDate) schedulePayload.endDate = endDate;

          const apiRes = await fetchWithAuth("/api/schedule-events", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(schedulePayload),
          });
          const apiData = await apiRes.json().catch(() => null);
          if (!apiRes.ok) {
            throw new Error(apiData?.error || "schedule_save_failed");
          }

          const linkedEventIds = Array.isArray(apiData?.ids) ? apiData.ids.map((id) => String(id || "").trim()).filter(Boolean) : [];
          const linkedEventGroupId = String(apiData?.grupoRecorrenciaId || linkedGroupId || classId).trim() || classId;
          createdEventIdForRollback = linkedEventIds[0] || "";
          const docRef = firebase.doc(firebase.primaryDb, "classes", classId);
          for (const studentId of studentIds) {
            if (!studentId) continue;
            await patchFirestoreUserDocument({
              userId: studentId,
              context: "admin_pedagogico_student_link",
              patch: {
                professorId: teacherId,
                teacherId: teacherId,
                professorNome: teacherName,
                teacherNome: teacherName,
                atualizadoEm: firebase.serverTimestamp(),
              },
            });
            updateAdminStudentCachedRow(studentId, {
              professorId: teacherId,
              teacherId: teacherId,
              professorNome: teacherName,
              teacherNome: teacherName,
            });
          }
          const payload = {
            ...nextRow,
            linkedEventGroupId,
            linkedEventIds,
            source: "student_line",
            updatedBy: String(user.uid || ""),
            updatedAt: firebase.serverTimestamp(),
            ...(isEdit ? null : { createdBy: String(user.uid || ""), createdAt: firebase.serverTimestamp() }),
          };
          await withTimeout(firebase.setDoc(docRef, payload, { merge: true }), 12_000, "firestore_admin_pedagogico_class_merge");
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
          rerenderAdminStudentSheetIfOpen();
        } catch (e) {
          if (createdEventIdForRollback) {
            try {
              await fetchWithAuth(`/api/schedule-events?id=${encodeURIComponent(createdEventIdForRollback)}&mode=future`, {
                method: "DELETE",
              });
            } catch (rollbackError) {
              console.warn("[admin] controle-pedagogico rollback failed:", rollbackError);
            }
          }
          console.error("[admin] controle-pedagogico save failed:", e);
          setErr("Não foi possível salvar agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || (isEdit ? "Salvar" : "Criar aula");
        }
      })();

      return false;
    },
    onSecondary: () => true,
  });

  window.setTimeout(() => {
    const form = modalBody?.querySelector("[data-admin-ped-class-form]");
    if (!(form instanceof HTMLElement)) return;
    const setVal = (key, value) => {
      const el = form.querySelector(`[data-admin-ped-field="${CSS.escape(String(key))}"]`);
      if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement || el instanceof HTMLTextAreaElement) el.value = String(value ?? "");
    };
    setVal("type", typeValue);
    setVal("teacherId", teacherValue);
    setVal("plan", planValue);
    setVal("status", statusValue);
    setVal("groupName", groupNameValue);
    setVal("startDate", startDateValue);
    setVal("endDate", endDateValue);
    setVal("notes", notesValue);
    const typeSel = form.querySelector('[data-admin-ped-field="type"]');
    const groupWrap = form.querySelector("[data-admin-ped-group-name]");
    const studentsPicker = form.querySelector("[data-admin-ped-students]");
    if (typeSel instanceof HTMLSelectElement && typeLocked) typeSel.disabled = true;
    if (studentsPicker instanceof HTMLElement && lockedStudentId) studentsPicker.hidden = true;
    if (groupWrap instanceof HTMLElement) groupWrap.hidden = typeValue !== "group";
    const firstFocusable = form.querySelector(
      'select:not([disabled]), input:not([type="hidden"]):not([disabled]), textarea:not([disabled]), button:not([disabled])'
    );
    if (firstFocusable instanceof HTMLElement) {
      try {
        firstFocusable.focus();
      } catch {}
    }

    const syncDay = (weekday) => {
      const rowEl = form.querySelector(`[data-admin-ped-schedule-row="${CSS.escape(String(weekday))}"]`);
      if (!(rowEl instanceof HTMLElement)) return;
      const enabledEl = rowEl.querySelector(`[data-admin-ped-schedule-enabled="${CSS.escape(String(weekday))}"]`);
      const timesEl = rowEl.querySelector(`[data-admin-ped-schedule-times="${CSS.escape(String(weekday))}"]`);
      const unavailableEl = rowEl.querySelector(`[data-admin-ped-schedule-unavailable="${CSS.escape(String(weekday))}"]`);
      const isEnabled = enabledEl instanceof HTMLInputElement ? enabledEl.checked : false;
      if (timesEl instanceof HTMLElement) timesEl.hidden = !isEnabled;
      if (unavailableEl instanceof HTMLElement) unavailableEl.hidden = isEnabled;
      rowEl.classList.toggle("is-active", isEnabled);
      rowEl.classList.toggle("is-disabled", !isEnabled);
    };

    form.querySelectorAll("[data-admin-ped-schedule-row]").forEach((rowEl) => {
      if (!(rowEl instanceof HTMLElement)) return;
      const weekday = Number(rowEl.getAttribute("data-admin-ped-schedule-row"));
      if (!Number.isFinite(weekday)) return;
      syncDay(weekday);
      const enabledEl = rowEl.querySelector(`[data-admin-ped-schedule-enabled="${CSS.escape(String(weekday))}"]`);
      if (enabledEl instanceof HTMLInputElement) {
        enabledEl.addEventListener("change", () => syncDay(weekday));
      }
      const copyBtn = rowEl.querySelector(`[data-admin-ped-schedule-copy="${CSS.escape(String(weekday))}"]`);
      if (copyBtn instanceof HTMLButtonElement) {
        copyBtn.addEventListener("click", () => {
          const startEl = rowEl.querySelector(`[data-admin-ped-schedule-start="${CSS.escape(String(weekday))}"]`);
          const endEl = rowEl.querySelector(`[data-admin-ped-schedule-end="${CSS.escape(String(weekday))}"]`);
          const startValue = startEl instanceof HTMLInputElement ? String(startEl.value || "").trim() : "";
          const endValue = endEl instanceof HTMLInputElement ? String(endEl.value || "").trim() : "";
          if (!startValue || !endValue) return;
          form.querySelectorAll("[data-admin-ped-schedule-row]").forEach((targetRow) => {
            if (!(targetRow instanceof HTMLElement)) return;
            const targetWeekday = Number(targetRow.getAttribute("data-admin-ped-schedule-row"));
            if (!Number.isFinite(targetWeekday) || targetWeekday === weekday) return;
            const targetEnabled = targetRow.querySelector(`[data-admin-ped-schedule-enabled="${CSS.escape(String(targetWeekday))}"]`);
            if (!(targetEnabled instanceof HTMLInputElement) || !targetEnabled.checked) return;
            const targetStart = targetRow.querySelector(`[data-admin-ped-schedule-start="${CSS.escape(String(targetWeekday))}"]`);
            const targetEnd = targetRow.querySelector(`[data-admin-ped-schedule-end="${CSS.escape(String(targetWeekday))}"]`);
            if (targetStart instanceof HTMLInputElement) targetStart.value = startValue;
            if (targetEnd instanceof HTMLInputElement) targetEnd.value = endValue;
          });
        });
      }
    });

    if (typeSel instanceof HTMLSelectElement && groupWrap instanceof HTMLElement) {
      typeSel.addEventListener("change", () => {
        groupWrap.hidden = normalizeClassType(typeSel.value) !== "group";
      });
    }
  }, 0);
};

const openAdminPedPlanModal = ({ mode = "create", planRow = null } = {}) => {
  const isEdit = mode === "edit" && planRow && planRow.id;
  const row = planRow && typeof planRow === "object" ? planRow : null;

  openModal({
    title: isEdit ? "Editar plano" : "Criar plano",
    primaryLabel: isEdit ? "Salvar" : "Criar plano",
    secondaryLabel: "Cancelar",
    hideSecondary: false,
    showTrash: false,
    bodyHtml: `
      <div class="admin-ped-modal" data-admin-ped-plan-form>
        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Nome do plano</span>
            <input class="admin-ped-modal-input" type="text" data-admin-ped-plan-field="name" placeholder="Ex: Gold" />
          </label>
          <label class="admin-ped-modal-field">
            <span>Status</span>
            <select class="admin-ped-modal-select" data-admin-ped-plan-field="status">
              <option value="active">Ativo</option>
              <option value="inactive">Inativo</option>
            </select>
          </label>
        </div>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Preço mensal (R$)</span>
            <input class="admin-ped-modal-input" type="number" inputmode="decimal" min="0" step="0.01" data-admin-ped-plan-field="monthlyPrice" placeholder="Ex: 497.00" />
          </label>
          <label class="admin-ped-modal-field">
            <span>Aulas semanais</span>
            <input class="admin-ped-modal-input" type="number" inputmode="numeric" min="0" step="1" data-admin-ped-plan-field="weeklyClasses" placeholder="Ex: 1" />
          </label>
        </div>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Tipo</span>
            <select class="admin-ped-modal-select" data-admin-ped-plan-field="type">
              <option value="individual">Individual</option>
              <option value="group">Grupo</option>
              <option value="hybrid">Híbrido</option>
            </select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Descrição</span>
            <input class="admin-ped-modal-input" type="text" data-admin-ped-plan-field="description" placeholder="Ex: 1 aula/semana + material" />
          </label>
        </div>

        <div class="admin-ped-modal-error" data-admin-ped-plan-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const form = modalBody?.querySelector("[data-admin-ped-plan-form]");
      if (!(form instanceof HTMLElement)) return false;
      const errEl = form.querySelector("[data-admin-ped-plan-error]");
      const setErr = (msg) => {
        if (errEl instanceof HTMLElement) {
          errEl.textContent = String(msg || "");
          errEl.hidden = !msg;
        }
      };

      const read = (key) => {
        const el = form.querySelector(`[data-admin-ped-plan-field="${CSS.escape(String(key))}"]`);
        if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement) return String(el.value || "").trim();
        return "";
      };

      const name = read("name");
      const status = normalizePlanStatus(read("status"));
      const type = normalizePlanType(read("type"));
      const monthlyPriceRaw = read("monthlyPrice");
      const weeklyRaw = read("weeklyClasses");
      const description = read("description");

      const monthlyPrice = monthlyPriceRaw ? Number(monthlyPriceRaw) : null;
      const weeklyClasses = weeklyRaw ? Number.parseInt(weeklyRaw, 10) : null;

      setErr("");
      if (!name) {
        setErr("Informe o nome do plano.");
        return false;
      }
      if (monthlyPriceRaw && !Number.isFinite(monthlyPrice)) {
        setErr("Preço mensal inválido.");
        return false;
      }
      if (weeklyRaw && !Number.isFinite(weeklyClasses)) {
        setErr("Quantidade de aulas semanais inválida.");
        return false;
      }

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = isEdit ? "Salvando…" : "Criando…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_plan_save");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");

          const id = isEdit ? String(row.id) : `plan_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
          const docRef = firebase.doc(firebase.primaryDb, "plans", id);
          const payload = {
            id,
            name,
            monthlyPrice: Number.isFinite(monthlyPrice) ? monthlyPrice : null,
            weeklyClasses: Number.isFinite(weeklyClasses) ? weeklyClasses : null,
            type,
            description,
            status,
            updatedAt: firebase.serverTimestamp(),
            updatedBy: String(user.uid || ""),
            ...(isEdit ? null : { createdAt: firebase.serverTimestamp(), createdBy: String(user.uid || "") }),
          };
          await withTimeout(firebase.setDoc(docRef, payload, { merge: true }), 12_000, "firestore_admin_plan_merge");
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] plan save failed:", e);
          setErr("Não foi possível salvar agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || (isEdit ? "Salvar" : "Criar plano");
        }
      })();

      return false;
    },
    onSecondary: () => true,
  });

  window.setTimeout(() => {
    const form = modalBody?.querySelector("[data-admin-ped-plan-form]");
    if (!(form instanceof HTMLElement)) return;
    const setVal = (key, value) => {
      const el = form.querySelector(`[data-admin-ped-plan-field="${CSS.escape(String(key))}"]`);
      if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement) el.value = String(value ?? "");
    };
    setVal("name", row?.name || "");
    setVal("status", normalizePlanStatus(row?.status || "active"));
    setVal("type", normalizePlanType(row?.type || "individual"));
    setVal("monthlyPrice", Number.isFinite(Number(row?.monthlyPrice)) ? String(row.monthlyPrice) : "");
    setVal("weeklyClasses", Number.isFinite(Number(row?.weeklyClasses)) ? String(row.weeklyClasses) : "");
    setVal("description", row?.description || "");
  }, 0);
};

const toggleAdminPedPlanStatus = ({ planId } = {}) => {
  const id = String(planId || "").trim();
  if (!id) return;
  const row = (Array.isArray(adminPedagogicoState.plans) ? adminPedagogicoState.plans : []).find((p) => String(p?.id || "") === id) || null;
  if (!row) return;
  const next = normalizePlanStatus(row.status) === "active" ? "inactive" : "active";

  (async () => {
    try {
      const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_plan_toggle");
      const user = await waitForFirebaseAuthReady(firebase, 5000);
      if (!user) throw new Error("not_authenticated");
      const docRef = firebase.doc(firebase.primaryDb, "plans", id);
      await withTimeout(
        firebase.setDoc(docRef, { status: next, updatedAt: firebase.serverTimestamp(), updatedBy: String(user.uid || "") }, { merge: true }),
        12_000,
        "firestore_admin_plan_toggle"
      );
      await renderAdminControlePedagogicoPanel({ force: true });
    } catch (e) {
      console.error("[admin] plan toggle failed:", e);
      setAdminPedagogicoStatus("Não foi possível atualizar agora.", "error");
    }
  })();
};

const deleteAdminPedPlan = ({ planId } = {}) => {
  const id = String(planId || "").trim();
  if (!id) return;
  const row = (Array.isArray(adminPedagogicoState.plans) ? adminPedagogicoState.plans : []).find((p) => String(p?.id || "") === id) || null;
  const name = String(row?.name || "plano").trim() || "plano";

  const activeStudents = (Array.isArray(adminPedagogicoState.students) ? adminPedagogicoState.students : []).filter((s) => {
    if (!s || typeof s !== "object") return false;
    if (!s.ativo) return false;
    return normalizeSearchText(String(s.plano || "")) === normalizeSearchText(name);
  });

  const needsStrongConfirm = activeStudents.length > 0;
  const confirmHtml = needsStrongConfirm
    ? `
      <p>Existem <strong>${activeStudents.length}</strong> aluno(s) ativo(s) vinculados a este plano. Para excluir, digite <strong>${escapeHtml(
        name
      )}</strong> abaixo.</p>
      <label class="admin-ped-modal-field">
        <span>Confirmação</span>
        <input class="admin-ped-modal-input" type="text" data-admin-ped-plan-confirm placeholder="Digite o nome do plano" />
      </label>
    `
    : `<p>Tem certeza que deseja excluir <strong>${escapeHtml(name)}</strong>? Esta ação não pode ser desfeita.</p>`;

  openModal({
    title: "Excluir plano",
    primaryLabel: "Excluir",
    secondaryLabel: "Cancelar",
    bodyHtml: `<div class="admin-ped-modal">${confirmHtml}<div class="admin-ped-modal-error" data-admin-ped-plan-delete-error hidden>—</div></div>`,
    onPrimary: () => {
      const wrap = modalBody?.querySelector(".admin-ped-modal");
      const errEl = wrap?.querySelector("[data-admin-ped-plan-delete-error]");
      const setErr = (msg) => {
        if (errEl instanceof HTMLElement) {
          errEl.textContent = String(msg || "");
          errEl.hidden = !msg;
        }
      };
      setErr("");
      if (needsStrongConfirm) {
        const input = wrap?.querySelector("[data-admin-ped-plan-confirm]");
        const typed = input instanceof HTMLInputElement ? String(input.value || "").trim() : "";
        if (normalizeSearchText(typed) !== normalizeSearchText(name)) {
          setErr("Confirmação inválida.");
          return false;
        }
      }

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Excluindo…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_plan_delete");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");
          const docRef = firebase.doc(firebase.primaryDb, "plans", id);
          await withTimeout(firebase.deleteDoc(docRef), 12_000, "firestore_admin_plan_delete");
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] plan delete failed:", e);
          setErr("Não foi possível excluir agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || "Excluir";
        }
      })();

      return false;
    },
    onSecondary: () => true,
  });
};

const openAdminPedGroupModal = ({ mode = "create", groupRow = null } = {}) => {
  const isEdit = mode === "edit" && groupRow && groupRow.id;
  const row = groupRow && typeof groupRow === "object" ? groupRow : null;
  const teachers = Array.isArray(adminPedagogicoState.teachers) ? adminPedagogicoState.teachers : [];
  const students = Array.isArray(adminPedagogicoState.students) ? adminPedagogicoState.students : [];
  const plans = Array.isArray(adminPedagogicoState.plans) ? adminPedagogicoState.plans : [];

  const teacherOptions =
    `<option value="">Selecione...</option>` +
    teachers
      .slice()
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
      .map((t) => `<option value="${escapeHtml(String(t.id))}">${escapeHtml(String(t.nome || "Professor"))}</option>`)
      .join("");

  const planOptions =
    `<option value="">Sem plano</option>` +
    plans
      .slice()
      .filter((p) => String(p?.status || "").toLowerCase() !== "inactive")
      .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "pt-BR"))
      .map((p) => `<option value="${escapeHtml(String(p.id))}">${escapeHtml(String(p.name || "Plano"))}</option>`)
      .join("");

  const selectedStudents = new Set((Array.isArray(row?.studentIds) ? row.studentIds : []).map(String));
  const studentsHtml = students
    .slice()
    .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
    .map((s) => {
      const id = String(s.id || "");
      const checked = selectedStudents.has(id);
      return `
        <label class="admin-ped-student">
          <input type="checkbox" value="${escapeHtml(id)}" ${checked ? "checked" : ""} data-admin-ped-group-student />
          <span>${escapeHtml(String(s.nome || "Aluno"))}</span>
        </label>
      `;
    })
    .join("");

  openModal({
    title: isEdit ? "Editar turma" : "Criar turma",
    primaryLabel: isEdit ? "Salvar" : "Criar turma",
    secondaryLabel: "Cancelar",
    bodyHtml: `
      <div class="admin-ped-modal" data-admin-ped-group-form>
        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Nome da turma</span>
            <input class="admin-ped-modal-input" type="text" data-admin-ped-group-field="name" placeholder="Ex: Turma 01" />
          </label>
          <label class="admin-ped-modal-field">
            <span>Status</span>
            <select class="admin-ped-modal-select" data-admin-ped-group-field="status">
              <option value="active">Ativa</option>
              <option value="paused">Pausada</option>
              <option value="ended">Encerrada</option>
            </select>
          </label>
        </div>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Professor</span>
            <select class="admin-ped-modal-select" data-admin-ped-group-field="teacherId">
              ${teacherOptions}
            </select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Plano</span>
            <select class="admin-ped-modal-select" data-admin-ped-group-field="planId">
              ${planOptions}
            </select>
          </label>
        </div>

        <div class="admin-ped-modal-field">
          <span>Dias da semana</span>
          <div class="admin-ped-days" data-admin-ped-group-days>
            ${buildAdminPedDaysCheckboxesHtml(normalizeDaysOfWeek(row?.daysOfWeek || [1]))}
          </div>
        </div>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Início</span>
            <input class="admin-ped-modal-input" type="time" data-admin-ped-group-field="startTime" />
          </label>
          <label class="admin-ped-modal-field">
            <span>Fim</span>
            <input class="admin-ped-modal-input" type="time" data-admin-ped-group-field="endTime" />
          </label>
        </div>

        <div class="admin-ped-modal-field">
          <span>Alunos</span>
          <div class="admin-ped-students-picker">
            ${studentsHtml || `<div class="admin-ped-modal-error">Sem alunos cadastrados.</div>`}
          </div>
        </div>

        <div class="admin-ped-modal-error" data-admin-ped-group-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const form = modalBody?.querySelector("[data-admin-ped-group-form]");
      if (!(form instanceof HTMLElement)) return false;
      const errEl = form.querySelector("[data-admin-ped-group-error]");
      const setErr = (msg) => {
        if (errEl instanceof HTMLElement) {
          errEl.textContent = String(msg || "");
          errEl.hidden = !msg;
        }
      };
      const read = (key) => {
        const el = form.querySelector(`[data-admin-ped-group-field="${CSS.escape(String(key))}"]`);
        if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement) return String(el.value || "").trim();
        return "";
      };

      const name = read("name");
      const status = normalizeClassStatus(read("status"));
      const teacherId = read("teacherId");
      const planId = read("planId");
      const startTime = read("startTime");
      const endTime = read("endTime");
      const startMin = timeToMinutes(startTime);
      const endMin = timeToMinutes(endTime);
      const days = [];
      form.querySelectorAll("[data-admin-ped-day]").forEach((el) => {
        if (!(el instanceof HTMLInputElement)) return;
        if (!el.checked) return;
        const n = Number(el.value);
        if (Number.isFinite(n)) days.push(n);
      });
      const studentIds = [];
      form.querySelectorAll("[data-admin-ped-group-student]").forEach((el) => {
        if (!(el instanceof HTMLInputElement)) return;
        if (el.checked) studentIds.push(String(el.value || "").trim());
      });

      setErr("");
      if (!name) {
        setErr("Informe o nome da turma.");
        return false;
      }
      if (!teacherId) {
        setErr("Selecione um professor.");
        return false;
      }
      if (!days.length) {
        setErr("Selecione pelo menos um dia da semana.");
        return false;
      }
      if (!startMin || !endMin || endMin <= startMin) {
        setErr("O horário final deve ser maior que o horário inicial.");
        return false;
      }
      if (!studentIds.length) {
        setErr("Selecione ao menos 1 aluno.");
        return false;
      }

      const teacherName = String(adminPedagogicoState.teachersById?.get(teacherId)?.nome || "").trim();
      const studentNames = studentIds
        .map((id) => String(adminPedagogicoState.studentsById?.get(id)?.nome || "").trim())
        .filter(Boolean);

      const planRow = planId ? (adminPedagogicoState.plansById instanceof Map ? adminPedagogicoState.plansById.get(planId) || null : null) : null;
      const planName = planRow ? String(planRow.name || "").trim() : "";
      const planKey = normalizePlanKeyLoose(planName);

      const groupId = isEdit ? String(row.id) : `group_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
      const classId = isEdit ? String(row.classId || `class_${groupId}`) : `class_${groupId}`;

      const tempGroupAsClass = {
        id: classId,
        type: "group",
        status,
        teacherId,
        studentIds,
        daysOfWeek: normalizeDaysOfWeek(days),
        startMin,
        endMin,
      };
      const candidates = (Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : []).filter((c) => String(c.id || "") !== classId);
      const conflicts = computeAdminPedagogicoConflicts(candidates.concat([tempGroupAsClass]));
      if (conflicts.length) {
        setErr(`Conflito detectado: ${conflicts[0].reason}. Ajuste dias/horários para continuar.`);
        return false;
      }

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = isEdit ? "Salvando…" : "Criando…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_group_save");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");

          const groupRef = firebase.doc(firebase.primaryDb, "groups", groupId);
          const classRef = firebase.doc(firebase.primaryDb, "classes", classId);

          const groupPayload = {
            id: groupId,
            classId,
            name,
            teacherId,
            teacherName: teacherName || "",
            studentIds,
            studentNames,
            planId: planId || "",
            planName: planName || "",
            daysOfWeek: normalizeDaysOfWeek(days),
            startMin,
            endMin,
            status,
            updatedAt: firebase.serverTimestamp(),
            updatedBy: String(user.uid || ""),
            ...(isEdit ? null : { createdAt: firebase.serverTimestamp(), createdBy: String(user.uid || "") }),
          };

          const classPayload = {
            id: classId,
            type: "group",
            title: name,
            teacherId,
            teacherName: teacherName || "",
            groupId,
            groupName: name,
            planId: planId || "",
            planName: planName || "",
            plan: planKey || "",
            studentIds,
            studentNames,
            daysOfWeek: normalizeDaysOfWeek(days),
            startMin,
            endMin,
            startDate: createDateKey(new Date()),
            endDate: "",
            status,
            notes: "",
            updatedAt: firebase.serverTimestamp(),
            updatedBy: String(user.uid || ""),
            ...(isEdit ? null : { createdAt: firebase.serverTimestamp(), createdBy: String(user.uid || "") }),
          };

          await withTimeout(firebase.setDoc(groupRef, groupPayload, { merge: true }), 12_000, "firestore_admin_group_merge");
          await withTimeout(firebase.setDoc(classRef, classPayload, { merge: true }), 12_000, "firestore_admin_group_class_merge");

          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] group save failed:", e);
          setErr("Não foi possível salvar agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || (isEdit ? "Salvar" : "Criar turma");
        }
      })();

      return false;
    },
    onSecondary: () => true,
  });

  window.setTimeout(() => {
    const form = modalBody?.querySelector("[data-admin-ped-group-form]");
    if (!(form instanceof HTMLElement)) return;
    const setVal = (key, value) => {
      const el = form.querySelector(`[data-admin-ped-group-field="${CSS.escape(String(key))}"]`);
      if (el instanceof HTMLInputElement || el instanceof HTMLSelectElement) el.value = String(value ?? "");
    };
    setVal("name", row?.name || "");
    setVal("status", normalizeClassStatus(row?.status || "active"));
    setVal("teacherId", row?.teacherId || "");
    setVal("planId", row?.planId || "");
    setVal("startTime", row ? formatHmFromMinutes(row.startMin || 0) : "14:00");
    setVal("endTime", row ? formatHmFromMinutes(row.endMin || 0) : "14:30");
  }, 0);
};

const toggleAdminPedGroupStatus = ({ groupId } = {}) => {
  const id = String(groupId || "").trim();
  if (!id) return;
  const row = (Array.isArray(adminPedagogicoState.groups) ? adminPedagogicoState.groups : []).find((g) => String(g?.id || "") === id) || null;
  if (!row) return;
  const current = normalizeClassStatus(row.status);
  const next = current === "active" ? "paused" : "active";
  const classId = String(row.classId || "");

  (async () => {
    try {
      const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_group_toggle");
      const user = await waitForFirebaseAuthReady(firebase, 5000);
      if (!user) throw new Error("not_authenticated");
      await withTimeout(
        firebase.setDoc(firebase.doc(firebase.primaryDb, "groups", id), { status: next, updatedAt: firebase.serverTimestamp() }, { merge: true }),
        12_000,
        "firestore_admin_group_toggle"
      );
      if (classId) {
        await withTimeout(
          firebase.setDoc(firebase.doc(firebase.primaryDb, "classes", classId), { status: next, updatedAt: firebase.serverTimestamp() }, { merge: true }),
          12_000,
          "firestore_admin_group_class_toggle"
        );
      }
      await renderAdminControlePedagogicoPanel({ force: true });
    } catch (e) {
      console.error("[admin] group toggle failed:", e);
      setAdminPedagogicoStatus("Não foi possível atualizar agora.", "error");
    }
  })();
};

const deleteAdminPedGroup = ({ groupId } = {}) => {
  const id = String(groupId || "").trim();
  if (!id) return;
  const row = (Array.isArray(adminPedagogicoState.groups) ? adminPedagogicoState.groups : []).find((g) => String(g?.id || "") === id) || null;
  const label = row?.name ? row.name : "turma";
  const classId = String(row?.classId || "");

  openModal({
    title: "Excluir turma",
    primaryLabel: "Excluir",
    secondaryLabel: "Cancelar",
    bodyHtml: `Tem certeza que deseja excluir <strong>${escapeHtml(label)}</strong>? Esta ação não pode ser desfeita.`,
    onPrimary: () => {
      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Excluindo…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_group_delete");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");
          await withTimeout(firebase.deleteDoc(firebase.doc(firebase.primaryDb, "groups", id)), 12_000, "firestore_admin_group_delete");
          if (classId) {
            await withTimeout(firebase.deleteDoc(firebase.doc(firebase.primaryDb, "classes", classId)), 12_000, "firestore_admin_group_class_delete");
          }
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] group delete failed:", e);
          if (modalBody instanceof HTMLElement) modalBody.innerHTML = "Não foi possível excluir agora.";
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || "Excluir";
        }
      })();
      return false;
    },
    onSecondary: () => true,
  });
};

const openAdminPedStudentLinkModal = ({ studentId } = {}) => {
  const alunoId = String(studentId || "").trim();
  if (!alunoId) return;
  const student = adminPedagogicoState.studentsById instanceof Map ? adminPedagogicoState.studentsById.get(alunoId) || null : null;
  const teachers = Array.isArray(adminPedagogicoState.teachers) ? adminPedagogicoState.teachers : [];
  const groups = Array.isArray(adminPedagogicoState.groups) ? adminPedagogicoState.groups : [];

  const teacherOptions =
    `<option value="">Sem professor</option>` +
    teachers
      .slice()
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
      .map((t) => `<option value="${escapeHtml(String(t.id))}">${escapeHtml(String(t.nome || "Professor"))}</option>`)
      .join("");

  const groupOptions =
    `<option value="">Sem turma</option>` +
    groups
      .slice()
      .sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""), "pt-BR"))
      .map((g) => `<option value="${escapeHtml(String(g.id))}">${escapeHtml(String(g.name || "Turma"))}</option>`)
      .join("");

  const currentTeacher = String(student?.professorId || student?.teacherId || "").trim();
  const currentGroup = String(student?.groupId || "").trim();

  openModal({
    title: "Vincular aluno",
    primaryLabel: "Salvar",
    secondaryLabel: "Cancelar",
    bodyHtml: `
      <div class="admin-ped-modal" data-admin-ped-link-form>
        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Professor responsável</span>
            <select class="admin-ped-modal-select" data-admin-ped-link-field="teacherId">${teacherOptions}</select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Turma</span>
            <select class="admin-ped-modal-select" data-admin-ped-link-field="groupId">${groupOptions}</select>
          </label>
        </div>
        <div class="admin-ped-modal-error" data-admin-ped-link-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const form = modalBody?.querySelector("[data-admin-ped-link-form]");
      const errEl = form?.querySelector("[data-admin-ped-link-error]");
      const setErr = (msg) => {
        if (errEl instanceof HTMLElement) {
          errEl.textContent = String(msg || "");
          errEl.hidden = !msg;
        }
      };
      setErr("");
      const read = (key) => {
        const el = form?.querySelector(`[data-admin-ped-link-field="${CSS.escape(String(key))}"]`);
        if (el instanceof HTMLSelectElement) return String(el.value || "").trim();
        return "";
      };
      const teacherId = read("teacherId");
      const groupId = read("groupId");
      const group = groupId && adminPedagogicoState.groupsById instanceof Map ? adminPedagogicoState.groupsById.get(groupId) || null : null;
      const patch = {
        professorId: teacherId || "",
        teacherId: teacherId || "",
        groupId: groupId || "",
        groupName: group ? String(group.name || "").trim() : "",
        atualizadoEm: undefined,
      };

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Salvando…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_student_link");
          await patchFirestoreUserDocument({
            userId: alunoId,
            context: "admin_student_link_merge",
            patch: { ...patch, atualizadoEm: firebase.serverTimestamp() },
          });
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] student link failed:", e);
          setErr("Não foi possível salvar agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || "Salvar";
        }
      })();
      return false;
    },
    onSecondary: () => true,
  });

  window.setTimeout(() => {
    const form = modalBody?.querySelector("[data-admin-ped-link-form]");
    if (!(form instanceof HTMLElement)) return;
    const t = form.querySelector('[data-admin-ped-link-field="teacherId"]');
    const g = form.querySelector('[data-admin-ped-link-field="groupId"]');
    if (t instanceof HTMLSelectElement) t.value = currentTeacher;
    if (g instanceof HTMLSelectElement) g.value = currentGroup;
  }, 0);
};

const openAdminPedQuickLinkModal = () => {
  const students = Array.isArray(adminPedagogicoState.students) ? adminPedagogicoState.students : [];
  const activeStudents = students.filter((s) => s && typeof s === "object" && s.ativo);
  if (!activeStudents.length) return;

  const options =
    `<option value="">Selecione...</option>` +
    activeStudents
      .slice()
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
      .map((s) => {
        const label = `${String(s.nome || "Aluno").trim()}${s.email ? ` · ${String(s.email).trim()}` : ""}`;
        return `<option value="${escapeHtml(String(s.id || ""))}">${escapeHtml(label)}</option>`;
      })
      .join("");

  openModal({
    title: "Vincular aluno a professor/turma",
    primaryLabel: "Continuar",
    secondaryLabel: "Cancelar",
    bodyHtml: `
      <div class="modal-form">
        <label class="modal-field">
          <span>Aluno</span>
          <select class="modal-input" data-admin-ped-quick-link-student>${options}</select>
        </label>
        <div class="modal-inline-error" data-admin-ped-quick-link-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const sel = modalBody?.querySelector("[data-admin-ped-quick-link-student]");
      const errEl = modalBody?.querySelector("[data-admin-ped-quick-link-error]");
      const setErr = (msg) => {
        if (!(errEl instanceof HTMLElement)) return;
        errEl.textContent = String(msg || "");
        errEl.hidden = !msg;
      };
      setErr("");
      const alunoId = sel instanceof HTMLSelectElement ? String(sel.value || "").trim() : "";
      if (!alunoId) {
        setErr("Selecione um aluno para continuar.");
        return false;
      }
      closeModal();
      openAdminPedStudentLinkModal({ studentId: alunoId });
      return false;
    },
    onSecondary: () => true,
  });
};

const openAdminPedFeedbackModal = ({ mode = "create", feedbackRow = null } = {}) => {
  const isEdit = false;
  const teachers = Array.isArray(adminPedagogicoState.teachers) ? adminPedagogicoState.teachers : [];
  const teacherOptions =
    `<option value="">Selecione...</option>` +
    teachers
      .slice()
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"))
      .map((t) => `<option value="${escapeHtml(String(t.id))}">${escapeHtml(String(t.nome || "Professor"))}</option>`)
      .join("");

  const scoreField = (key, label) => `
    <label class="admin-ped-modal-field">
      <span>${escapeHtml(label)} (0–10)</span>
      <input class="admin-ped-modal-input" type="number" inputmode="numeric" min="0" max="10" step="1" data-admin-ped-feedback-field="${escapeHtml(
        key
      )}" />
    </label>
  `;

  openModal({
    title: "Enviar feedback pedagógico",
    primaryLabel: "Enviar",
    secondaryLabel: "Cancelar",
    bodyHtml: `
      <div class="admin-ped-modal" data-admin-ped-feedback-form>
        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Professor avaliado</span>
            <select class="admin-ped-modal-select" data-admin-ped-feedback-field="teacherId">${teacherOptions}</select>
          </label>
          <label class="admin-ped-modal-field">
            <span>Data da observação</span>
            <input class="admin-ped-modal-input" type="date" data-admin-ped-feedback-field="observationDate" />
          </label>
        </div>

        <div class="admin-ped-modal-row">
          <label class="admin-ped-modal-field">
            <span>Tipo de aula</span>
            <select class="admin-ped-modal-select" data-admin-ped-feedback-field="classType">
              <option value="individual">Individual</option>
              <option value="group">Grupo</option>
            </select>
          </label>
          ${scoreField("generalScore", "Nota geral")}
        </div>

        <div class="admin-ped-modal-row">
          ${scoreField("clarityScore", "Clareza")}
          ${scoreField("didacticsScore", "Didática")}
        </div>
        <div class="admin-ped-modal-row">
          ${scoreField("correctionScore", "Correção do aluno")}
          ${scoreField("timeManagementScore", "Gestão do tempo")}
        </div>
        <div class="admin-ped-modal-row">
          ${scoreField("personalizationScore", "Personalização")}
          ${scoreField("energyScore", "Energia e condução")}
        </div>
        <div class="admin-ped-modal-row">
          ${scoreField("materialUsageScore", "Uso do material")}
          ${scoreField("engagementScore", "Engajamento")}
        </div>

        <label class="admin-ped-modal-field">
          <span>Pontos fortes</span>
          <textarea class="admin-ped-modal-textarea" rows="2" data-admin-ped-feedback-field="strengths" placeholder="O que funcionou bem?"></textarea>
        </label>
        <label class="admin-ped-modal-field">
          <span>Pontos de melhoria</span>
          <textarea class="admin-ped-modal-textarea" rows="2" data-admin-ped-feedback-field="improvements" placeholder="O que melhorar?"></textarea>
        </label>
        <label class="admin-ped-modal-field">
          <span>Plano de ação recomendado</span>
          <textarea class="admin-ped-modal-textarea" rows="2" data-admin-ped-feedback-field="actionPlan" placeholder="Próximos passos claros"></textarea>
        </label>
        <label class="admin-ped-modal-field">
          <span>Observação livre</span>
          <textarea class="admin-ped-modal-textarea" rows="2" data-admin-ped-feedback-field="freeNotes" placeholder="Opcional"></textarea>
        </label>

        <div class="admin-ped-modal-error" data-admin-ped-feedback-error hidden>—</div>
      </div>
    `,
    onPrimary: () => {
      const form = modalBody?.querySelector("[data-admin-ped-feedback-form]");
      if (!(form instanceof HTMLElement)) return false;
      const errEl = form.querySelector("[data-admin-ped-feedback-error]");
      const setErr = (msg) => {
        if (errEl instanceof HTMLElement) {
          errEl.textContent = String(msg || "");
          errEl.hidden = !msg;
        }
      };
      const read = (key) => {
        const el = form.querySelector(`[data-admin-ped-feedback-field="${CSS.escape(String(key))}"]`);
        if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || el instanceof HTMLSelectElement) return String(el.value || "").trim();
        return "";
      };
      const teacherId = read("teacherId");
      const observationDate = read("observationDate");
      const classType = normalizeClassType(read("classType"));
      const generalScore = Number(read("generalScore"));

      const numeric = (k) => {
        const raw = read(k);
        if (!raw) return null;
        const n = Number(raw);
        return Number.isFinite(n) ? clampInt(n, 0, 10, null) : null;
      };

      setErr("");
      if (!teacherId) {
        setErr("Selecione um professor.");
        return false;
      }
      if (!observationDate) {
        setErr("Selecione a data da observação.");
        return false;
      }
      if (!Number.isFinite(generalScore) || generalScore < 0 || generalScore > 10) {
        setErr("Informe a nota geral (0 a 10).");
        return false;
      }

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Enviando…";

      (async () => {
        try {
          const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_feedback_send");
          const user = await waitForFirebaseAuthReady(firebase, 5000);
          if (!user) throw new Error("not_authenticated");
          const teacherName = String(adminPedagogicoState.teachersById?.get(teacherId)?.nome || "").trim();
          const id = `fb_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
          const docRef = firebase.doc(firebase.primaryDb, "pedagogicalFeedbacks", id);
          const payload = {
            id,
            teacherId,
            teacherName,
            observationDate,
            classType,
            generalScore: clampInt(generalScore, 0, 10, 0),
            clarityScore: numeric("clarityScore"),
            didacticsScore: numeric("didacticsScore"),
            correctionScore: numeric("correctionScore"),
            timeManagementScore: numeric("timeManagementScore"),
            personalizationScore: numeric("personalizationScore"),
            energyScore: numeric("energyScore"),
            materialUsageScore: numeric("materialUsageScore"),
            engagementScore: numeric("engagementScore"),
            strengths: read("strengths"),
            improvements: read("improvements"),
            actionPlan: read("actionPlan"),
            freeNotes: read("freeNotes"),
            createdBy: String(user.uid || ""),
            createdAt: firebase.serverTimestamp(),
            readByTeacher: false,
            readAt: null,
          };
          await withTimeout(firebase.setDoc(docRef, payload, { merge: true }), 12_000, "firestore_admin_feedback_merge");
          closeModal();
          await renderAdminControlePedagogicoPanel({ force: true });
        } catch (e) {
          console.error("[admin] feedback send failed:", e);
          setErr("Não foi possível enviar agora.");
        } finally {
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
          if (modalPrimary) modalPrimary.textContent = prev || "Enviar";
        }
      })();
      return false;
    },
    onSecondary: () => true,
  });

  window.setTimeout(() => {
    const form = modalBody?.querySelector("[data-admin-ped-feedback-form]");
    if (!(form instanceof HTMLElement)) return;
    const dateEl = form.querySelector('[data-admin-ped-feedback-field="observationDate"]');
    if (dateEl instanceof HTMLInputElement) dateEl.value = createDateKey(new Date());
  }, 0);
};

const openAdminPedFeedbackViewModal = ({ feedbackId } = {}) => {
  const id = String(feedbackId || "").trim();
  if (!id) return;
  const row =
    (Array.isArray(adminPedagogicoState.pedagogicalFeedbacks) ? adminPedagogicoState.pedagogicalFeedbacks : []).find((f) => String(f?.id || "") === id) ||
    null;
  if (!row) return;
  const p = row.payload && typeof row.payload === "object" ? row.payload : {};
  const lines = [
    ["Professor", row.teacherName || row.teacherId || "—"],
    ["Data", row.observationDate || "—"],
    ["Tipo", row.classType === "group" ? "Grupo" : "Individual"],
    ["Nota geral", Number.isFinite(Number(row.generalScore)) ? String(row.generalScore) : "—"],
    ["Pontos fortes", String(row.strengths || "").trim() || "—"],
    ["Pontos de melhoria", String(row.improvements || "").trim() || "—"],
    ["Plano de ação", String(row.actionPlan || "").trim() || "—"],
    ["Observação livre", String(row.freeNotes || "").trim() || "—"],
  ];
  const scoreFields = [
    ["Clareza", p.clarityScore],
    ["Didática", p.didacticsScore],
    ["Correção", p.correctionScore],
    ["Gestão do tempo", p.timeManagementScore],
    ["Personalização", p.personalizationScore],
    ["Energia", p.energyScore],
    ["Uso do material", p.materialUsageScore],
    ["Engajamento", p.engagementScore],
  ];
  const scoreHtml = scoreFields
    .map(([label, val]) => `<li class="admin-ped-overview-item"><span>${escapeHtml(label)}</span><strong>${escapeHtml(Number.isFinite(Number(val)) ? String(val) : "—")}</strong></li>`)
    .join("");
  const mainHtml = lines
    .map(([label, val]) => `<li class="admin-ped-overview-item"><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(val || "—"))}</strong></li>`)
    .join("");

  openModal({
    title: "Feedback pedagógico",
    primaryLabel: "Fechar",
    secondaryLabel: "Fechar",
    hideSecondary: true,
    bodyHtml: `
      <div class="admin-ped-overview">
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Resumo</div>
          <ul class="admin-ped-overview-list">${mainHtml}</ul>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Notas detalhadas</div>
          <ul class="admin-ped-overview-list">${scoreHtml}</ul>
        </div>
      </div>
    `,
    onPrimary: () => true,
  });
};

const openTeacherPedFeedbackModal = ({ feedbackId } = {}) => {
  const id = String(feedbackId || "").trim();
  if (!id) return;
  const row = (Array.isArray(teacherV4DashboardState.feedbacks) ? teacherV4DashboardState.feedbacks : []).find((f) => String(f?.id || "") === id) || null;
  if (!row) return;

  const p = row.payload && typeof row.payload === "object" ? row.payload : {};
  const scoreFields = [
    ["Clareza", p.clarityScore],
    ["Didática", p.didacticsScore],
    ["Correção", p.correctionScore],
    ["Gestão do tempo", p.timeManagementScore],
    ["Personalização", p.personalizationScore],
    ["Energia", p.energyScore],
    ["Uso do material", p.materialUsageScore],
    ["Engajamento", p.engagementScore],
  ];
  const scoreHtml = scoreFields
    .map(
      ([label, val]) =>
        `<li class="admin-ped-overview-item"><span>${escapeHtml(label)}</span><strong>${escapeHtml(Number.isFinite(Number(val)) ? String(val) : "—")}</strong></li>`
    )
    .join("");

  const summaryHtml = [
    ["Data", row.observationDate || "—"],
    ["Tipo", row.classType === "group" ? "Grupo" : "Individual"],
    ["Nota geral", Number.isFinite(Number(row.generalScore)) ? String(row.generalScore) : "—"],
  ]
    .map(([label, val]) => `<li class="admin-ped-overview-item"><span>${escapeHtml(label)}</span><strong>${escapeHtml(String(val || "—"))}</strong></li>`)
    .join("");

  const markRead = async () => {
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_teacher_feedback_read");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) throw new Error("not_authenticated");
    await withTimeout(
      firebase.setDoc(
        firebase.doc(firebase.primaryDb, "pedagogicalFeedbacks", id),
        { readByTeacher: true, readAt: firebase.serverTimestamp(), updatedAt: firebase.serverTimestamp() },
        { merge: true }
      ),
      12_000,
      "firestore_teacher_feedback_read_merge"
    );
  };

  openModal({
    title: "Feedback pedagógico",
    primaryLabel: row.readByTeacher ? "Fechar" : "Marcar como lido",
    secondaryLabel: "Fechar",
    hideSecondary: row.readByTeacher,
    bodyHtml: `
      <div class="admin-ped-overview">
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Resumo</div>
          <ul class="admin-ped-overview-list">${summaryHtml}</ul>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Pontos fortes</div>
          <div class="admin-student-panel-note">${escapeHtml(String(row.strengths || "").trim() || "—")}</div>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Pontos de melhoria</div>
          <div class="admin-student-panel-note">${escapeHtml(String(row.improvements || "").trim() || "—")}</div>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Plano de ação</div>
          <div class="admin-student-panel-note">${escapeHtml(String(row.actionPlan || "").trim() || "—")}</div>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Observação livre</div>
          <div class="admin-student-panel-note">${escapeHtml(String(row.freeNotes || "").trim() || "—")}</div>
        </div>
        <div class="admin-ped-overview-card">
          <div class="admin-ped-overview-title">Notas detalhadas</div>
          <ul class="admin-ped-overview-list">${scoreHtml}</ul>
        </div>
      </div>
    `,
    onPrimary: () => {
      if (row.readByTeacher) return true;
      if (modalPrimary) modalPrimary.disabled = true;
      const prev = modalPrimary?.textContent || "";
      if (modalPrimary) modalPrimary.textContent = "Salvando…";
      (async () => {
        try {
          await markRead();
          closeModal();
          teacherV4DashboardState.loadedAt = 0;
          renderTeacherDashboard();
        } catch (e) {
          console.error("[teacher] feedback mark read failed:", e);
          if (modalPrimary) modalPrimary.textContent = prev || "Marcar como lido";
          if (modalPrimary) modalPrimary.disabled = false;
        }
      })();
      return false;
    },
    onSecondary: () => true,
  });
};

