const getAdminStudentMetaById = (alunoId) => {
  const id = String(alunoId || "").trim();
  if (!id) return null;
  const map = adminStudentsState.studentsById instanceof Map ? adminStudentsState.studentsById : new Map();
  if (map.has(id)) return map.get(id) || null;
  const aliasMap = adminStudentsState.studentAliasToDocId instanceof Map ? adminStudentsState.studentAliasToDocId : new Map();
  const canonicalId = String(aliasMap.get(id) || "").trim();
  return canonicalId ? map.get(canonicalId) || null : null;
};

const getAdminRetentionDecisionByStudentId = (alunoId) => {
  const id = String(alunoId || "").trim();
  if (!id) return null;
  const queues = adminPedagogicoState.retention?.queues;
  const decisions = Array.isArray(queues?.decisoes) ? queues.decisoes : [];
  return decisions.find((row) => String(row?.alunoId || "").trim() === id) || null;
};

const getAdminStudentRecurringGroupIds = (alunoId) => {
  const id = String(alunoId || "").trim();
  if (!id) return [];
  const groupIds = new Set();
  const classes = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  classes.forEach((classRow) => {
    if (!classRow || typeof classRow !== "object") return;
    const studentIds = Array.isArray(classRow.studentIds) ? classRow.studentIds.map((studentId) => String(studentId || "").trim()).filter(Boolean) : [];
    if (!studentIds.includes(id)) return;
    const linkedGroupId = String(classRow.linkedEventGroupId || classRow.grupoRecorrenciaId || "").trim();
    if (linkedGroupId) groupIds.add(linkedGroupId);
    const linkedEventIds = Array.isArray(classRow.linkedEventIds) ? classRow.linkedEventIds : [];
    linkedEventIds.forEach((eventId) => {
      const evt = Array.isArray(adminStudentsState.events) ? adminStudentsState.events.find((row) => String(row?.id || "") === String(eventId || "")) : null;
      const evtGroupId = String(evt?.grupoRecorrenciaId || "").trim();
      if (evtGroupId) groupIds.add(evtGroupId);
    });
  });

  const events = Array.isArray(adminStudentsState.events) ? adminStudentsState.events : [];
  events.forEach((evt) => {
    if (!evt || typeof evt !== "object") return;
    if (String(evt.alunoId || "").trim() !== id) return;
    const groupId = String(evt.grupoRecorrenciaId || "").trim();
    if (groupId) groupIds.add(groupId);
  });

  return [...groupIds];
};

const findAdminStudentRecurringEventId = (alunoId, groupId) => {
  const id = String(alunoId || "").trim();
  const gid = String(groupId || "").trim();
  if (!id || !gid) return "";
  const classes = Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : [];
  for (const classRow of classes) {
    if (!classRow || typeof classRow !== "object") continue;
    const studentIds = Array.isArray(classRow.studentIds) ? classRow.studentIds.map((studentId) => String(studentId || "").trim()).filter(Boolean) : [];
    if (!studentIds.includes(id)) continue;
    const linkedGroupId = String(classRow.linkedEventGroupId || classRow.grupoRecorrenciaId || "").trim();
    if (linkedGroupId !== gid) continue;
    const linkedEventIds = Array.isArray(classRow.linkedEventIds) ? classRow.linkedEventIds.map((eventId) => String(eventId || "").trim()).filter(Boolean) : [];
    if (linkedEventIds.length) return linkedEventIds[0];
  }
  const events = Array.isArray(adminStudentsState.events) ? adminStudentsState.events : [];
  const match = events.find((evt) => String(evt.alunoId || "").trim() === id && String(evt.grupoRecorrenciaId || "").trim() === gid);
  return match ? String(match.id || "").trim() : "";
};

const rerenderAdminStudentLifecycleViews = () => {
  if (adminStudentsState.history?.isOpen) renderAdminStudentSheet();
  if (typeof renderAdminPedagogicoStudentsPanel === "function") renderAdminPedagogicoStudentsPanel();
  if (typeof refreshAdminPedagogicoRetentionState === "function") refreshAdminPedagogicoRetentionState({ force: true }).catch(() => {});
  if (typeof renderAdminStudentsList === "function") renderAdminStudentsList();
};

const requestAdminStudentMirrorSync = ({ firestoreDocId, context = "student_mirror_sync" } = {}) => {
  const id = String(firestoreDocId || "").trim();
  if (!id) return Promise.resolve(null);
  return fetchWithAuth("/api/admin-users", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ uid: id, action: "sync_mirror" }),
  })
    .then((response) =>
      response
        .json()
        .catch(() => null)
        .then((body) => ({ ok: response.ok, status: response.status, body }))
    )
    .then((result) => {
      const sync = result?.body?.sync || null;
      const payload = {
        documentId: id,
        context,
        status: result?.status,
        sync,
        error: result?.body?.error || "",
      };
      if (!result?.ok || result?.body?.ok === false) console.warn("[ownership] student mirror sync incomplete", payload);
      else console.info("[ownership] student mirror sync complete", payload);
      return sync || result?.body || null;
    })
    .catch((syncError) => {
      console.error("[ownership] student mirror sync failed", {
        documentId: id,
        context,
        message: syncError?.message || String(syncError || ""),
      });
      return null;
    });
};

const getAdminStudentLifecycleClassRows = (alunoId) => {
  const id = String(alunoId || "").trim();
  if (!id) return [];
  return (Array.isArray(adminPedagogicoState.classes) ? adminPedagogicoState.classes : []).filter((classRow) => {
    const studentIds = Array.isArray(classRow?.studentIds) ? classRow.studentIds.map((studentId) => String(studentId || "").trim()) : [];
    return studentIds.includes(id);
  });
};

const getAdminStudentLifecycleEventGroupIds = (alunoId) => {
  const groupIds = new Set(getAdminStudentRecurringGroupIds(alunoId));
  getAdminStudentLifecycleClassRows(alunoId).forEach((classRow) => {
    const groupId = String(classRow?.linkedEventGroupId || classRow?.grupoRecorrenciaId || "").trim();
    if (groupId) groupIds.add(groupId);
  });
  return [...groupIds].filter(Boolean);
};

const isHiddenAdminLifecycleEventStatus = (status) => {
  const raw = String(status || "").trim().toLowerCase();
  return raw === "cancelada" || raw === "cancelado" || raw === "cancelled" || raw === "canceled" || raw === "deleted";
};

const queueAdminStudentLifecycleCascade = async ({ firebase, batch, alunoId, active, nowIso } = {}) => {
  const id = String(alunoId || "").trim();
  if (!id || !firebase || !batch) return { classes: 0, events: 0 };
  const nextClassStatus = active ? "active" : "paused";
  const nextEventStatus = active ? "agendada" : "cancelada";
  const todayKey = createDateKey(new Date());
  let classesCount = 0;
  let eventsCount = 0;
  const classIds = [];
  const eventIds = [];

  getAdminStudentLifecycleClassRows(id).forEach((classRow) => {
    const classId = String(classRow?.id || "").trim();
    if (!classId) return;
    batch.set(
      firebase.doc(firebase.primaryDb, "classes", classId),
      {
        status: nextClassStatus,
        lifecycleCascadeStatus: active ? "reactivated" : "effective_cancelled",
        lifecycleCascadeAt: nowIso,
        updatedAt: firebase.serverTimestamp(),
      },
      { merge: true }
    );
    classesCount += 1;
    classIds.push(classId);
  });

  const groupIds = new Set(getAdminStudentLifecycleEventGroupIds(id));
  const eventsSnap = await withTimeout(firebase.getDocs(firebase.collection(firebase.primaryDb, "aulas")), 12_000, "firestore_lifecycle_aulas_list");
  eventsSnap.forEach((docSnap) => {
    const data = docSnap.data ? docSnap.data() : {};
    const alunoIdRaw = String(data?.alunoId || "").trim();
    const groupId = String(data?.grupoRecorrenciaId || "").trim();
    const dateKey = String(data?.dateKey || "").trim();
    if (alunoIdRaw !== id) return;
    if (groupIds.size && groupId && !groupIds.has(groupId)) return;
    if (!isValidDateKey(dateKey) || dateKey < todayKey) return;
    batch.set(
      firebase.doc(firebase.primaryDb, "aulas", docSnap.id),
      {
        status: nextEventStatus,
        lifecycleCascadeStatus: active ? "reactivated" : "effective_cancelled",
        lifecycleCascadeAt: nowIso,
        updatedAt: firebase.serverTimestamp(),
      },
      { merge: true }
    );
    eventsCount += 1;
    eventIds.push(docSnap.id);
  });

  return { classes: classesCount, events: eventsCount, classIds, eventIds, active: Boolean(active), eventStatus: nextEventStatus, classStatus: nextClassStatus };
};

const applyAdminStudentLifecycleCascadeToCache = (summary) => {
  if (!summary || typeof summary !== "object") return;
  const classIds = new Set((Array.isArray(summary.classIds) ? summary.classIds : []).map((id) => String(id || "").trim()).filter(Boolean));
  const eventIds = new Set((Array.isArray(summary.eventIds) ? summary.eventIds : []).map((id) => String(id || "").trim()).filter(Boolean));
  const classStatus = String(summary.classStatus || "").trim();
  const eventStatus = String(summary.eventStatus || "").trim();
  if (classIds.size && Array.isArray(adminPedagogicoState.classes)) {
    adminPedagogicoState.classes = adminPedagogicoState.classes.map((row) => (classIds.has(String(row?.id || "")) ? { ...row, status: classStatus } : row));
  }
  if (eventIds.size) {
    const patchEvents = (rows) =>
      Array.isArray(rows) ? rows.map((row) => (eventIds.has(String(row?.id || "")) ? { ...row, status: eventStatus } : row)).filter((row) => !isHiddenAdminLifecycleEventStatus(row?.status)) : rows;
    adminPedagogicoState.scheduleEvents = patchEvents(adminPedagogicoState.scheduleEvents) || [];
    adminStudentsState.events = patchEvents(adminStudentsState.events) || [];
  }
};

const saveAdminStudentLifecyclePatch = async ({ alunoId, patch = {}, cascade = null } = {}) => {
  const requestedId = String(alunoId || "").trim();
  if (!requestedId) throw new Error("missing_student_id");
  const student = getAdminStudentMetaById(requestedId);
  const aliasMap = adminStudentsState.studentAliasToDocId instanceof Map ? adminStudentsState.studentAliasToDocId : new Map();
  const id = resolveStudentCanonicalDocId(student || requestedId, { aliasMap });
  const cleanPatch = sanitizeFirestorePatch(patch || {});
  let etapa = "A";
  try {
    console.info("[Cancellation] A — firestoreDocId resolvido", {
      selectedStudent: student
        ? {
            id: student?.id,
            docId: student?.docId,
            firestoreDocId: student?.firestoreDocId,
            uid: student?.uid,
            userId: student?.userId,
            studentId: student?.studentId,
            alunoId: student?.alunoId,
            nome: student?.nome,
            email: student?.email,
          }
        : null,
      studentId: requestedId,
      studentDocId: id,
      resolvedDocumentId: id,
      collection: "users",
      database: "primaryDb",
      documentPath: `users/${id}`,
      payload: cleanPatch,
    });
    etapa = "B";
    const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_student_lifecycle_patch");
    const user = await waitForFirebaseAuthReady(firebase, 5000);
    if (!user) throw new Error("not_authenticated");
    if (typeof firebase.updateDoc !== "function") {
      const error = new Error("firebase_updateDoc_unavailable");
      error.code = "missing_updateDoc";
      throw error;
    }
    if (cascade && typeof firebase.writeBatch !== "function") {
      const error = new Error("firebase_writeBatch_unavailable");
      error.code = "missing_writeBatch";
      throw error;
    }
    const studentRef = firebase.doc(firebase.primaryDb, "users", id);
    const beforeSnapshot = await withTimeout(firebase.getDoc(studentRef), 12_000, "firestore_student_lifecycle_before");
    if (!beforeSnapshot?.exists?.()) {
      throw new Error(`canonical_student_document_not_found: users/${id}`);
    }
    console.info("[Cancellation] B — documento users/%s encontrado", id);
    etapa = "C";
    const beforeData = beforeSnapshot.data ? beforeSnapshot.data() : {};
    const beforeEmail = String(beforeData?.email || "").trim().toLowerCase();
    const selectedEmail = String(student?.email || "").trim().toLowerCase();
    const beforeUid = String(beforeData?.uid || beforeData?.userId || "").trim();
    const selectedUid = String(student?.uid || student?.userId || "").trim();
    if (selectedEmail && beforeEmail && selectedEmail !== beforeEmail && (!beforeUid || !selectedUid || beforeUid !== selectedUid)) {
      throw new Error("student_identity_mismatch_before_write");
    }
    console.info("[Cancellation] C — identidade validada", {
      documentId: id,
      beforeEmail,
      selectedEmail,
      beforeUid,
      selectedUid,
    });
    etapa = "D";
    let cascadeSummary = null;
    if (typeof cascade === "function") {
      const batch = firebase.writeBatch(firebase.primaryDb);
      batch.update(studentRef, cleanPatch);
      cascadeSummary = await cascade({ firebase, batch, studentRef, studentId: id, beforeData });
      await withTimeout(batch.commit(), 16_000, "firestore_student_lifecycle_batch_commit");
      applyAdminStudentLifecycleCascadeToCache(cascadeSummary);
    } else {
      await withTimeout(firebase.updateDoc(studentRef, cleanPatch), 12_000, "firestore_student_lifecycle_update");
    }
    console.info("[Cancellation] D — updateDoc concluído", { documentId: id, documentPath: `users/${id}`, cascade: cascadeSummary });
    etapa = "E";
    const persistedRow = await loadAdminStudentRowFromFirestoreById(id);
    if (!persistedRow) {
      throw new Error("student_reload_after_lifecycle_patch_failed");
    }
    console.info("[Cancellation] E — documento relido", {
      studentId: id,
      cancelamento: persistedRow.cancelamento || null,
      tipo: persistedRow.tipo || "",
    });
    etapa = "F";
    if (Object.prototype.hasOwnProperty.call(cleanPatch, "cancelamento")) {
      const expectedCancellation = cleanPatch.cancelamento;
      const persistedCancellation = normalizeStudentCancellationRecord(persistedRow.cancelamento);
      if (expectedCancellation && typeof expectedCancellation === "object" && !persistedCancellation) {
        throw new Error("cancelamento_not_persisted");
      }
      if (expectedCancellation == null && persistedCancellation != null) {
        throw new Error("cancelamento_not_cleared");
      }
      if (persistedCancellation) {
        const persistedOrigin = String(persistedCancellation.origem || "").trim();
        const hasPedidoDate = Boolean(persistedCancellation.dataPedido);
        const hasEndDate = Boolean(persistedCancellation.dataFimAviso || persistedCancellation.dataFimPrevista);
        const isEffective = Boolean(persistedCancellation?.desfecho || persistedCancellation?.dataEfetivacao);
        if (!hasPedidoDate || (persistedOrigin === "pedido" && !hasEndDate && !isEffective)) {
          throw new Error("cancelamento_persisted_invalid_shape");
        }
      }
    }
    console.info("[Cancellation] F — cancelamento confirmado no documento", {
      documentId: id,
      hasCancelamento: Boolean(persistedRow?.cancelamento),
    });
    const selectedNome = String(student?.nome || "").trim();
    const selectedEmailAfter = String(student?.email || "").trim().toLowerCase();
    const selectedUidAfter = String(student?.uid || student?.userId || "").trim();
    const persistedNome = String(persistedRow?.nome || "").trim();
    const persistedEmail = String(persistedRow?.email || "").trim().toLowerCase();
    const persistedUid = String(persistedRow?.uid || persistedRow?.userId || "").trim();
    const persistedDocId = String(persistedRow?.firestoreDocId || persistedRow?.docId || persistedRow?.documentId || persistedRow?.id || "").trim();
    console.log("[Cancellation integrity comparison]", {
      canonicalDocumentId: id,
      before: {
        nome: selectedNome,
        email: selectedEmailAfter,
        uid: selectedUidAfter,
      },
      after: {
        nome: persistedNome,
        email: persistedEmail,
        uid: persistedUid,
        firestoreDocId: persistedDocId,
      },
    });
    const sameDocId = persistedDocId === id;
    const emailMismatch = selectedEmailAfter && persistedEmail && selectedEmailAfter !== persistedEmail;
    const uidMismatch = selectedUidAfter && persistedUid && selectedUidAfter !== persistedUid;
    if (!sameDocId || (emailMismatch && uidMismatch)) {
      throw new Error("student_integrity_after_write_failed");
    }
    etapa = "G";
    if (student && typeof student === "object") {
      const mergedPersistedRow = mergeAdminStudentWithCachedProfile(student, persistedRow);
      updateAdminStudentCachedRow(id, mergedPersistedRow);
      requestAdminStudentMirrorSync({ firestoreDocId: id, context: "student_lifecycle_patch" });
      console.info("[Cancellation] G — cache atualizado", { documentId: id });
      return mergedPersistedRow;
    }
    await ensureAdminStudentsBaseData({ force: true });
    const refreshedStudent = getAdminStudentMetaById(id);
    if (refreshedStudent) {
      requestAdminStudentMirrorSync({ firestoreDocId: id, context: "student_lifecycle_patch" });
      console.info("[Cancellation] G — cache recarregado", { documentId: id, mode: "base_reload" });
      return refreshedStudent;
    }
    requestAdminStudentMirrorSync({ firestoreDocId: id, context: "student_lifecycle_patch" });
    console.info("[Cancellation] G — cache atualizado", { documentId: id });
    return persistedRow;
  } catch (error) {
    console.error("[Cancellation] Erro", {
      etapa,
      code: error?.code,
      message: error?.message,
      documentId: id,
      documentPath: `users/${id}`,
      stack: error?.stack,
    });
    error.cancellationStage = etapa;
    throw error;
  }
};

const archiveStudentCancellationRecord = ({ alunoMeta, record } = {}) => {
  const previous = Array.isArray(alunoMeta?.cancelamentosAnteriores) ? alunoMeta.cancelamentosAnteriores : [];
  return previous.concat([clonePlainData(record)].filter(Boolean));
};

const loadAdminStudentLifecycleSensors = async ({ alunoId, force = false } = {}) => {
  const history = adminStudentsState.history;
  if (!history?.isOpen) return;
  const id = String(alunoId || history.alunoId || "").trim();
  if (!id) return;
  const aluno = getAdminStudentMetaById(id);
  const cancelamento = normalizeStudentCancellationRecord(aluno?.cancelamento);
  const range = getStudentCancellationWindowRange(cancelamento);
  if (!range) {
    adminStudentsState.history.lifecycleSensors = {
      loading: false,
      payment: null,
      attendance: null,
      paymentError: "",
      attendanceError: "",
    };
    renderAdminStudentSheet();
    return;
  }

  if (!force && history.lifecycleSensors?.loadedAt && Date.now() - history.lifecycleSensors.loadedAt < 30_000) return;
  adminStudentsState.history.lifecycleSensors = {
    ...(history.lifecycleSensors && typeof history.lifecycleSensors === "object" ? history.lifecycleSensors : {}),
    loading: true,
    paymentError: "",
    attendanceError: "",
  };
  renderAdminStudentSheet();

  const paymentTask = (async () => {
    await ensureFinanceLoaded({ force: false });
    return deriveSensorPagamento(aluno, range.fromKey, range.toKey, {
      charges: financeState.cobrancas,
      financeStudents: financeState.alunos,
    });
  })();

  const attendanceTask = Promise.resolve(
    deriveSensorFrequencia(aluno, range.fromKey, range.toKey, {
      logs: adminStudentsState.logs,
      events: adminStudentsState.events,
      classes: adminPedagogicoState.classes,
    })
  );

  const [paymentRes, attendanceRes] = await Promise.allSettled([paymentTask, attendanceTask]);
  if (!adminStudentsState.history?.isOpen || String(adminStudentsState.history?.alunoId || "") !== id) return;
  adminStudentsState.history.lifecycleSensors = {
    loading: false,
    loadedAt: Date.now(),
    payment: paymentRes.status === "fulfilled" ? paymentRes.value : { estado: "erro", detalhe: "—" },
    attendance: attendanceRes.status === "fulfilled" ? attendanceRes.value : { estado: "erro", detalhe: "—" },
    paymentError: paymentRes.status === "rejected" ? String(paymentRes.reason?.message || paymentRes.reason || "payment_sensor_failed") : "",
    attendanceError: attendanceRes.status === "rejected" ? String(attendanceRes.reason?.message || attendanceRes.reason || "attendance_sensor_failed") : "",
  };
  if (paymentRes.status === "rejected") console.error("[admin] lifecycle payment sensor failed:", paymentRes.reason);
  if (attendanceRes.status === "rejected") console.error("[admin] lifecycle attendance sensor failed:", attendanceRes.reason);
  renderAdminStudentSheet();
};

const patchAdminStudentStatus = async ({ alunoId, ativo } = {}) => {
  const id = String(alunoId || "").trim();
  if (!id) return;
  const firebase = await withTimeout(loadFirebaseAdminApi(), 8000, "firebase_init_admin_student_status");
  const patch = {
    ativo: Boolean(ativo),
    atualizadoEm: firebase.serverTimestamp(),
  };
  if (ativo) {
    patch.canceladoEm = null;
    patch.desativadoEm = null;
  } else {
    const now = firebase.serverTimestamp();
    patch.canceladoEm = now;
    patch.desativadoEm = now;
    patch.professorId = null;
    patch.teacherId = null;
  }
  await patchFirestoreUserDocument({
    userId: id,
    context: "student_status_patch",
    patch,
  });
  updateAdminStudentCachedRow(id, patch);
};

const openAdminStudentRegisterCancellationModal = ({ alunoId } = {}) => {
  const id = String(alunoId || "").trim();
  if (!id) return;
  const firstLessonDate = getAdminStudentFirstLessonDate(id);
  const firstLessonValue = firstLessonDate ? createDateKey(firstLessonDate) : "";

  openModal({
    title: "Registrar cancelamento",
    primaryLabel: "Confirmar cancelamento",
    secondaryLabel: "Cancelar",
    returnFocusEl: getAdminStudentSheet()?.querySelector('[data-admin-student-lifecycle-action="register_cancel"]') || null,
    bodyHtml: `
      <div class="admin-student-lifecycle-modal">
        <label class="admin-student-lifecycle-modal-field">
          <span>Data do pedido</span>
          <input type="date" data-admin-student-cancel-date value="${escapeHtml(createDateKey(new Date()))}" />
        </label>
        ${
          firstLessonValue
            ? `<div class="admin-student-lifecycle-modal-hint">Primeira aula encontrada: <strong>${escapeHtml(formatAdminDate(firstLessonValue))}</strong></div>`
            : `
              <label class="admin-student-lifecycle-modal-field">
                <span>Data da primeira aula (opcional)</span>
                <input type="date" data-admin-student-first-lesson-date value="" />
              </label>
            `
        }
        <label class="admin-student-lifecycle-modal-field">
          <span>Motivo</span>
          <select data-admin-student-cancel-reason>
            <option value="">Selecione…</option>
            ${STUDENT_CANCELLATION_REASON_OPTIONS.map((reason) => `<option value="${escapeHtml(reason)}">${escapeHtml(reason)}</option>`).join("")}
          </select>
        </label>
        <label class="admin-student-lifecycle-modal-field">
          <span>Detalhe opcional</span>
          <textarea rows="3" data-admin-student-cancel-detail placeholder="Contexto adicional"></textarea>
        </label>
        <div class="admin-student-lifecycle-modal-summary" data-admin-student-cancel-summary>
          Aviso prévio até —. As aulas continuam normalmente até lá.
        </div>
        <div class="admin-student-lifecycle-modal-error" data-admin-student-cancel-error hidden></div>
      </div>
    `,
    onPrimary: () => {
      const dateEl = modalBody?.querySelector("[data-admin-student-cancel-date]");
      const reasonEl = modalBody?.querySelector("[data-admin-student-cancel-reason]");
      const detailEl = modalBody?.querySelector("[data-admin-student-cancel-detail]");
      const firstLessonEl = modalBody?.querySelector("[data-admin-student-first-lesson-date]");
      const errorEl = modalBody?.querySelector("[data-admin-student-cancel-error]");
      const pedidoKey = dateEl instanceof HTMLInputElement ? String(dateEl.value || "").trim() : "";
      const reason = reasonEl instanceof HTMLSelectElement ? String(reasonEl.value || "").trim() : "";
      const detail = detailEl instanceof HTMLTextAreaElement ? String(detailEl.value || "").trim() : "";
      const firstLessonKey = firstLessonValue || (firstLessonEl instanceof HTMLInputElement ? String(firstLessonEl.value || "").trim() : "");
      const setErr = (message) => {
        if (!(errorEl instanceof HTMLElement)) return;
        errorEl.textContent = String(message || "");
        errorEl.hidden = !message;
      };
      if (!isValidDateKey(pedidoKey)) {
        setErr("Selecione uma data de pedido válida.");
        return false;
      }
      if (!reason) {
        setErr("Selecione um motivo para continuar.");
        return false;
      }

      const pedidoDate = parseDateKey(pedidoKey);
      const firstDate = isValidDateKey(firstLessonKey) ? parseDateKey(firstLessonKey) : null;
      const diffMs = pedidoDate && firstDate ? pedidoDate.getTime() - firstDate.getTime() : Number.NaN;
      const isWithin7d = pedidoDate && firstDate && diffMs >= 0 && diffMs <= 7 * 86_400_000;
      const dataFimAvisoDate = isWithin7d && firstDate ? addMonthsPreservingDay(firstDate, 1) : addMonthsPreservingDay(pedidoDate, 2);
      const cancelamento = buildStudentCancellationRecord({
        dataPedido: pedidoDate,
        origem: "pedido",
        motivo: reason,
        motivoDetalhe: detail,
        dataFimAviso: dataFimAvisoDate,
        aulasSuspensas: false,
        eventos: [
          createStudentCancellationHistoryEntry(
            "Pedido registrado",
            `${isWithin7d ? "Janela de 7 dias" : "Aviso prévio"} até ${formatAdminDate(dataFimAvisoDate)}`
          ),
        ],
      });

      if (modalPrimary) modalPrimary.disabled = true;
      if (modalSecondary) modalSecondary.disabled = true;
      (async () => {
        try {
          await saveAdminStudentLifecyclePatch({ alunoId: id, patch: { cancelamento } });
          rerenderAdminStudentLifecycleViews();
          closeModal();
        } catch (error) {
          console.error("[Cancellation] submit failed", {
            error,
            code: error?.code,
            message: error?.message,
            stack: error?.stack,
            studentId: id,
            studentDocId: id,
            cancellationPayload: cancelamento,
          });
          setErr(`Não foi possível registrar o cancelamento agora.\nErro: ${error?.code || error?.message || "unknown_error"}\nEtapa: ${error?.cancellationStage || "?"}`);
          if (modalPrimary) modalPrimary.disabled = false;
          if (modalSecondary) modalSecondary.disabled = false;
        }
      })();
      return false;
    },
  });

  window.setTimeout(() => {
    const dateEl = modalBody?.querySelector("[data-admin-student-cancel-date]");
    const firstLessonEl = modalBody?.querySelector("[data-admin-student-first-lesson-date]");
    const summaryEl = modalBody?.querySelector("[data-admin-student-cancel-summary]");
    const syncSummary = () => {
      if (!(summaryEl instanceof HTMLElement) || !(dateEl instanceof HTMLInputElement)) return;
      const pedidoDate = parseDateKey(String(dateEl.value || "").trim());
      const firstDate = firstLessonValue
        ? parseDateKey(firstLessonValue)
        : firstLessonEl instanceof HTMLInputElement && isValidDateKey(firstLessonEl.value)
          ? parseDateKey(firstLessonEl.value)
          : null;
      if (!(pedidoDate instanceof Date) || Number.isNaN(pedidoDate.getTime())) {
        summaryEl.textContent = "Aviso prévio até —. As aulas continuam normalmente até lá.";
        return;
      }
      const diffMs = firstDate instanceof Date ? pedidoDate.getTime() - firstDate.getTime() : Number.NaN;
      const isWithin7d = firstDate instanceof Date && diffMs >= 0 && diffMs <= 7 * 86_400_000;
      const endDate = isWithin7d && firstDate ? addMonthsPreservingDay(firstDate, 1) : addMonthsPreservingDay(pedidoDate, 2);
      summaryEl.textContent = isWithin7d
        ? `Cancelamento em até 7 dias da primeira aula: sem aviso prévio, aulas até ${formatAdminDate(endDate)}.`
        : `Aviso prévio até ${formatAdminDate(endDate)}. As aulas continuam normalmente até lá.`;
    };
    dateEl?.addEventListener("input", syncSummary);
    firstLessonEl?.addEventListener("input", syncSummary);
    syncSummary();
  }, 0);
};

